window.C1_DATA={"course":{"title":"Deutsch C1","subtitle":"Türkçe → Almanca · Deutsch-Test für den Beruf C1","version":"c1-14-compact-progress","lessonCount":40},"lessons":[{"id":1,"unit":"C1 temeli","title":"C1 düzeyi ve DTB C1 sınav stratejisi","skills":["Strateji","Okuma","Dinleme"],"goal":"C1 düzeyindeki dil beklentilerini Deutsch-Test für den Beruf C1’in işyeri odaklı görevleriyle ilişkilendirmek.","explanation":"C1 düzeyinde amaç yalnızca ileri dilbilgisi değildir: uzun ve yoğun metinleri anlamak, örtük anlamı yakalamak, resmî ve yarı resmî kayıtları yönetmek, işyerinde sorun çözmek, bilgiyi başka bir kişiye aktarmak ve düşünceyi ikna edici biçimde yapılandırmak gerekir. Hedef sınav Deutsch-Test für den Beruf C1 olduğu için bu kursta özellikle işyeri iletişimi, arabuluculuk/aktarım (Mediation), müşteri yazışmaları, telefon notları, toplantı dili ve çözüm odaklı konuşma öne çıkar.","examples":[["Die Lieferverzögerung lässt sich voraussichtlich bis Freitag beheben.","Teslimat gecikmesi muhtemelen cuma gününe kadar giderilebilir.","İşyerinde temkinli ve çözüm odaklı ifade."],["Ich fasse kurz zusammen, was der Kunde telefonisch mitgeteilt hat.","Müşterinin telefonda ilettiklerini kısaca özetliyorum.","DTB’de önemli olan bilgi aktarımı / Mediation."]],"quiz":[{"q":"DTB C1’de hangi alan özellikle önemlidir?","o":["Yalnızca akademik makale yazmak","İşyeri bağlamında bilgiyi anlayıp uygun biçimde aktarmak ve çözüm üretmek","Sadece tek tek kelime ezberlemek"],"a":1,"why":"Sınav genel mesleki Almancayı, işyeri iletişimini ve bazı görevlerde Mediation/aktarım becerisini ölçer."},{"q":"C1 düzeyinde iyi bir çalışma yaklaşımı hangisidir?","o":["Kalıpları bağlamdan bağımsız ezberlemek","Dilbilgisi, kelime, kayıt ve iletişim işlevlerini gerçek işyeri görevleri içinde birleştirmek","Yalnızca çoktan seçmeli soru çözmek"],"a":1,"why":"Üretim ve etkileşim görevleri dil araçlarının bağlam içinde kullanılmasını gerektirir."}],"activities":[{"id":"format","type":"mc","title":"DTB C1 yapısını tanı","intro":"Bu bölüm, kursun neden yalnızca gramerden oluşmadığını gösterir.","questions":[{"q":"DTB C1 yazılı sınavında hangi kombinasyon doğrudur?","o":["Sadece Lesen, Hören ve Schreiben","Lesen + Lesen/Schreiben + Hören + Hören/Schreiben + Sprachbausteine/Schreiben","Sadece Sprachbausteine ve Sprechen"],"a":1,"why":"Yazılı sınav, becerileri yer yer birleştiren beş bölümden oluşur."},{"q":"Sözlü sınav için hazırlık süresi nasıldır?","o":["20 dakika","10 dakika","Hazırlık süresi yoktur"],"a":2,"why":"DTB C1 sözlü sınavı hazırlıksız yapılır."},{"q":"Toplam kaç puan vardır?","o":["100","240","300"],"a":1,"why":"Her beceri 60 puan; toplam 240 puan."},{"q":"Geçmek için toplam asgari puan kaçtır?","o":["120","144","180"],"a":1,"why":"Toplamın %60’ı = 144 puan."},{"q":"Hangi görev Mediation/bilgi aktarımını açıkça çalıştırır?","o":["Telefon mesajından meslektaşa not çıkarmak","Sadece fiil çekimi yapmak","Tek kelime eşanlamlısı seçmek"],"a":0,"why":"Hören und Schreiben, duyulan bilgiyi hedef alıcıya aktarır."},{"q":"DTB C1 neyi ölçer?","o":["Belirli bir mesleğin uzmanlık terminolojisini","Genel işyeri bağlamında uygun Almanca iletişim kurma becerisini","Sadece üniversite derslerini izleme becerisini"],"a":1,"why":"Sınav genel mesleki/işyeri odaklı Almancayı ölçer."}]},{"id":"skills","type":"match","title":"Beceri → sınav davranışı","intro":"","prompts":["Lesen","Hören","Schreiben","Sprechen"],"options":["Yoğun işyeri metninde doğru bilgiyi seçmek","Tek dinlemede niyet/eylem/ana argümanı yakalamak","Adresata uygun e-posta ve gerekçeli Stellungnahme üretmek","Hazırlıksız anlatmak, soruya cevap vermek ve ortak çözüm geliştirmek"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"3–5 cümlede DTB C1’in hangi becerileri ölçtüğünü ve senin için en zor alanı yaz.","target":"En az iki sınav bileşenini doğru adlandır ve bir çalışma önceliği belirt.","example":"Der DTB C1 prüft arbeitsplatzbezogenes Lesen, Hören, Schreiben und Sprechen. Besonders anspruchsvoll finde ich die integrierten Aufgaben, weil Informationen nicht nur verstanden, sondern weitergegeben werden müssen. Deshalb möchte ich vor allem Mediation und spontanes Sprechen trainieren.","mode":"write","minChars":60,"checklist":[]}},{"id":2,"unit":"C1 temeli","title":"Metin örgüsü: gönderim ve bağdaşıklık","skills":["Okuma","Yazma"],"goal":"Uzun metinlerde zamir, gönderim ve bağlayıcıların neye işaret ettiğini izlemek.","explanation":"C1 okuma sorularında doğru cevap çoğu zaman tek bir cümlede değildir. “dies”, “dabei”, “dadurch”, “Letzteres”, “ein solcher Ansatz” gibi ifadeler önceki bilgiyi yeniden paketler. Yazarken de aynı ismi tekrar etmek yerine kontrollü gönderim kullanmak metni daha olgun gösterir.","examples":[["Viele Hochschulen führen hybride Formate ein. Dadurch können auch Berufstätige teilnehmen.","Birçok üniversite hibrit format getiriyor. Böylece çalışanlar da katılabiliyor.","“Dadurch” önceki eylemin sonucunu kurar."],["Es gibt zwei Modelle: Präsenzpflicht und freie Teilnahme. Letzteres bietet mehr Flexibilität.","İki model var: zorunlu yüz yüze ve serbest katılım. İkincisi daha fazla esneklik sunar.","“Letzteres” ikinci unsura gönderme yapar."]],"quiz":[{"q":"“Letzteres” hangi unsura gönderme yapar?","o":["İlk söylenene","Son söylenene","Bütün paragrafa"],"a":1,"why":"Letzteres = sonuncu / ikinci anılan unsur."},{"q":"“Dadurch” en sık hangi ilişkiyi kurar?","o":["Sonuç / araç","Zaman","Alıntı"],"a":0,"why":"Dadurch, önceki durumdan doğan sonucu veya aracı belirtir."}],"activities":[{"id":"cohesion-mc","type":"mc","title":"Bağdaşıklık sinyallerini çöz","intro":"","questions":[{"q":"Taviz: ___ die Stichprobe klein ist, sind die Ergebnisse relevant.","o":["Wenngleich","Folglich","Dadurch","Zumal"],"a":0,"why":"Wenngleich = her ne kadar."},{"q":"Sonuç: Die Nachfrage sank. ___ wurde das Angebot reduziert.","o":["Folglich","Wenngleich","Indem","Während"],"a":0,"why":"Folglich = bunun sonucunda."},{"q":"Karşılaştırmalı karşıtlık: Gruppe A profitiert. ___ entstehen Gruppe B Nachteile.","o":["Demgegenüber","Infolgedessen","Daher","Somit"],"a":0,"why":"Demgegenüber iki grubu karşı karşıya getirir."},{"q":"Koşul: Die Regel gilt, ___ keine Ausnahme genehmigt wird.","o":["sofern","obwohl","zumal","wodurch"],"a":0,"why":"sofern = şu koşulla ki/eğer."},{"q":"Ek gerekçe: Die Maßnahme ist teuer, ___ ihr Nutzen unklar ist.","o":["zumal","folglich","hingegen","indem"],"a":0,"why":"zumal ek/kuvvetlendirici gerekçe verir."},{"q":"Araç/yöntem: Man senkt Kosten, ___ man Prozesse automatisiert.","o":["indem","obwohl","sofern","während dagegen"],"a":0,"why":"indem = nasıl/yöntem."},{"q":"Gönderim: Es wurden zwei Modelle getestet. ___ erwies sich als robuster.","o":["Letzteres","Folglich","Wenngleich","Daher dass"],"a":0,"why":"Letzteres ikinci modele gider."},{"q":"“Nichtsdestotrotz” hangi ilişkiyi verir?","o":["Taviz/karşıtlık","Amaç","Zaman","Koşul"],"a":0,"why":"Beklenen sonuca rağmen karşıt durum."}]},{"id":"referenz","type":"match","title":"Gönderim ifadesi → işlev","intro":"","prompts":["dadurch","dabei","letzteres","ein solcher Ansatz"],"options":["önceki durumun sonucu/araç ilişkisi","aynı süreç içindeki eşzamanlı/ilişkili yön","son anılan unsur","önceden tanımlanan yaklaşım/model"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"3–5 cümlelik paragrafta dadurch, dabei veya letzteres gibi en az iki gönderim aracı kullan.","target":"Gönderimin neye referans verdiği açık olmalı.","example":"Das Team prüft zwei Modelle: feste Präsenztage und flexible Anwesenheit. Letzteres bietet mehr Spielraum. Dadurch kann die Planung besser an unterschiedliche Aufgaben angepasst werden.","mode":"write","minChars":60,"checklist":[]}},{"id":3,"unit":"C1 temeli","title":"Argümantasyon ve bağlaçlar","skills":["Yazma","Konuşma"],"goal":"Karşıtlık, neden, sonuç, taviz ve sınırlama ilişkilerini hassas biçimde kurmak.","explanation":"C1 metinlerinde “aber” ve “weil” tek başına yeterli değildir. İlişkiyi doğru türde kurmak gerekir: “zwar … jedoch”, “wenngleich”, “insofern als”, “folglich”, “demgegenüber”, “unter der Voraussetzung, dass”. Bağlaç çeşitliliği ancak anlam doğruysa puan getirir.","examples":[["Wenngleich die Datenbasis klein ist, sind die Ergebnisse bemerkenswert.","Veri tabanı küçük olmakla birlikte sonuçlar dikkat çekicidir.","Taviz ilişkisi."],["Die Nachfrage sank deutlich; folglich wurde das Angebot reduziert.","Talep belirgin biçimde düştü; bunun sonucunda arz azaltıldı.","Sonuç ilişkisi."]],"quiz":[{"q":"Hangi bağlaç taviz (concession) bildirir?","o":["folglich","wenngleich","infolgedessen"],"a":1,"why":"Wenngleich = her ne kadar / olsa da."},{"q":"“demgegenüber” en uygun hangi işlevdedir?","o":["Karşılaştırmalı karşıtlık","Sebep","Amaç"],"a":0,"why":"Demgegenüber iki görüş veya olguyu karşı karşıya getirir."}],"activities":[{"id":"argument","type":"mc","title":"Argümantasyon ilişkileri","intro":"","questions":[{"q":"___ die Umstellung teuer ist, kann sie sich langfristig lohnen.","o":["Wenngleich","Folglich","Dadurch"],"a":0,"why":"Wenngleich taviz bildirir."},{"q":"Die Reklamationen nahmen zu. ___ wurde der Prüfprozess verschärft.","o":["Demgegenüber","Folglich","Während"],"a":1,"why":"Folglich sonuç bildirir."},{"q":"Die Produktion bevorzugt Standardisierung. ___ fordert der Vertrieb mehr Flexibilität.","o":["Demgegenüber","Zumal","Infolgedessen"],"a":0,"why":"İki görüş karşı karşıya getirilir."},{"q":"Wir können den Termin halten, ___ der Lieferant heute bestätigt.","o":["unter der Voraussetzung, dass","wenngleich","infolgedessen"],"a":0,"why":"Koşul ifade edilir."},{"q":"Die Lösung ist sinnvoll, ___ sie kurzfristig mehr Aufwand verursacht.","o":["obwohl","dadurch","folglich"],"a":0,"why":"Karşıt/taviz ilişkisi."},{"q":"Welche Formulierung klingt C1-gerecht und präzise?","o":["Das ist gut, weil gut.","Zwar erhöht die Maßnahme den Aufwand, langfristig verbessert sie jedoch die Qualität.","Es ist halt so."],"a":1,"why":"İlişki açık ve nüanslı kurulmuştur."}]},{"id":"relations","type":"match","title":"Bağlayıcı → ilişki","intro":"","prompts":["wenngleich","folglich","demgegenüber","unter der Voraussetzung, dass","zumal"],"options":["taviz","sonuç","karşıtlık","koşul","ek gerekçe/vurgu"],"answers":[0,1,2,3,4],"why":[]}],"production":{"task":"Bir işyeri görüşünü 4–6 cümlede savun ve karşıt görüşe de yer ver.","target":"En az bir taviz ve bir sonuç bağlayıcısı kullan.","example":"Zwar kostet die Umstellung zunächst Zeit, langfristig verbessert sie jedoch die Abläufe. Wenngleich nicht alle Mitarbeitenden überzeugt sind, sollte das Modell getestet werden. Folglich wäre ein begrenzter Pilotversuch sinnvoll.","mode":"write","minChars":60,"checklist":[]}},{"id":4,"unit":"C1 temeli","title":"Parafraz ve anlam inceliği","skills":["Okuma","Yazma"],"goal":"Aynı fikri farklı sözcük ve yapılarla, anlamı bozmadan yeniden ifade etmek.","explanation":"Goethe ve telc C1’de seçenekler metindeki ifadeyi çoğu zaman aynen tekrar etmez. “zurückgehen auf” ile “bedingt sein durch”, “in Betracht ziehen” ile “berücksichtigen”, “kaum zu überschätzen” ile “von großer Bedeutung sein” arasındaki ilişkiyi görmek gerekir. Üretimde de aynı sözcüğü tekrar etmek yerine kontrollü parafraz kullan.","examples":[["Der Rückgang ist auf mehrere Faktoren zurückzuführen.","Düşüş birden fazla faktöre bağlanabilir.","Nedensellik parafrazı."],["Diese Entwicklung darf nicht außer Acht gelassen werden.","Bu gelişme göz ardı edilmemelidir.","Resmî/akademik ifade."]],"quiz":[{"q":"“etwas in Betracht ziehen” en yakın hangi anlama gelir?","o":["etwas ablehnen","etwas berücksichtigen","etwas beweisen"],"a":1,"why":"Her ikisi de bir unsuru değerlendirmeye katmak demektir."},{"q":"“nicht außer Acht lassen” ne demektir?","o":["göz ardı etmemek","reddetmek","abartmak"],"a":0,"why":"Bir faktörü dikkate almaya devam etmek anlamındadır."}],"activities":[{"id":"para-mc","type":"mc","title":"Parafrazı tanı","intro":"","questions":[{"q":"“berücksichtigen” ≈","o":["in Betracht ziehen","verwerfen","bestreiten","verschweigen"],"a":0,"why":"İkisi de değerlendirmeye katmak."},{"q":"“auf etwas zurückzuführen sein” ≈","o":["durch etwas bedingt sein","etwas verhindern","etwas verbergen","etwas beschleunigen"],"a":0,"why":"Nedeni belirtir."},{"q":"“von großer Bedeutung” ≈","o":["maßgeblich","belanglos","zufällig","überflüssig"],"a":0,"why":"maßgeblich = önemli/belirleyici."},{"q":"“etwas außer Acht lassen” ≈","o":["etwas ignorieren","etwas fördern","etwas belegen","etwas erweitern"],"a":0,"why":"Göz ardı etmek."},{"q":"“einen Einwand erheben” ≈","o":["widersprechen","zustimmen","abschließen","zusammenfassen"],"a":0,"why":"İtiraz etmek."},{"q":"“sich als tragfähig erweisen” ≈","o":["funktionieren / belastbar sein","scheitern","verboten sein","unverständlich sein"],"a":0,"why":"Uygulanabilir/sağlam çıkmak."},{"q":"“die These untermauern” ≈","o":["die These stützen","die These vergessen","die These vermeiden","die These abschwächen"],"a":0,"why":"Kanıt/argümanla desteklemek."},{"q":"“eine Entwicklung zeichnet sich ab” ≈","o":["eine Entwicklung wird erkennbar","alles bleibt gleich","etwas wird verboten","etwas endet sofort"],"a":0,"why":"Bir eğilim görünür hale gelir."}]},{"id":"para-pairs","type":"match","title":"İfade → eşdeğer anlam","intro":"","prompts":["etwas berücksichtigen","auf mehrere Faktoren zurückzuführen sein","nicht außer Acht lassen","eine Rolle spielen"],"options":["etwas in Betracht ziehen","durch mehrere Faktoren bedingt sein","berücksichtigen / nicht ignorieren","von Bedeutung sein"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Aynı işyeri fikrini iki farklı yapıyla ifade et.","target":"Eşanlamlı veya farklı gramer yapısı kullan; anlam aynı kalsın.","example":"Die Maßnahme verursacht erhebliche Kosten. Anders ausgedrückt: Das Unternehmen müsste dafür deutlich mehr Geld einplanen.","mode":"write","minChars":60,"checklist":[]}},{"id":5,"unit":"C1 temeli","title":"Kayıt ve üslup: resmî, nötr, konuşma dili","skills":["Yazma","Konuşma"],"goal":"Duruma göre uygun kayıt seçmek ve üslup kırılmalarını önlemek.","explanation":"C1’de yalnızca doğru cümle kurmak değil, cümlenin bağlama uygun olması beklenir. Bir foruma “Meines Erachtens …” ile yazılabilir; yarı resmî e-postada “Ich möchte Sie darauf aufmerksam machen, dass …” uygundur. “Das ist total blöd” gibi ifadeler resmî bağlamda uygun değildir.","examples":[["Ich möchte Sie darauf aufmerksam machen, dass die vereinbarte Frist bereits abgelaufen ist.","Kararlaştırılan sürenin dolduğuna dikkatinizi çekmek isterim.","Yarı resmî/resmî."],["Aus meiner Sicht überwiegen die Vorteile.","Bana göre avantajlar ağır basıyor.","Nötr argümantatif kayıt."]],"quiz":[{"q":"Bir iş e-postasında en uygun ifade hangisidir?","o":["Das nervt echt.","Ich möchte Sie auf ein Problem aufmerksam machen.","Krass, das geht gar nicht."],"a":1,"why":"Duruma uygun, nazik ve açık bir kayıt kullanır."},{"q":"“Meines Erachtens” hangi işlevi görür?","o":["Görüş belirtme","Özür dileme","Alıntı yapma"],"a":0,"why":"Resmî/nötr biçimde kişisel görüş belirtir."}],"activities":[{"id":"register-mc","type":"mc","title":"Kayıt seçimi","intro":"","questions":[{"q":"Yarı resmî e-posta için en uygun ifade?","o":["Das ist echt Mist.","Ich möchte Sie auf eine Unstimmigkeit aufmerksam machen.","Ey, könnt ihr das fixen?","Mega nervig."],"a":1,"why":"Nazik, açık ve profesyonel kayıt."},{"q":"Akademik temkinli ifade?","o":["Das beweist hundertprozentig …","Die Befunde legen nahe, dass …","Jeder weiß, dass …","Ganz klar …"],"a":1,"why":"“legen nahe” kanıt derecesini uygun tutar."},{"q":"Tartışmada kibar itiraz?","o":["Unsinn.","Ich sehe den Punkt, allerdings …","Falsch!","Quatsch."],"a":1,"why":"Partneradäquat ve etkileşimli."},{"q":"Resmî öneri?","o":["Mach doch einfach …","Als mögliche Lösung schlage ich vor, …","Du musst halt …","Easy: …"],"a":1,"why":"Uygun register."},{"q":"Nötr görüş belirtme?","o":["Meines Erachtens …","Ich schwöre …","Voll krass …","Safe …"],"a":0,"why":"Nötr/resmî argümantasyon."},{"q":"Resmî talep?","o":["Wäre es möglich, …?","Gib mir …","Los, mach …","Kannste …?"],"a":0,"why":"Nazik ve uygun."},{"q":"Akademik sınırlama?","o":["Dies gilt allerdings nur unter der Voraussetzung, dass …","Das gilt immer.","Keine Ahnung, aber …","Ist halt so."],"a":0,"why":"Koşulu açıklar."},{"q":"Sunum geçişi?","o":["Jetzt mal egal.","Damit komme ich zum zweiten Aspekt.","Whatever.","Und so."],"a":1,"why":"Dinleyiciye yapı sinyali verir."}]},{"id":"register-map","type":"match","title":"Durum → uygun kayıt","intro":"","prompts":["yakın iş arkadaşıyla mola sohbeti","müşteriye şikâyet yanıtı","yönetime Stellungnahme","telefon notu"],"options":["informel ama anlaşılır","nazik ve profesyonel","nötr-resmî ve argümantatif","kısa, yoğun, eylem odaklı"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Resmî bir iş e-postası için 4–5 cümle yaz.","target":"Nazik, mesafeli ve profesyonel kayıt; konuşma dili yok.","example":"Ich möchte Sie darauf aufmerksam machen, dass die vereinbarte Frist bereits abgelaufen ist. Dennoch bin ich zuversichtlich, dass wir gemeinsam eine Lösung finden können. Bitte teilen Sie mir kurz mit, wie Sie weiter vorgehen möchten.","mode":"write","minChars":60,"checklist":[]}},{"id":6,"unit":"C1 temeli","title":"Eşdizimler ve işlevsel fiil yapıları","skills":["Kelime","Yazma","Okuma"],"goal":"Tek tek kelime yerine doğal sözcük birliklerini ve akademik kalıpları kullanmak.","explanation":"C1’de sözcük bilgisi “çok kelime bilmekten” çok, doğru kelimeleri birlikte kullanabilmektir. “eine Entscheidung treffen”, “in Kraft treten”, “zur Verfügung stehen”, “Kritik üben”, “Maßnahmen ergreifen” gibi kalıplar doğal ve yoğun bir anlatım sağlar.","examples":[["Die Universität ergreift Maßnahmen gegen Prüfungsbetrug.","Üniversite sınav hilesine karşı önlemler alıyor.","“Maßnahmen ergreifen” sabit eşdizim."],["Die neue Regelung tritt im Januar in Kraft.","Yeni düzenleme ocakta yürürlüğe giriyor.","“in Kraft treten” sabit kalıp."]],"quiz":[{"q":"Doğal eşdizim hangisidir?","o":["eine Entscheidung machen","eine Entscheidung treffen","eine Entscheidung bauen"],"a":1,"why":"Standart Nomen-Verb-Verbindung “eine Entscheidung treffen”dir."},{"q":"“Kritik üben an” ne demektir?","o":["eleştirmek","desteklemek","erteleme yapmak"],"a":0,"why":"Bir konu veya kişiyi eleştirmek anlamındadır."}],"activities":[{"id":"colloc-mc","type":"mc","title":"Doğal eşdizimler","intro":"","questions":[{"q":"eine Schlussfolgerung ___","o":["ziehen","machen","bauen","stellen"],"a":0,"why":"eine Schlussfolgerung ziehen."},{"q":"eine Maßnahme ___","o":["ergreifen","schreiben","legen","laufen"],"a":0,"why":"Maßnahmen ergreifen."},{"q":"zur Debatte ___","o":["stehen","laufen","ziehen","fallen immer"],"a":0,"why":"zur Debatte stehen."},{"q":"einen Zusammenhang ___","o":["herstellen","kochen","setzen","laufen"],"a":0,"why":"einen Zusammenhang herstellen."},{"q":"eine Annahme ___","o":["in Frage stellen","ins Haus bringen","zu Fuß setzen","in Kraft machen"],"a":0,"why":"eine Annahme in Frage stellen."},{"q":"Verantwortung ___","o":["übernehmen","nehmen auf","machen","bauen"],"a":0,"why":"Verantwortung übernehmen."},{"q":"einen Antrag ___","o":["stellen","setzen","machen immer","ziehen"],"a":0,"why":"einen Antrag stellen."},{"q":"unter Druck ___","o":["geraten","kommen zu","ziehen","leisten"],"a":0,"why":"unter Druck geraten/stehen."}]},{"id":"colloc-map","type":"match","title":"İsim → doğal fiil","intro":"","prompts":["eine Entscheidung","Maßnahmen","Kritik","zur Verfügung","eine Schlussfolgerung"],"options":["treffen","ergreifen","üben","stehen","ziehen"],"answers":[0,1,2,3,4],"why":[]}],"production":{"task":"4–6 cümlede en az üç doğal C1 eşdizimi kullan.","target":"Örn. Entscheidung treffen, Maßnahmen ergreifen, zur Verfügung stehen.","example":"Die Geschäftsleitung muss zeitnah eine Entscheidung treffen. Um weitere Verzögerungen zu vermeiden, sollten wir konkrete Maßnahmen ergreifen. Dafür stehen bereits zusätzliche Ressourcen zur Verfügung.","mode":"write","minChars":60,"checklist":[]}},{"id":7,"unit":"C1 dilbilgisi","title":"Süreç edilgeni (Vorgangspassiv): süreç ve perspektif","skills":["Dilbilgisi","Yazma"],"goal":"Vorgangspassiv’i tüm temel zamanlarda ve farklı cümle türlerinde güvenli kullanmak.","explanation":"Vorgangspassiv “werden + Partizip II” ile bir sürece odaklanır. Fail gerekirse “von + Dativ” veya özellikle sebep/araç için “durch + Akkusativ” ile verilir. Perfektte “ist … worden” kullanılır; “geworden” değil.","examples":[["Die Ergebnisse werden morgen veröffentlicht.","Sonuçlar yarın yayımlanacak.","Präsens pasif."],["Die Daten sind mehrfach überprüft worden.","Veriler birkaç kez kontrol edildi.","Perfekt pasif."]],"quiz":[{"q":"Doğru Perfekt-Passiv hangisidir?","o":["Die Daten sind geprüft geworden.","Die Daten sind geprüft worden.","Die Daten haben geprüft worden."],"a":1,"why":"Vorgangspassiv Perfekt: sein + Partizip II + worden."},{"q":"“durch” en çok ne zaman uygundur?","o":["İnsan faili belirtirken her zaman","Nedensel/araçsal bir etkeni belirtirken","Zaman belirtirken"],"a":1,"why":"Örn. “durch einen Fehler verursacht”."}],"activities":[{"id":"passiv-mc","type":"mc","title":"Vorgangspassiv","intro":"","questions":[{"q":"Die Kommission ___ den Antrag gestern ___.","o":["hat / abgelehnt","ist / abgelehnt worden","wurde / abgelehnt worden","war / ablehnen"],"a":1,"why":"Perfekt Vorgangspassiv: ist + Partizip II + worden."},{"q":"Aktiv: Man diskutiert über die Folgen. Doğru Passiv?","o":["Die Folgen werden diskutiert über.","Über die Folgen wird diskutiert.","Über die Folgen werden diskutiert.","Es diskutiert über die Folgen."],"a":1,"why":"Akkusativ nesnesi olmadığı için öznesiz pasif; fiil tekil."},{"q":"“Die Tür ist geschlossen.” neyi vurgular?","o":["Kapanma sürecini","Ortaya çıkmış durumu","Failin kim olduğunu","Geleceği"],"a":1,"why":"sein + Partizip II = Zustandspassiv."},{"q":"Das Gebäude wurde ___ ein Erdbeben beschädigt.","o":["von","durch","mit","bei"],"a":1,"why":"Nedensel/araçsal etken için “durch + Akk.” uygundur."},{"q":"Welche Form ist korrekt?","o":["Die Daten sind geprüft geworden.","Die Daten sind geprüft worden.","Die Daten haben geprüft worden.","Die Daten wurden geprüft gewesen."],"a":1,"why":"Perfekt Passiv’te “worden” kullanılır."},{"q":"Niemand hat eine Lösung gefunden. →","o":["Keine Lösung ist gefunden.","Es wurde keine Lösung gefunden.","Keine Lösung wurde finden.","Niemand wurde eine Lösung gefunden."],"a":1,"why":"Niemand çoğu zaman pasifte olumsuzlukla ifade edilir."},{"q":"Der Antrag ___ bereits genehmigt; wir warten nur auf die Zustellung.","o":["wird","ist","wurde gerade","würde"],"a":1,"why":"Burada sonuç durumu vurgulanıyor."},{"q":"Man half den Betroffenen sofort. →","o":["Die Betroffenen wurden sofort geholfen.","Den Betroffenen wurde sofort geholfen.","Den Betroffenen wurden sofort geholfen.","Es wurden die Betroffenen geholfen."],"a":1,"why":"helfen Dativ alır; öznesiz pasif tekil “wurde”."}]},{"id":"passiv-tf","type":"tf","title":"Süreç mi, sonuç mu?","intro":"","statements":[{"q":"„Die Daten werden geprüft.“ bir süreç anlatır.","a":true,"why":"werden + Partizip II = Vorgangspassiv."},{"q":"„Die Daten sind geprüft.“ devam eden süreci anlatır.","a":false,"why":"sein + Partizip II çoğunlukla sonuç durumunu anlatır."},{"q":"Perfekt Vorgangspassiv’de „worden“ kullanılır.","a":true,"why":"ist/sind + Partizip II + worden."}]}],"production":{"task":"4–5 cümlede Vorgangspassiv’i iki farklı zamanda kullan.","target":"werden + Partizip II ve Perfektte worden yapısını doğru kur.","example":"Die neuen Richtlinien werden nächste Woche eingeführt. Alle Mitarbeitenden werden vorher informiert. Die wichtigsten Änderungen sind bereits mehrfach geprüft worden.","mode":"write","minChars":60,"checklist":[]}},{"id":8,"unit":"C1 dilbilgisi","title":"Durum edilgeni (Zustandspassiv) ve öznesiz pasif","skills":["Dilbilgisi","Yazma"],"goal":"Sonuç durumu ile süreci ayırmak ve Akkusativobjekt olmadan pasif kurmak.","explanation":"Zustandspassiv “sein + Partizip II” ile ortaya çıkmış durumu anlatır: “Die Tür ist geschlossen.” Süreç “Die Tür wird geschlossen.” şeklindedir. Akkusativ nesnesi olmayan fiillerde de öznesiz pasif mümkündür: “Den Betroffenen wurde geholfen.”","examples":[["Der Antrag ist bereits genehmigt.","Başvuru hâlihazırda onaylanmış durumda.","Durum."],["Über den Vorschlag wurde lange diskutiert.","Öneri uzun süre tartışıldı.","Öznesiz Vorgangspassiv."]],"quiz":[{"q":"Hangisi Zustandspassiv’dir?","o":["Die Tür wird geschlossen.","Die Tür ist geschlossen.","Man schließt die Tür."],"a":1,"why":"sein + Partizip II sonuç durumunu gösterir."},{"q":"Doğru öznesiz pasif hangisidir?","o":["Den Gästen wurden geholfen.","Den Gästen wurde geholfen.","Die Gäste wurde geholfen."],"a":1,"why":"Gizli “es” nedeniyle fiil tekil kalır."}],"activities":[{"id":"zustand","type":"mc","title":"Zustandspassiv ve öznesiz pasif","intro":"","questions":[{"q":"Hangisi Zustandspassiv?","o":["Der Bericht wird geschrieben.","Der Bericht ist geschrieben.","Man schreibt den Bericht."],"a":1,"why":"sein + Partizip II = sonuç durumu."},{"q":"Doğru öznesiz pasif?","o":["Den Kunden wurden geholfen.","Den Kunden wurde geholfen.","Die Kunden wurde geholfen."],"a":1,"why":"Dativ nesne özne olmaz; fiil tekil kalır."},{"q":"„Über die Änderung wurde diskutiert.“ neden mümkündür?","o":["Fiil Akkusativ nesnesi gerektirmez ama öznesiz pasif kurulabilir.","„diskutieren“ her zaman geçişlidir.","Bu cümle pasif değildir."],"a":0,"why":"Almancada geçişsiz fiillerle öznesiz pasif mümkündür."},{"q":"Süreç → sonuç sırası hangisidir?","o":["ist geschlossen → wird geschlossen","wird geschlossen → ist geschlossen","hat geschlossen → wird geschlossen"],"a":1,"why":"Önce kapanma süreci, sonra kapalı durum."}]},{"id":"passive-use","type":"match","title":"Yapı → tip","intro":"","prompts":["wird geliefert","ist geliefert","wurde geholfen","ist geliefert worden"],"options":["Vorgangspassiv Präsens","Zustandspassiv","öznesiz Passiv","Vorgangspassiv Perfekt"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Süreç ve sonuç durumunu 4–5 cümlede karşılaştır.","target":"Vorgangspassiv + Zustandspassiv + mümkünse öznesiz pasif.","example":"Die Anlage wird gerade gewartet. Am Nachmittag ist sie wieder betriebsbereit. Während der Wartung wird im Ersatzbereich gearbeitet.","mode":"write","minChars":60,"checklist":[]}},{"id":9,"unit":"C1 dilbilgisi","title":"İsim-fiil birleşimleri (Nomen-Verb-Verbindungen)","skills":["Dilbilgisi","Kelime"],"goal":"Serbest Nomen-Verb-Verbindungen ile Funktionsverbgefüge’yi tanımak ve kullanmak.","explanation":"C1’de birçok soyut eylem ad + fiil kalıbıyla ifade edilir. Bazıları gerçek anlamlıdır (“eine Frage stellen”), bazıları işlevsel fiil yapısıdır (“zur Sprache bringen”, “in Erwägung ziehen”). Bunlar özellikle resmî ve akademik metinlerde sık görülür.","examples":[["Der Vorschlag kam erneut zur Sprache.","Öneri tekrar gündeme geldi.","Funktionsverbgefüge."],["Wir ziehen eine Verlängerung der Frist in Erwägung.","Süre uzatımını değerlendiriyoruz.","Resmî ifade."]],"quiz":[{"q":"“in Erwägung ziehen” ne demektir?","o":["göz önünde bulundurmak","reddetmek","yasaklamak"],"a":0,"why":"Bir seçeneği ciddi biçimde değerlendirmeye almak."},{"q":"Doğal kalıp hangisidir?","o":["Kritik machen","Kritik üben","Kritik nehmen"],"a":1,"why":"Standart kalıp “Kritik üben (an + Dat.)”."}],"activities":[{"id":"nvv-mc","type":"mc","title":"Nomen-Verb-Verbindungen","intro":"","questions":[{"q":"eine Entscheidung ___","o":["machen","treffen","tun","setzen"],"a":1,"why":"Standart eşdizim: eine Entscheidung treffen."},{"q":"Kritik ___ an der Reform","o":["üben","machen","stellen","geben"],"a":0,"why":"Kritik an etwas üben."},{"q":"etwas in Erwägung ___","o":["bringen","ziehen","nehmen","führen"],"a":1,"why":"in Erwägung ziehen = değerlendirmek."},{"q":"zur Verfügung ___","o":["sein/stehen","machen","ziehen","setzen"],"a":0,"why":"zur Verfügung stehen / stellen."},{"q":"in Kraft ___","o":["kommen","treten","gehen","laufen"],"a":1,"why":"in Kraft treten = yürürlüğe girmek."},{"q":"Maßnahmen ___","o":["ergreifen","nehmen","leisten","stellen"],"a":0,"why":"Maßnahmen ergreifen = önlem almak."},{"q":"eine Frage zur Sprache ___","o":["bringen","ziehen","treffen","halten"],"a":0,"why":"zur Sprache bringen = gündeme getirmek."},{"q":"einen Beitrag zu etwas ___","o":["leisten","machen","setzen","führen"],"a":0,"why":"einen Beitrag leisten."}]},{"id":"nvv-rephrase","type":"match","title":"NVV → basit fiil","intro":"","prompts":["eine Entscheidung treffen","Kritik üben","zur Verfügung stellen","in Erwägung ziehen"],"options":["entscheiden","kritisieren","bereitstellen","erwägen"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"En az iki Nomen-Verb-Verbindung kullan ve birini basit fiille parafraz et.","target":"NVV’yi doğal bağlamda kullan.","example":"Die Leitung hat eine Entscheidung getroffen. Anders ausgedrückt: Sie hat entschieden, das Projekt fortzusetzen. Gleichzeitig wurde Kritik an der bisherigen Planung geübt.","mode":"write","minChars":60,"checklist":[]}},{"id":10,"unit":"C1 dilbilgisi","title":"Kip fiilleri (Modalverben): nesnel anlamlar","skills":["Dilbilgisi","Yazma"],"goal":"Zorunluluk, izin, olanak, istek ve görev anlamlarını doğru modal fiille aktarmak.","explanation":"Nesnel kullanımda modalite özne ve eyleme ilişkindir: “müssen” zorunluluk, “dürfen” izin/yasak, “können” yetenek/olanak, “sollen” görev/beklenti, “wollen” niyet bildirir. Perfektte Ersatzinfinitiv görülür: “hat teilnehmen können”.","examples":[["Die Teilnehmenden müssen sich vorher anmelden.","Katılımcılar önceden kayıt olmak zorunda.","Zorunluluk."],["Wir haben die Frist verlängern können.","Süreyi uzatabildik.","Ersatzinfinitiv."]],"quiz":[{"q":"“Es ist nicht notwendig” hangi modal yapıyla verilebilir?","o":["nicht müssen","nicht dürfen","sollen"],"a":0,"why":"nicht müssen = zorunlu olmamak; nicht dürfen = yasak olmak."},{"q":"Doğru Perfekt hangisidir?","o":["Wir haben kommen gekonnt.","Wir haben kommen können.","Wir sind kommen können."],"a":1,"why":"Modal fiilde Perfekt çoğunlukla Ersatzinfinitiv kullanır."}],"activities":[{"id":"modal-obj","type":"mc","title":"Modalverben: nesnel kullanım","intro":"","questions":[{"q":"Du ___ hier nicht parken. Es ist verboten.","o":["musst","darfst","kannst","sollst"],"a":1,"why":"nicht dürfen = yasak."},{"q":"Wir ___ die Frist nicht einhalten; es war unmöglich.","o":["durften","konnten","sollten","wollten"],"a":1,"why":"nicht können = olanaksız/yetersiz olmak."},{"q":"Es ist nicht notwendig, dass du kommst. → Du ___ kommen.","o":["darfst nicht","musst nicht","sollst nicht","willst nicht"],"a":1,"why":"nicht müssen = zorunda olmamak."},{"q":"Perfekt: Wir ___ früher abreisen ___.","o":["haben / müssen","sind / gemusst","haben / gemusst","wurden / müssen"],"a":0,"why":"Ersatzinfinitiv: haben + Infinitiv + Modalinfinitiv."},{"q":"Man erwartet von uns, dass wir den Bericht überarbeiten. → Wir ___ den Bericht überarbeiten.","o":["sollen","dürfen","mögen","können"],"a":0,"why":"sollen görev/beklenti aktarır."},{"q":"Er weigert sich zu unterschreiben. → Er ___ nicht unterschreiben.","o":["will","darf","kann","muss"],"a":0,"why":"nicht wollen = isteksizlik/ret."},{"q":"Die Genehmigung erlaubt uns die Nutzung. → Wir ___ das Gebäude nutzen.","o":["dürfen","müssen","sollen","wollen"],"a":0,"why":"dürfen = izin."},{"q":"Sie ist fähig, komplexe Daten zu analysieren. → Sie ___ komplexe Daten analysieren.","o":["soll","kann","darf","muss"],"a":1,"why":"können = yetenek."}]},{"id":"modal-fn","type":"match","title":"Modalite → tipik araç","intro":"","prompts":["zorunluluk","izin","olanak/yetenek","görev/talimat","niyet"],"options":["müssen","dürfen","können","sollen","wollen"],"answers":[0,1,2,3,4],"why":[]}],"production":{"task":"Zorunluluk, izin ve olanağı içeren 4–5 cümle yaz.","target":"müssen/dürfen/können anlamlarını karıştırma.","example":"Die Mitarbeitenden müssen die Sicherheitsregeln beachten. Sie dürfen den Bereich nur mit Ausweis betreten, können Fragen aber jederzeit an die Teamleitung richten.","mode":"write","minChars":60,"checklist":[]}},{"id":11,"unit":"C1 dilbilgisi","title":"Kip fiilleri (Modalverben): öznel anlam ve kanıt derecesi","skills":["Dilbilgisi","Okuma"],"goal":"Tahmin, çıkarım, söylenti ve şüpheli iddia gibi öznel modal anlamları çözmek.","explanation":"C1 metinlerinde modal fiiller kanıt derecesini kodlar. “muss” güçlü çıkarım, “dürfte” olası varsayım, “könnte” zayıf olasılık, “soll” başkasından duyulan bilgi, “will” konuşanın mesafeli yaklaştığı öz iddia anlamına gelebilir.","examples":[["Die Ursache dürfte im veränderten Konsumverhalten liegen.","Neden muhtemelen değişen tüketim davranışında yatıyor.","Olası varsayım."],["Der Minister soll von den Problemen gewusst haben.","Bakanın sorunları bildiği söyleniyor.","İkinci el bilgi/söylenti."]],"quiz":[{"q":"“Er soll davon gewusst haben.” en yakın anlam hangisidir?","o":["Kesin biliyorum.","Duyduğuma göre biliyormuş.","Bilmesi yasaktı."],"a":1,"why":"Öznel “sollen” doğrulanmamış/ikinci el bilgiyi aktarır."},{"q":"En güçlü çıkarım hangisidir?","o":["könnte","dürfte","muss"],"a":2,"why":"Öznel “müssen” konuşanın çok güçlü çıkarımını gösterir."}],"activities":[{"id":"modal-subj","type":"mc","title":"Modalverben: bilgi derecesi","intro":"","questions":[{"q":"Er ___ schon angekommen sein; sein Auto steht draußen. (çok güçlü çıkarım)","o":["könnte","muss","soll","will"],"a":1,"why":"subjektives müssen = güçlü çıkarım."},{"q":"Die Preise ___ nächstes Jahr leicht sinken. (olasılık)","o":["könnten","müssen","wollen","sollen"],"a":0,"why":"könnte = belirsiz olasılık."},{"q":"Die Ministerin ___ bereits informiert gewesen sein. (duyuma göre)","o":["muss","soll","will","darf"],"a":1,"why":"sollen = ikinci el/doğrulanmamış bilgi."},{"q":"Der Zeuge ___ alles gesehen haben. (kendisi iddia ediyor, konuşan mesafeli)","o":["will","muss","darf","soll"],"a":0,"why":"wollen subjektiv = kişinin kendi iddiası, konuşan şüpheci olabilir."},{"q":"Die Ursache ___ in der neuen Software liegen. (muhtemelen)","o":["dürfte","soll","will","muss immer"],"a":0,"why":"dürfte = yüksek olasılık/varsayım."},{"q":"Das ___ kein Zufall sein. (güçlü olumsuz çıkarım)","o":["kann","muss","soll","darf"],"a":0,"why":"“Das kann kein … sein” = kesinlikle olamaz."},{"q":"Vergangenheit: Vielleicht hat er den Termin vergessen. → Er ___ den Termin vergessen haben.","o":["könnte","soll","will","muss"],"a":0,"why":"könnte + Infinitiv Perfekt."},{"q":"Rat: Du ___ deine Argumente klarer strukturieren.","o":["solltest","willst","darfst","kannst nur"],"a":0,"why":"Konjunktiv II von sollen = tavsiye."}]},{"id":"evidenz","type":"match","title":"Modal yapı → anlam","intro":"","prompts":["könnte passiert sein","dürfte passiert sein","muss passiert sein","soll passiert sein","will passiert sein"],"options":["olasılık","yüksek olasılık","güçlü çıkarım","duyum/ikinci el bilgi","kişinin tartışmalı kendi iddiası"],"answers":[0,1,2,3,4],"why":[]}],"production":{"task":"Bir olay hakkında 4 cümlede farklı kesinlik dereceleri ifade et.","target":"könnte/dürfte/muss/soll yapılarını anlamına göre kullan.","example":"Der Lieferant dürfte die Ware bereits verschickt haben. Die Sendung muss also unterwegs sein. Laut Spedition soll es gestern jedoch eine Verzögerung gegeben haben.","mode":"write","minChars":60,"checklist":[]}},{"id":12,"unit":"C1 dilbilgisi","title":"Dilek/varsayım kipi (Konjunktiv II): varsayım, ihtiyat ve geçmiş pişmanlık","skills":["Dilbilgisi","Konuşma","Yazma"],"goal":"Gerçek dışı koşullar, temkinli ifadeler, öneriler ve geçmişte gerçekleşmeyen durumları ifade etmek.","explanation":"Konjunktiv II C1’de yalnızca “würde” cümlesi değildir. “Wäre die Nachfrage höher, ließe sich das Projekt finanzieren.” gibi yoğun yapılar, temkinli iddialar (“Es wäre denkbar, dass …”) ve geçmiş pişmanlık (“Man hätte früher reagieren müssen.”) önemlidir.","examples":[["Wäre mehr Zeit vorhanden, ließe sich die Analyse vertiefen.","Daha fazla zaman olsaydı analiz derinleştirilebilirdi.","İrreal koşul."],["Man hätte die Risiken früher berücksichtigen sollen.","Riskler daha erken dikkate alınmalıydı.","Geçmişe dönük değerlendirme."]],"quiz":[{"q":"Geçmişte gerçekleşmeyen öneri hangisidir?","o":["Man sollte reagieren.","Man hätte reagieren sollen.","Man soll reagieren."],"a":1,"why":"Konjunktiv II Vergangenheit geçmişe dönük tavsiye/eleştiri yapar."},{"q":"“Es wäre denkbar, dass …” ne tür bir işlev taşır?","o":["Temkinli varsayım","Kesin emir","Söylenti aktarma"],"a":0,"why":"İddiayı ihtiyatlılaştırır."}],"activities":[{"id":"k2-mc","type":"mc","title":"Konjunktiv II","intro":"","questions":[{"q":"___ mehr Daten vorhanden, ließe sich die Hypothese besser prüfen.","o":["Wären","Sind","Seien","Wurden"],"a":0,"why":"İrreal koşul: Wären …, ließe …"},{"q":"Geçmiş pişmanlık: Wir ___ früher reagieren ___.","o":["hätten / sollen","würden / sollen","seien / sollen","haben / sollen"],"a":0,"why":"hätten + Infinitiv + sollen."},{"q":"Temkinli öneri hangisidir?","o":["Das ist so.","Es wäre denkbar, dass …","Das muss so sein.","Mach das!"],"a":1,"why":"Konjunktiv II iddiayı yumuşatır."},{"q":"Wenn ich mehr Zeit ___, ___ ich den Bericht überarbeiten.","o":["hätte / würde","habe / werde","sei / würde","hatte / würde"],"a":0,"why":"İrreal şart."},{"q":"Es ___ sinnvoll, die Stichprobe zu vergrößern.","o":["wäre","sei","wird","war immer"],"a":0,"why":"Temkinli değerlendirme."},{"q":"Er tut so, als ___ er alles.","o":["wüsste","weiß","wisse","wusste immer"],"a":0,"why":"als ob/als + Konjunktiv II irreal karşılaştırma."},{"q":"Das ___ ich an deiner Stelle vermeiden.","o":["würde","werde","sei","habe"],"a":0,"why":"Tavsiye için Konjunktiv II."},{"q":"Hätten wir die Warnung ernst genommen, ___ es nicht so weit gekommen.","o":["wäre","ist","sei","würde jetzt"],"a":0,"why":"Geçmiş irreal koşul: wäre … gekommen."}]},{"id":"k2-fn","type":"match","title":"Yapı → işlev","intro":"","prompts":["Es wäre sinnvoll, …","Wenn wir mehr Zeit hätten, …","Das hätte nicht passieren dürfen.","Ich würde vorschlagen, …"],"options":["temkinli değerlendirme","gerçek dışı/varsayımsal koşul","geçmişe dönük eleştiri/pişmanlık","nazik öneri"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Bir işyeri sorununda temkinli öneri ve geçmişe dönük eleştiri yaz.","target":"Konjunktiv II Präsens + Vergangenheit kullan.","example":"Es wäre sinnvoll, den Kunden früher zu informieren. Wir könnten zunächst eine Zwischenlösung anbieten. Rückblickend hätten wir die Frist realistischer planen sollen.","mode":"write","minChars":60,"checklist":[]}},{"id":13,"unit":"C1 dilbilgisi","title":"Dolaylı anlatım kipi (Konjunktiv I)","skills":["Dilbilgisi","Okuma","Yazma"],"goal":"Başkasının sözünü mesafeli biçimde aktarmak ve haber dilini anlamak.","explanation":"Konjunktiv I, özellikle haber ve akademik aktarımda kaynağın sözünü konuşanın kendi iddiası gibi sunmamasını sağlar: “Die Autorin erklärt, die Daten seien eindeutig.” Biçim Indikativ ile çakışıyorsa çoğu zaman Konjunktiv II devreye girer.","examples":[["Der Forscher betont, die Ergebnisse seien vorläufig.","Araştırmacı sonuçların geçici olduğunu vurguluyor.","Dolaylı anlatım."],["Die Zeugen erklärten, sie hätten nichts bemerkt.","Tanıklar hiçbir şey fark etmediklerini söylediler.","Çakışmayı önlemek için Konjunktiv II."]],"quiz":[{"q":"Dolaylı anlatım için en tipik yapı hangisidir?","o":["Er sagt, er ist krank.","Er sagt, er sei krank.","Er sagt, krank sein."],"a":1,"why":"Konjunktiv I mesafeli aktarım sağlar."},{"q":"Konjunktiv I’in temel iletişim işlevi nedir?","o":["Kaynağın sözünü mesafeli aktarmak","Emir vermek","Gelecek zaman kurmak"],"a":0,"why":"Konuşan aktarılan bilgiye doğrudan sahiplik iddiası eklemez."}],"activities":[{"id":"k1-mc","type":"mc","title":"Konjunktiv I","intro":"","questions":[{"q":"Die Autorin sagt, die Daten ___ eindeutig.","o":["seien","sind","wären nur","werden gewesen"],"a":0,"why":"Konjunktiv I plural: seien."},{"q":"Er erklärt, er ___ keine Kenntnis davon.","o":["habe","hat","hätte immer","haben"],"a":0,"why":"Konjunktiv I: habe."},{"q":"Der Sprecher behauptet, die Maßnahme ___ Wirkung.","o":["zeige","zeigt","zeigte zwingend","würde gezeigt"],"a":0,"why":"Konjunktiv I: zeige."},{"q":"Indikativ ve Konjunktiv I çakışırsa sık kullanılan çözüm?","o":["Konjunktiv II","Imperativ","Passiv zorunlu","Futur II"],"a":0,"why":"Mesafeyi görünür kılmak için Ersatzkonjunktiv II."},{"q":"Sie sagten, sie ___ nichts bemerkt.","o":["hätten","haben","seien bemerken","würden bemerkt"],"a":0,"why":"Plural biçimde Konjunktiv I “haben” ile çakıştığı için “hätten”."},{"q":"Konjunktiv I’in temel amacı?","o":["Kaynağı mesafeli aktarmak","Geleceği kesinleştirmek","Emir vermek","Soru sormak"],"a":0,"why":"Özellikle haber/rapor dilinde aktarım işlevi."},{"q":"Die Expertin betont, man ___ die Daten vorsichtig interpretieren.","o":["müsse","muss","musste","würde müssen gewesen"],"a":0,"why":"Konjunktiv I von müssen: müsse."},{"q":"Er meint, das Ergebnis ___ überraschend.","o":["sei","ist","wäre nur vielleicht","war"],"a":0,"why":"Konjunktiv I von sein: sei."}]},{"id":"indirect","type":"match","title":"Doğrudan → dolaylı","intro":"","prompts":["„Ich habe keine Zeit.“","„Die Lieferung kommt morgen.“","„Wir können den Termin halten.“"],"options":["Er sagt, er habe keine Zeit.","Sie erklärt, die Lieferung komme morgen.","Sie sagen, sie könnten/können den Termin halten."],"answers":[0,1,2],"why":[]}],"production":{"task":"Bir yöneticinin üç cümlesini dolaylı anlatımla aktar.","target":"Konjunktiv I ile kaynak mesafesi göster.","example":"Die Projektleiterin erklärte, der Termin sei weiterhin realistisch. Sie habe bereits zusätzliche Ressourcen beantragt und werde das Team morgen informieren.","mode":"write","minChars":60,"checklist":[]}},{"id":14,"unit":"C1 dilbilgisi","title":"Adlaştırma ve fiilleştirme","skills":["Dilbilgisi","Yazma","Okuma"],"goal":"Yoğun isim yapıları ile açık fiil cümleleri arasında dönüşüm yapmak.","explanation":"Akademik ve resmî metinler sık sık nominal yapı kullanır: “wegen der steigenden Kosten”. Daha akıcı anlatım için fiilleştirilebilir: “weil die Kosten steigen”. Ters yönde dönüşüm de metni yoğunlaştırır. Doğru edat ve hâl seçimi kritik önemdedir.","examples":[["Aufgrund der starken Nachfrage wurde das Angebot erweitert.","Yüksek talep nedeniyle teklif genişletildi.","Nominal yapı."],["Weil die Nachfrage stark gestiegen ist, wurde das Angebot erweitert.","Talep çok arttığı için teklif genişletildi.","Fiilleştirilmiş yapı."]],"quiz":[{"q":"“wegen der Verzögerung” için uygun fiil cümlesi hangisidir?","o":["weil sich etwas verzögert","obwohl sich etwas verzögert","damit sich etwas verzögert"],"a":0,"why":"“wegen” neden bildirir; “weil” ile fiilleştirilebilir."},{"q":"Nominalizasyonun tipik etkisi nedir?","o":["Metni yoğunlaştırır ve resmîleştirebilir","Her zaman konuşma dilini artırır","Fiil zamanını kaldırdığı için anlamı yok eder"],"a":0,"why":"Özellikle akademik/resmî yazıda bilgi yoğunluğunu artırır."}],"activities":[{"id":"nom-mc","type":"mc","title":"Nominalisierung / Verbalisierung","intro":"","questions":[{"q":"“wegen der steigenden Kosten” →","o":["weil die Kosten steigen","obwohl die Kosten steigen","damit die Kosten steigen","wenn die Kosten nicht steigen"],"a":0,"why":"wegen = neden."},{"q":"“trotz der Kritik” →","o":["obwohl es Kritik gibt","weil es Kritik gibt","damit es Kritik gibt","bevor es Kritik gibt"],"a":0,"why":"trotz = taviz, obwohl."},{"q":"“nach Abschluss der Studie” →","o":["nachdem die Studie abgeschlossen worden war","weil die Studie beginnt","bevor man die Studie abschließt","falls die Studie endet"],"a":0,"why":"nach = zaman ilişkisi, nachdem."},{"q":"“zur Verbesserung der Qualität” →","o":["damit die Qualität verbessert wird","weil die Qualität schlecht ist","obwohl die Qualität steigt","nachdem die Qualität sank"],"a":0,"why":"zur + nominal amaç = damit/um … zu."},{"q":"“bei einer weiteren Verschärfung” →","o":["wenn sich die Lage weiter verschärft","obwohl die Lage besser wird","weil niemand reagiert","nachdem alles vorbei ist"],"a":0,"why":"bei + durum çoğu kez wenn/falls."},{"q":"“aufgrund fehlender Daten” →","o":["weil Daten fehlen","obwohl Daten fehlen","damit Daten fehlen","bevor Daten fehlen"],"a":0,"why":"aufgrund = neden."},{"q":"“während der Auswertung” →","o":["während die Daten ausgewertet werden","weil die Daten fehlen","nachdem alles fertig ist","damit man beginnt"],"a":0,"why":"Eş zamanlılık."},{"q":"Nominal yapı ne zaman özellikle uygundur?","o":["Bilgiyi yoğun ve resmî biçimde paketlemek gerektiğinde","Her konuşma cümlesinde","Sadece A1 düzeyinde","Sadece sorularda"],"a":0,"why":"Akademik/resmî registerda yoğunluk sağlar."}]},{"id":"nom-map","type":"match","title":"Nominal → verbal","intro":"","prompts":["wegen der Verzögerung","trotz der Kritik","nach Abschluss der Prüfung","zur Verbesserung der Qualität"],"options":["weil sich etwas verzögert","obwohl Kritik geäußert wird","nachdem die Prüfung abgeschlossen wurde","damit die Qualität verbessert wird"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Bir işyeri ifadesini nominal ve verbal iki biçimde yaz.","target":"Nominalisierung ve Verbalisierung arasında doğru anlam ilişkisi kur.","example":"Nach der Prüfung der Unterlagen wurde der Antrag genehmigt. Nachdem die Unterlagen geprüft worden waren, genehmigte die Abteilung den Antrag.","mode":"write","minChars":60,"checklist":[]}},{"id":15,"unit":"İş dünyası C1","title":"İşe giriş, başvuru ve çalışma koşulları","skills":["Kelime","Okuma","Yazma"],"goal":"Bewerbung, Arbeitsantritt, Kündigungsfrist ve çalışma koşullarıyla ilgili yoğun işyeri dilini güvenli kullanmak.","explanation":"DTB C1’de işyeri metinleri genellikle basit günlük kelimelerden değil, sabit birleşimlerden ve resmî yapılardan oluşur. “eine Stelle antreten”, “auf die Einhaltung einer Frist verzichten”, “unter welchen Bedingungen”, “ein Anliegen ansprechen” gibi yapılar hem Sprachbausteine hem de yazılı iletişim için kritiktir.","examples":[["Ich könnte die Stelle bereits zum Monatsanfang antreten.","Pozisyona ay başında başlayabilirim.","Stelle antreten = işe başlamak."],["Mein bisheriger Arbeitgeber verzichtet auf die Einhaltung der Kündigungsfrist.","Mevcut işverenim ihbar süresine uyulmasından feragat ediyor.","resmî işyeri kalıbı."],["Ich möchte noch ein persönliches Anliegen ansprechen.","Bir kişisel konuyu daha gündeme getirmek istiyorum.","nazik geçiş."]],"activities":[{"id":"job-colloc","type":"match","title":"İş dünyası kalıpları","intro":"","prompts":["eine Stelle","eine Frist","ein Anliegen","Bedingungen","ein Gespräch"],"options":["antreten","einhalten","ansprechen","klären","führen"],"answers":[0,1,2,3,4],"why":[]},{"id":"job-mail","type":"cloze","title":"E-postadaki boşluğu bağlama göre doldur","intro":"","text":"Sehr geehrte Frau König, ___ habe ich meinen aktuellen Arbeitgeber informiert. Er ist bereit, auf einen Teil der Kündigungsfrist zu ___. Daher könnte ich die Stelle früher ___. Könnten Sie mir bitte mitteilen, unter welchen ___ dies möglich wäre?","blanks":[{"label":"1","options":["Inzwischen","Trotzdem","Obwohl"],"a":0,"why":"Zaman ilerlemesini belirtir."},{"label":"2","options":["verzichten","kündigen","bestehen"],"a":0,"why":"auf etwas verzichten."},{"label":"3","options":["antreten","betreten","eintreten"],"a":0,"why":"eine Stelle antreten."},{"label":"4","options":["Bedingungen","Meinungen","Folgen"],"a":0,"why":"unter welchen Bedingungen."}]}],"production":{"task":"Yeni bir işverene 5–7 cümlelik yarı resmî bir e-posta yaz: başlangıç tarihiyle ilgili durumu açıkla, bir kişisel konuyu belirt ve bilgi iste.","target":"Nazik resmî kayıt, en az iki işyeri kalıbı ve açık bir istek kullan.","example":"Sehr geehrte Frau Berger, inzwischen konnte ich meinen möglichen Eintrittstermin klären. Mein derzeitiger Arbeitgeber ist bereit, auf einen Teil der Kündigungsfrist zu verzichten. Daher könnte ich die Stelle bereits zum 1. Mai antreten. Ich möchte jedoch noch ein persönliches Anliegen ansprechen und wäre Ihnen dankbar, wenn Sie mir die Rahmenbedingungen kurz erläutern könnten.","mode":"write","minChars":60,"checklist":[]}},{"id":16,"unit":"İş dünyası C1","title":"Ekip, liderlik ve iş organizasyonu","skills":["Kelime","Konuşma","Yazma"],"goal":"Ekip içi iş dağılımı, liderlik, motivasyon ve organizasyon hakkında C1 düzeyinde nüanslı konuşmak.","explanation":"Sözlü sınavda hem monolog hem de iş arkadaşıyla etkileşim işyeri temalarını kullanır. Bu nedenle “Verantwortung übernehmen”, “Aufgaben priorisieren”, “Rückmeldung geben”, “Zuständigkeiten klären”, “eine Übergangslösung ausarbeiten” gibi işlevsel ifadeler aktif olmalıdır.","examples":[["Wir sollten die Zuständigkeiten zunächst eindeutig klären.","Önce sorumlulukları netleştirmeliyiz.","sorun çözme dili."],["Eine gute Führungskraft gibt konstruktive Rückmeldung und setzt klare Prioritäten.","İyi bir yönetici yapıcı geri bildirim verir ve net öncelikler belirler.","Führung dili."],["Für die nächsten zwei Wochen brauchen wir eine tragfähige Übergangslösung.","Önümüzdeki iki hafta için uygulanabilir geçici çözüme ihtiyacımız var.","DTB problem çözme."]],"activities":[{"id":"team-colloc","type":"match","title":"İşlev → ifade","intro":"","prompts":["sorumluluk almak","öncelik belirlemek","görevleri netleştirmek","geri bildirim vermek","geçici çözüm geliştirmek"],"options":["Verantwortung übernehmen","Prioritäten setzen","Zuständigkeiten klären","Rückmeldung geben","eine Übergangslösung ausarbeiten"],"answers":[0,1,2,3,4],"why":[]},{"id":"team-case","type":"reading","title":"Durumu analiz et","intro":"","text":"In einem kleinen Team fallen zwei Mitarbeitende für mehrere Wochen aus. Die Teamleitung möchte zunächst sämtliche Aufgaben unverändert weiterführen. Einige Kolleginnen weisen jedoch darauf hin, dass dies zu Überlastung führen könnte. Sie schlagen vor, dringende Aufgaben zu priorisieren und weniger wichtige Projekte vorübergehend zu verschieben.","questions":[{"q":"Was ist der Konflikt?","o":["Urlaubsplanung","Alle Aufgaben fortführen vs. Prioritäten neu setzen","Gehaltserhöhung"],"a":1,"why":"Metin iş yükünün yeniden düzenlenmesini tartışır."},{"q":"Welche Lösung wirkt am tragfähigsten?","o":["Alle Aufgaben unverändert lassen","Prioritäten setzen und weniger Dringendes verschieben","Keine Entscheidung treffen"],"a":1,"why":"Kapasite eksikliğine doğrudan cevap verir."},{"q":"Welches Wort passt zur Situation?","o":["Überlastung","Werbekampagne","Kundenbindung"],"a":0,"why":"Ekip kapasitesinin aşılması söz konusu."}]}],"production":{"task":"Bir ekipte iki kişinin uzun süreli yokluğu için 5–7 cümlelik çözüm önerisi yaz.","target":"Sofortmaßnahme, iş dağılımı, iletişim ve orta vadeli çözüm belirt; en az iki Nomen-Verb-Verbindung kullan.","example":"Zunächst sollten wir die Prioritäten neu setzen und die Zuständigkeiten klären. Gleichzeitig könnte die Teamleitung eine Übergangslösung ausarbeiten. Weniger dringende Projekte ließen sich vorübergehend verschieben. Dadurch vermeiden wir, dass einzelne Kolleginnen und Kollegen dauerhaft überlastet werden.","mode":"write","minChars":60,"checklist":[]}},{"id":17,"unit":"İş dünyası C1","title":"Müşteri hizmetleri, şikâyet ve çözüm dili","skills":["Okuma","Yazma","Kayıt"],"goal":"Bir şikâyette olguyu, iddiayı ve talebi ayırmak; müşteriye suçlayıcı olmayan profesyonel çözüm diliyle cevap vermek.","explanation":"Lesen und Schreiben görevi yalnızca metni anlamayı değil, üst yöneticinin sert veya eksik talimatını uygun müşteri diline dönüştürmeyi de gerektirir. C1 düzeyinde “Wir bedauern…”, “der Vorgang wird geprüft”, “ohne der Ursache vorzugreifen”, “wir schlagen folgendes Vorgehen vor” gibi ifadeler yararlıdır.","examples":[["Wir bedauern die entstandenen Unannehmlichkeiten.","Yaşanan aksaklıktan dolayı üzgünüz.","profesyonel açılış."],["Der Vorgang wird derzeit geprüft; über das Ergebnis informieren wir Sie umgehend.","Konu şu anda inceleniyor; sonuç hakkında sizi derhal bilgilendireceğiz.","suçlamadan süreç belirtme."],["Wir schlagen vor, zunächst einen Vor-Ort-Termin zu vereinbaren.","Öncelikle yerinde inceleme randevusu önermekteyiz.","çözüm odaklılık."]],"activities":[{"id":"complaint-functions","type":"match","title":"İletişim işlevi → ifade","intro":"","prompts":["empati","durum açıklama","belirsizlik/temkin","çözüm önerisi","sonraki adım"],"options":["Wir bedauern die entstandenen Unannehmlichkeiten.","Nach unseren Unterlagen wurde die Ware am Dienstag geliefert.","Die genaue Ursache lässt sich derzeit noch nicht abschließend beurteilen.","Wir schlagen vor, die betroffene Ware auszutauschen.","Wir melden uns bis spätestens Freitag erneut bei Ihnen."],"answers":[0,1,2,3,4],"why":[]},{"id":"complaint-read","type":"reading","title":"Şikâyette bilgiyi ayır","intro":"","text":"Ein Kunde meldet, dass eine Lieferung beschädigt angekommen sei. Er geht davon aus, dass die Verpackung unzureichend gewesen sei, und bittet um Ersatz bis Freitag. Die Logistikabteilung weist intern darauf hin, dass der Schaden möglicherweise beim Transport entstanden ist und bittet den Kundenservice, zunächst Fotos anzufordern.","questions":[{"q":"Was ist gesichert?","o":["Die Verpackung war definitiv fehlerhaft.","Der Kunde meldet einen Schaden und wünscht Ersatz bis Freitag.","Der Transporteur ist verantwortlich."],"a":1,"why":"Neden henüz kesin değil; şikâyet ve talep kesin."},{"q":"Was soll der Kundenservice zuerst tun?","o":["Schuld eingestehen","Fotos anfordern","Rechnung stornieren"],"a":1,"why":"İç talimat önce fotoğraf istemektir."},{"q":"Welche Formulierung vermeidet eine vorschnelle Schuldzuweisung?","o":["Wir haben den Schaden verursacht.","Die genaue Ursache wird derzeit geprüft.","Sie haben sicher falsch ausgepackt."],"a":1,"why":"Tarafsız ve profesyonel."}]}],"production":{"task":"5–8 cümlelik bir müşteri e-postası yaz: şikâyeti kabul et, kesin olmayan nedeni temkinli ifade et, gerekli bilgiyi iste ve sonraki adımı belirt.","target":"Adresata uygun resmî kayıt; suçlayıcı dil yok; açık eylem ve zaman çizelgesi.","example":"Sehr geehrte Frau Neumann, vielen Dank für Ihre Nachricht. Wir bedauern, dass die Lieferung beschädigt bei Ihnen angekommen ist. Die genaue Ursache lässt sich derzeit noch nicht abschließend beurteilen. Damit wir den Vorgang schnell prüfen können, senden Sie uns bitte zwei Fotos der Verpackung und der beschädigten Ware. Sobald uns diese vorliegen, melden wir uns spätestens am nächsten Werktag mit einem konkreten Lösungsvorschlag.","mode":"write","minChars":60,"checklist":[]}},{"id":18,"unit":"İş dünyası C1","title":"Toplantı, tutanak ve görev dağılımı","skills":["Okuma","Kelime","Mediation"],"goal":"Toplantı tutanaklarında görüş, karar, sorumlu kişi ve son tarihi birbirinden ayırmak.","explanation":"Lesen Teil 4 işyeri tutanağında ayrıntı ve görev dağılımını test eder. “nimmt Stellung”, “wendet ein”, “weist darauf hin”, “bittet um Umsetzung”, “bis zum … vorlegen” gibi ifadeler görüş ile kararı ayırmaya yardım eder.","examples":[["Die Vertriebsleitung wendet ein, dass die Frist zu knapp sei.","Satış yönetimi sürenin çok kısa olduğuna itiraz ediyor.","itiraz ≠ karar."],["Die Geschäftsführung bittet die IT, bis Freitag einen Projektplan vorzulegen.","Yönetim BT’den cuma gününe kadar proje planı sunmasını istiyor.","görev + son tarih."],["Das Thema wird in einem gesonderten Termin vertieft.","Konu ayrı bir toplantıda derinleştirilecek.","sonraki adım."]],"activities":[{"id":"minutes-verbs","type":"match","title":"Protokoll fiili → işlev","intro":"","prompts":["nimmt Stellung","wendet ein","weist darauf hin","bittet um Umsetzung","beauftragt"],"options":["görüş bildirir","itiraz eder","dikkat çeker","uygulanmasını ister","görev verir"],"answers":[0,1,2,3,4],"why":[]},{"id":"minutes-case","type":"reading","title":"Mini-Protokoll","intro":"","text":"TOP 1: Lieferzeiten. Vertrieb berichtet über mehrere Beschwerden. Logistik weist darauf hin, dass ein neuer Dienstleister getestet wird. Die Geschäftsführung beauftragt Logistik, bis zum 15. Juni einen Vergleich der Lieferzeiten vorzulegen. Vertrieb und Kundenservice sollen bis dahin die Beschwerden nach Dringlichkeit kategorisieren.","questions":[{"q":"Was ist bereits entschieden?","o":["Der neue Dienstleister wird definitiv beauftragt.","Logistik soll einen Vergleich vorlegen.","Alle Beschwerden werden geschlossen."],"a":1,"why":"Açık görev verilmiştir."},{"q":"Wer soll Beschwerden kategorisieren?","o":["Nur Logistik","Vertrieb und Kundenservice","Geschäftsführung"],"a":1,"why":"Metinde iki bölüm birlikte görevlendirilir."},{"q":"Bis wann soll der Vergleich vorliegen?","o":["sofort","15. Juni","Ende des Jahres"],"a":1,"why":"Son tarih açıkça belirtilmiştir."},{"q":"Welche Aussage ist nur Information, kein Beschluss?","o":["Ein neuer Dienstleister wird getestet.","Logistik soll den Vergleich vorlegen.","Beschwerden sollen kategorisiert werden."],"a":0,"why":"Bu mevcut durum bilgisidir."}]}],"production":{"task":"Bir toplantıyı 5–7 cümlede özetle: sorun, iki görüş, karar, sorumlu kişi ve son tarih.","target":"Görüş ile karar fiillerini ayır; “soll”, “wird beauftragt”, “bis …” gibi yapılar kullan.","example":"Im Vertrieb wurden längere Lieferzeiten kritisiert. Die Logistik weist darauf hin, dass bereits ein neuer Dienstleister getestet wird. Die Geschäftsführung hat beschlossen, die Optionen systematisch zu vergleichen. Die Logistik soll bis zum 15. Juni einen Bericht vorlegen, während Vertrieb und Kundenservice die Beschwerden priorisieren.","mode":"write","minChars":60,"checklist":[]}},{"id":19,"unit":"İş dünyası C1","title":"Kalite, veri koruma, lojistik ve süreç dili","skills":["Okuma","Kelime","Dilbilgisi"],"goal":"Kalite yönetimi, Datenschutz, lojistik ve süreç iyileştirme metinlerindeki tipik C1 işyeri dilini anlamak.","explanation":"Model test farklı mesleklere özel uzmanlık bilgisi istemez; ancak genel işyeri alanlarında yoğun metinler kullanır. “personenbezogene Daten verarbeiten”, “Fehlerquote senken”, “Optimierungspotenzial prüfen”, “eine Lieferung nachverfolgen”, “Vorgaben einhalten” gibi ifadeler tekrar tekrar işe yarar.","examples":[["Personenbezogene Daten dürfen nur zweckgebunden verarbeitet werden.","Kişisel veriler yalnızca amaçla sınırlı şekilde işlenmelidir.","Datenschutz."],["Die Fehlerquote soll durch zusätzliche Kontrollen gesenkt werden.","Hata oranı ek kontrollerle düşürülmeli.","Qualität."],["Die Sendung lässt sich im System derzeit nicht eindeutig nachverfolgen.","Gönderi sistemde şu anda kesin şekilde takip edilemiyor.","Logistik."]],"activities":[{"id":"process-vocab","type":"match","title":"Alan → tipik ifade","intro":"","prompts":["Datenschutz","Qualitätsmanagement","Logistik","IT/Prozess"],"options":["personenbezogene Daten verarbeiten","Fehlerquote und kontinuierliche Verbesserung","Sendung nachverfolgen / Fehllieferung","Optimierungspotenzial prüfen"],"answers":[0,1,2,3],"why":[]},{"id":"process-read","type":"reading","title":"Yoğun işyeri metni","intro":"","text":"Das Unternehmen führt ein neues digitales Dokumentationssystem ein. Ziel ist es, Fehlerquellen schneller zu erkennen und Bearbeitungszeiten zu verkürzen. Gleichzeitig weist die Datenschutzbeauftragte darauf hin, dass nur erforderliche personenbezogene Daten gespeichert werden dürfen. Vor der Einführung müssen daher Zugriffsrechte festgelegt und Mitarbeitende unterwiesen werden.","questions":[{"q":"Welches Ziel hat das System?","o":["Mehr Daten sammeln","Fehler schneller erkennen und Bearbeitungszeit reduzieren","Datenschutz abschaffen"],"a":1,"why":"İki süreç hedefi açıkça belirtilir."},{"q":"Welche Bedingung gilt vor Einführung?","o":["Zugriffsrechte festlegen und unterweisen","Alle Daten öffentlich machen","Keine Schulung durchführen"],"a":0,"why":"Veri erişimi ve eğitim gereklidir."},{"q":"Welche Aussage ist korrekt?","o":["Es dürfen beliebig viele personenbezogene Daten gespeichert werden.","Es sollen nur erforderliche personenbezogene Daten gespeichert werden.","Das System hat keinen Datenschutzbezug."],"a":1,"why":"Amaçla gerekli verilerle sınırlama var."}]}],"production":{"task":"Bir süreç iyileştirme önerisini 5–7 cümlede yaz: mevcut sorun, öneri, veri/kalite riski ve kontrol önlemi.","target":"Passiv, nominalizasyon veya Nomen-Verb-Verbindung gibi en az iki C1 yapısı kullan.","example":"Zur Reduzierung der Bearbeitungszeit sollte ein digitales Ticketsystem eingeführt werden. Vor der Einführung müssen jedoch klare Zugriffsrechte festgelegt werden. Personenbezogene Daten dürfen nur im erforderlichen Umfang verarbeitet werden. Zusätzlich sollten regelmäßige Qualitätskontrollen durchgeführt werden, damit Fehler früh erkannt werden.","mode":"write","minChars":60,"checklist":[]}},{"id":20,"unit":"İş dünyası C1","title":"Mediation, telefon notu ve bilgi seçimi","skills":["Dinleme","Yazma","Mediation"],"goal":"Bir mesajdaki bilgiyi kopyalamadan, hedef kişiye gerekli alanlara dönüştürmek: kim, iletişim, neden, ek bilgi, yapılacak iş.","explanation":"Hören und Schreiben bölümünde dinleme yalnızca anlamayı değil, bilgiyi yapılandırılmış biçimde aktarmayı ölçer. Başarılı not “her şeyi” yazmaz; doğru kişiyi, iletişim bilgisini, önemli ayrıntıyı ve eylemi seçer.","examples":[["Herr Kaya von NordLogistik bittet um Rückruf bis 15 Uhr.","NordLogistik’ten Bay Kaya saat 15’e kadar geri arama istiyor.","kim + eylem + süre."],["Die Lieferung kann erst am Donnerstag erfolgen; der Kunde soll heute informiert werden.","Teslimat ancak perşembe yapılabilir; müşteri bugün bilgilendirilmeli.","durum + yapılacak iş."],["Ich notiere nur die Information, die meine Kollegin für den nächsten Schritt braucht.","Yalnızca meslektaşımın sonraki adım için ihtiyaç duyduğu bilgiyi not ederim.","Mediation ilkesi."]],"activities":[{"id":"note-fields","type":"match","title":"Bilgi → alan","intro":"","prompts":["Frau Deniz, ProService","040 555 28 91","Lieferung verzögert sich bis Donnerstag","Kunden heute informieren und Rückmeldung geben"],"options":["Name/Firma","Kontakt","Weitere Informationen","Zu erledigen"],"answers":[0,1,2,3],"why":[]},{"id":"relevance","type":"mc","title":"Hangi bilgi not için önceliklidir?","intro":"","questions":[{"q":"Bir tedarikçi 16:00’ya kadar geri arama istiyor. Hangisi en önemli?","o":["Konuşmacının ses tonu","Geri arama son saati ve iletişim bilgisi","Ofisin duvar rengi"],"a":1,"why":"Eyleme geçirilebilir bilgi önceliklidir."},{"q":"Mediation’da ne yapılmamalı?","o":["Ana bilgiyi hedef kişiye göre seçmek","Her cümleyi aynen kopyalamaya çalışmak","Yapılacak işi açık belirtmek"],"a":1,"why":"Amaç seçici aktarım, transkripsiyon değildir."},{"q":"„zu erledigen“ alanında ne olmalı?","o":["Bir sonraki eylem","Konuşmacının yaşı","Tüm konuşma metni"],"a":0,"why":"Eylem talimatı/sonraki adım."}]}],"production":{"task":"Aşağıdaki duruma göre telefon notu yaz: “Frau Özdemir, Firma KlimaTec, 030 448821, bakım ekibi yarın 14:00 yerine 16:30’da gelebilir; lütfen bugün 12:00’ye kadar yeni saati onaylayın.”","target":"Name/Firma, Kontakt, weitere Informationen ve zu erledigen alanlarını ayrı satırlarda yaz.","example":"Name/Firma: Frau Özdemir, KlimaTec\nKontakt: 030 448821\nWeitere Informationen: Wartung morgen erst um 16:30 Uhr möglich.\nZu erledigen: neuen Termin heute bis 12:00 Uhr bestätigen.","mode":"write","minChars":50,"checklist":[]}},{"id":21,"unit":"DTB C1 · Lesen","title":"Lesen Teil 1: bilgi ihtiyacı ↔ kısa makale eşleştirme","skills":["Okuma","Strateji"],"goal":"5 kişinin bilgi ihtiyacını 8 kısa iş dünyası metniyle eşleştirmek; anahtar kelime değil anlam eşleşmesi yapmak.","explanation":"Resmi formatta 5 kişi ve 8 kısa seçenek vardır. Çeldiriciler aynı kelime alanını paylaşabilir; doğru eşleştirme kişinin gerçek niyetini yakalamayı gerektirir. Önce kişi profilindeki “ne arıyor?” sorusunu tek cümleyle parafraz et, sonra seçenekleri tara.","examples":[["Sie sucht keine allgemeine Motivationstipps, sondern konkrete Hilfe bei Überlastung.","Genel motivasyon değil, aşırı iş yükü için somut yardım arıyor.","ihtiyacı parafraz et."],["Der Artikel erwähnt zwar Stress, beantwortet aber nicht ihre eigentliche Frage.","Makale stresten bahsediyor ama asıl soruyu cevaplamıyor.","çeldirici kontrolü."],["Entscheidend ist die thematische Passung, nicht ein identisches Schlüsselwort.","Belirleyici olan tematik uyumdur, aynı kelime değil.","Lesen Teil 1 stratejisi."]],"activities":[{"id":"lv1-set","type":"match","title":"5 kişi → 8 makale","intro":"Wähle pro Person die beste inhaltliche Passung.","prompts":["Aylin möchte wissen, wie sie nach Jahren im selben Beruf wieder mehr Sinn in ihrer Arbeit finden kann.","Bora sucht konkrete Strategien, um Überlastung mit seiner Vorgesetzten sachlich anzusprechen.","Cem interessiert sich dafür, wie kleine Firmen sich gegenüber großen Konkurrenten positionieren können.","Derya möchte nachhaltige Produkte anbieten, ohne nur ein „grünes“ Image zu verkaufen.","Emre fragt sich, ob eine berufliche Auszeit langfristig der Karriere schadet."],"options":["A · Sinnkrise im Beruf: Werte klären statt sofort kündigen","B · Schwierige Gespräche über Arbeitsbelastung professionell vorbereiten","C · Nischenstrategie: Wie kleine Anbieter gegen Marktführer bestehen","D · Nachhaltigkeit glaubwürdig in Produkt und Lieferkette verankern","E · Digitale Werbung mit kleinem Budget","F · Auszeiten, Sabbaticals und Rückkehr in den Beruf","G · Neue Regeln für Dienstreisen","H · Gehaltsgespräche in wirtschaftlich schwierigen Zeiten"],"answers":[0,1,2,3,5],"why":[]},{"id":"lv1-strat","type":"mc","title":"Strateji kontrolü","intro":"","questions":[{"q":"İlk adım ne olmalı?","o":["Her makaleyi tam ayrıntılı okumak","Kişinin bilgi ihtiyacını parafraz etmek","Aynı kelimeyi aramak"],"a":1,"why":"Arama hedefini netleştirir."},{"q":"İki seçenek benzerse neye bakılır?","o":["Hangi metin ihtiyacın tamamını karşılıyor?","Hangisi daha uzun?","Hangisinde aynı isim var?"],"a":0,"why":"Tam tematik uyum belirleyicidir."},{"q":"Bu bölümde kaç seçenek kullanılmadan kalabilir?","o":["Hiç","Birden fazla","Her zaman tam üç"],"a":1,"why":"8 seçenek 5 kişiye eşleştirilir; çeldiriciler kalır."}]}],"production":{"task":"Bir kişi profili seç ve ihtiyacını 2 cümlede Almanca parafraz et; ardından hangi makale türünün uygun olduğunu 2–3 cümlede gerekçelendir.","target":"Metindeki kelimeleri kopyalamadan “ne arıyor / ne aramıyor?” ayrımını kur.","example":"Sie sucht vor allem praktische Unterstützung für ein schwieriges Gespräch über ihre Arbeitsbelastung. Ein allgemeiner Artikel über Stress würde daher nicht ausreichen. Passend wäre ein Beitrag, der konkrete Gesprächsstrategien mit Vorgesetzten erklärt.","mode":"write","minChars":60,"checklist":[]}},{"id":22,"unit":"DTB C1 · Lesen","title":"Lesen Teil 2: talimat ve işyeri kurallarında ayrıntı","skills":["Okuma","Detay"],"goal":"İki işyeri metninde 2 Richtig/Falsch ve 2 Multiple-Choice sorusunu ayrıntıya göre çözmek.","explanation":"Bu bölüm yönerge, çalışan el kitabı, güvenlik veya veri koruma metinleri kullanabilir. R/F sorusunda cümledeki her parçanın doğru olması gerekir; MC’de metne yakın görünen ama zorunluluk/olasılık farkını değiştiren seçeneklere dikkat et.","examples":[["Der Ausweis kann als Zugangskarte dienen; daraus folgt nicht, dass er immer zum Bezahlen verwendet werden muss.","Kart giriş için kullanılabilir; bu, ödeme için zorunlu olduğu anlamına gelmez.","modalite ayrımı."],["„sollte“ ist nicht automatisch dasselbe wie „muss“.","“sollte” her zaman “muss” değildir.","R/F çeldiricisi."],["Achte auf Einschränkungen wie „nur“, „möglichst“, „unter der Voraussetzung“.","“nur”, “möglichst”, “unter der Voraussetzung” gibi sınırlamalara dikkat et.","ayrıntı sinyalleri."]],"activities":[{"id":"lv2-set","type":"reading","title":"Betriebliche Unterweisung","intro":"","text":"Alle Beschäftigten erhalten am ersten Arbeitstag einen persönlichen Zugangsausweis. Er öffnet die normalen Bürobereiche; für das Labor ist zusätzlich eine Freischaltung durch die Sicherheitsstelle erforderlich. Der Ausweis soll auf dem Firmengelände möglichst mitgeführt werden. Für private Nebentätigkeiten gilt: Sie müssen vor Aufnahme schriftlich angezeigt werden. Untersagt werden können sie nur, wenn betriebliche Interessen beeinträchtigt werden.\n\nPersonenbezogene Kundendaten dürfen ausschließlich in den vorgesehenen Systemen verarbeitet werden. Private Cloud-Speicher sind nicht zulässig. Bei Unsicherheit wenden sich Beschäftigte zunächst an ihre direkte Führungskraft; diese kann die Datenschutzstelle einbeziehen.","questions":[{"q":"Der Zugangsausweis öffnet ohne weitere Freischaltung auch das Labor.","o":["richtig","falsch"],"a":1,"why":"Labor için ek Freischaltung gerekir."},{"q":"Nebentätigkeiten müssen vor Beginn schriftlich gemeldet werden.","o":["richtig","falsch"],"a":0,"why":"Metinde açıkça “vor Aufnahme schriftlich angezeigt”."},{"q":"Für das Labor gilt:","o":["Der normale Ausweis reicht immer.","Es ist eine zusätzliche Freischaltung nötig.","Nur Gäste brauchen eine Freischaltung."],"a":1,"why":"Ek yetkilendirme zorunludur."},{"q":"Bei Datenschutzfragen sollen Mitarbeitende zunächst …","o":["private Cloud nutzen","die direkte Führungskraft ansprechen","den Kunden kontaktieren"],"a":1,"why":"Metin ilk başvuru noktasını belirtir."}]},{"id":"lv2-traps","type":"mc","title":"Çeldirici mantığı","intro":"","questions":[{"q":"“möglichst mitführen” ile “immer mitführen müssen” aynı mı?","o":["Evet","Hayır"],"a":1,"why":"Tavsiye/tercih ile zorunluluk farklıdır."},{"q":"R/F’de bir cümlenin yarısı doğru, yarısı yanlışsa?","o":["richtig","falsch"],"a":1,"why":"Tüm iddia doğru olmalıdır."}]}],"production":{"task":"Yukarıdaki kurallardan ikisini bir yeni çalışana 4–5 cümlede açıkla.","target":"Zorunluluk ve öneri derecesini koru; “müssen/dürfen/sollen”i doğru seç.","example":"Du musst eine Nebentätigkeit vor Beginn schriftlich melden. Der normale Zugangsausweis reicht für das Labor allerdings nicht aus; dafür brauchst du eine zusätzliche Freischaltung. Auf dem Firmengelände solltest du den Ausweis möglichst bei dir tragen.","mode":"write","minChars":60,"checklist":[]}},{"id":23,"unit":"DTB C1 · Lesen","title":"Lesen Teil 3: sorun ↔ tavsiye eşleştirme ve x seçeneği","skills":["Okuma","Seçici okuma"],"goal":"4 işyeri sorununu 6 tavsiye metniyle eşleştirmek; uygun tavsiye yoksa x seçmek.","explanation":"Bu bölümde en zor nokta “yakın ama çözmeyen” tavsiyedir. Sorunun temel ihtiyacını tanımla: hukuki bilgi mi, zaman yönetimi mi, ilişki sınırları mı, ulaşım mı? Sonra tavsiyenin aynı temel ihtiyaca gerçekten cevap verip vermediğini kontrol et.","examples":[["Ein ähnliches Thema reicht nicht; der Tipp muss das konkrete Problem bearbeiten.","Benzer konu yetmez; tavsiye somut sorunu çözmeli.","x seçeneği önemlidir."],["Wenn kein Tipp passt, ist x die korrekte Lösung.","Hiçbiri uymuyorsa x doğrudur.","zorla eşleştirme yapma."],["Problemkern: „Pendeln kostet täglich drei Stunden“ → Lösung muss Mobilität/Arbeitszeit betreffen.","Sorunun çekirdeğini ayır.","seçici okuma."]],"activities":[{"id":"lv3-set","type":"match","title":"4 sorun → 6 tavsiye (+ x)","intro":"","prompts":["Nora arbeitet mit ihrem Bruder im Familienbetrieb. Private Konflikte landen ständig im Büro.","Mert pendelt täglich fast drei Stunden und sieht seine Familie kaum.","Selin soll dauerhaft mehr Aufgaben übernehmen, bekommt aber weder Zeit noch Prioritäten angepasst.","Can möchte für ein Jahr aus familiären Gründen beruflich pausieren und sucht Informationen über mögliche Modelle."],"options":["A · Ein Coach kann helfen, persönliche Grenzen und Rollen im Familienbetrieb klarer zu trennen.","B · Flexible Startzeiten oder mehrere Homeoffice-Tage können lange Pendelzeiten reduzieren.","C · Führe ein Priorisierungsgespräch und dokumentiere, welche Aufgaben mit der vorhandenen Kapazität realistisch sind.","D · Nutze ein neues Zeiterfassungstool für Projekte.","E · In manchen Betrieben sind Sabbatical- oder unbezahlte Freistellungsmodelle möglich; kläre Voraussetzungen mit HR.","F · Ein Sprachkurs kann die Teamkommunikation verbessern.","X · kein passender Tipp"],"answers":[0,1,2,4],"why":[]},{"id":"lv3-strat","type":"mc","title":"Eşleştirme kararı","intro":"","questions":[{"q":"Bir tavsiye aynı kelimeyi kullanıyor ama sorunu çözmüyorsa?","o":["Yine de eşleştir","Eşleştirme; başka seçenek veya x ara"],"a":1,"why":"Ana ihtiyaca cevap şarttır."},{"q":"x ne zaman seçilir?","o":["Hiçbir tavsiye temel probleme uygun değilse","Metin uzunsa","Kelime bilinmiyorsa"],"a":0,"why":"x gerçek bir seçenektir."}]}],"production":{"task":"Sorunlardan birini seç ve 4–6 cümlelik C1 tavsiyesi yaz.","target":"Öneri + gerekçe + olası alternatif kullan; “an deiner Stelle”, “es wäre sinnvoll”, “unter Umständen” gibi yapılar ekle.","example":"An deiner Stelle würde ich zunächst ein strukturiertes Gespräch über Prioritäten führen. Es wäre sinnvoll, konkret zu zeigen, welche Aufgaben mit der aktuellen Kapazität nicht realistisch sind. Falls sich intern keine Lösung findet, könnte anschließend die Personalabteilung einbezogen werden.","mode":"write","minChars":60,"checklist":[]}},{"id":24,"unit":"DTB C1 · Lesen","title":"Lesen Teil 4: toplantı tutanağında karar ve sorumluluk","skills":["Okuma","Detay","Mediation"],"goal":"Uzun bir toplantı tutanağında 5 MC ile karar, gerekçe, sorumlu bölüm ve son tarihi bulmak.","explanation":"Tutanakta “X schlägt vor” bir öneridir; “die Geschäftsführung beschließt/beauftragt” ise karar/görevdir. Soru kökündeki özneye göre doğru paragrafı taramak, tüm metni eşit yoğunlukla okumaktan daha hızlıdır.","examples":[["Der Vertrieb schlägt eine Ausnahme vor; beschlossen ist sie damit noch nicht.","Satış istisna öneriyor; bu henüz karar değil.","görüş ≠ karar."],["Die IT wird beauftragt, bis Ende des Monats einen Plan vorzulegen.","BT ay sonuna kadar plan sunmakla görevlendiriliyor.","görev + deadline."],["Achte auf Namen, Abteilungen, Fristen und Modalverben.","İsim, bölüm, süre ve kip fiillerine dikkat et.","tarama stratejisi."]],"activities":[{"id":"lv4-set","type":"reading","title":"Abteilungsbesprechung","intro":"","text":"TOP 1 Kundenservice: Vertrieb berichtet über zunehmende Beschwerden wegen langer Antwortzeiten. Kundenservice erklärt, dass zwei Stellen unbesetzt sind. Die Geschäftsführung beschließt, für sechs Wochen eine interne Unterstützung aus dem Backoffice einzusetzen. Personal soll parallel die offenen Stellen neu ausschreiben.\n\nTOP 2 Software: IT schlägt vor, das Ticketsystem zu erweitern. Finanzen weist auf zusätzliche Lizenzkosten hin. Die Geschäftsführung beauftragt IT, bis zum 30. September zwei Varianten mit Kostenvergleich vorzulegen.\n\nTOP 3 Lieferqualität: Logistik berichtet über eine steigende Zahl verspäteter Sendungen. Einkauf möchte den Dienstleister sofort wechseln. Die Geschäftsführung hält einen sofortigen Wechsel für verfrüht und verlangt zunächst eine vierwöchige Messung der Lieferzeiten. Logistik soll die Ergebnisse anschließend vorstellen.","questions":[{"q":"Wie reagiert die Geschäftsführung auf die langen Antwortzeiten?","o":["Sie schließt den Kundenservice.","Sie setzt vorübergehend interne Unterstützung ein.","Sie verschiebt alle Anfragen."],"a":1,"why":"Altı haftalık Backoffice desteği kararlaştırılır."},{"q":"Was soll Personal tun?","o":["Offene Stellen neu ausschreiben","Software kaufen","Lieferzeiten messen"],"a":0,"why":"Personel paralel olarak ilanları yenileyecek."},{"q":"Was muss IT bis 30. September liefern?","o":["Nur eine Rechnung","Zwei Varianten mit Kostenvergleich","Einen neuen Dienstleister"],"a":1,"why":"Görev açıkça belirtilir."},{"q":"Warum wird der Lieferdienstleister nicht sofort gewechselt?","o":["Weil es keine Beschwerden gibt","Weil zunächst Daten über vier Wochen erhoben werden sollen","Weil Einkauf dagegen ist"],"a":1,"why":"Önce ölçüm istenir."},{"q":"Wer präsentiert später die Messergebnisse?","o":["Logistik","Finanzen","Personal"],"a":0,"why":"Logistik görevlidir."}]}],"production":{"task":"Mini-Protokollü 5 cümlede yönetici özeti olarak yaz.","target":"Üç TOP’tan her biri için karar veya sonraki adımı seç; önerilerle kararları karıştırma.","example":"Für den Kundenservice wird vorübergehend Unterstützung aus dem Backoffice eingesetzt, während Personal die offenen Stellen neu ausschreibt. Die IT soll bis Ende September zwei Varianten für das Ticketsystem vergleichen. Beim Lieferdienstleister wird noch keine Entscheidung getroffen; zunächst misst die Logistik vier Wochen lang die Lieferzeiten und stellt die Ergebnisse anschließend vor.","mode":"write","minChars":60,"checklist":[]}},{"id":25,"unit":"DTB C1 · Lesen + Schreiben","title":"Lesen und Schreiben: müşteri e-postasını anla ve profesyonel yanıtla","skills":["Okuma","Yazma","Mediation"],"goal":"Önce 2 MC ile bağlamı doğru anlamak, sonra ekip liderinin talimatını uygun müşteri diline dönüştürmek.","explanation":"Bu görevde içerik ve kayıt birlikte ölçülür. Üstünün iç mesajı kaba, kısaltılmış veya duygusal olabilir; sen bunu müşteriye doğrudan aktarmamalısın. Önce olguyu doğrula, sonra uygun iletişim işlevlerini kur: kabul/empati, açıklama, çözüm, sonraki adım.","examples":[["Interne Anweisung: „Die sollen das selbst regeln!“ → Kundenmail: „Wir möchten den Vorgang zunächst gemeinsam klären.“","İç talimatı doğrudan kopyalama.","register dönüşümü."],["Vielen Dank für Ihren Hinweis. Wir prüfen derzeit, an welcher Stelle der Fehler entstanden ist.","Nazik kabul + temkin.","profesyonel e-posta."],["Wir melden uns spätestens morgen mit einem konkreten Lösungsvorschlag.","Somut sonraki adım.","eylem odaklı."]],"activities":[{"id":"rw-set","type":"reading","title":"Kundenfall","intro":"","text":"Teamleitung: „Bitte übernimm das. Der Kunde behauptet, dass unsere Montage die Oberfläche beschädigt hat. Wir sind aber nicht sicher, ob das Material schon vorher einen Fehler hatte. Frag nach Fotos und der Chargennummer. Wenn wir das geprüft haben, bieten wir notfalls einen Vor-Ort-Termin an.“\n\nKunde: „Nach der Montage zeigen mehrere Paneele feine Risse. Vorher waren sie meiner Meinung nach einwandfrei. Bitte teilen Sie mir mit, wie Sie das Problem lösen wollen.“","questions":[{"q":"Was ist noch ungeklärt?","o":["Ob überhaupt Risse existieren","Ob Materialfehler oder Montage die Ursache ist","Ob der Kunde eine Rechnung hat"],"a":1,"why":"Nedeni kesin değil."},{"q":"Was soll zuerst angefordert werden?","o":["Fotos und Chargennummer","Neue Bestellung","Zahlungserinnerung"],"a":0,"why":"Ekip liderinin ilk talimatı budur."}]}],"production":{"task":"Müşteriye 100–140 kelimelik profesyonel e-posta yaz. Fotoğraf ve Chargennummer iste; nedeni kesinleştirmeden açıklama yap; kontrol sonrası olası Vor-Ort-Termin belirt.","target":"DTB yazma kriterlerine göre: Aufgabenbewältigung + klare Struktur + formale Richtigkeit + breites sprachliches Spektrum.","example":"Sehr geehrter Herr Klein,\n\nvielen Dank für Ihre Nachricht. Wir bedauern, dass nach der Montage Risse sichtbar geworden sind. Die genaue Ursache lässt sich anhand der bisherigen Informationen noch nicht abschließend beurteilen. Damit wir den Vorgang zuverlässig prüfen können, senden Sie uns bitte einige Fotos der betroffenen Paneele sowie die Chargennummer des Materials. Sobald uns diese Angaben vorliegen, prüfen wir den Fall umgehend. Falls sich die Ursache auf diesem Weg nicht eindeutig klären lässt, vereinbaren wir gerne einen Vor-Ort-Termin.\n\nMit freundlichen Grüßen","mode":"write","minChars":180,"checklist":["Adresat ve resmî kayıt uygun","Tüm iç talimatlar uygulandı","Neden konusunda temkinli dil","Somut sonraki adım ve çözüm"]}},{"id":26,"unit":"DTB C1 · Hören","title":"Hören Teil 1: üç işyeri konuşması, R/F + MC","skills":["Dinleme","Detay"],"goal":"Üç kısa konuşmayı bir kez dinleyip her biri için bir R/F ve bir MC çözmek.","explanation":"İlk soru genellikle genel durumu, ikinci soru ayrıntılı niyeti/öneriyi test eder. Dinlemeden önce iki soruyu oku; konuşmada görüş değişikliği veya “zunächst … aber …” gibi dönüşlere dikkat et.","examples":[["Wir brauchen zwar eine interne Lösung, ich würde aber zunächst ein externes Angebot einholen.","İlk fikirle nihai öneri farklı olabilir.","dönüş sinyali."],["Entscheidend ist, was am Ende vorgeschlagen oder beschlossen wird.","Son öneri/karar kritik.","detay dinleme."],["Zahlen, Zeiträume und Verantwortlichkeiten sind typische Prüfdetails.","Rakam, süre, sorumluluk tipik ayrıntıdır.","not alma."]],"activities":[{"id":"hv1-a","type":"listening","title":"Gespräch 1","intro":"","script":"TEAMLEITERIN: Im Projektteam fallen zwei Personen für mindestens sechs Wochen aus. Ich möchte vermeiden, dass die übrigen Kolleginnen dauerhaft Überstunden machen. VORGESETZTER: Können wir intern vertreten? TEAMLEITERIN: Teilweise. Für die technische Dokumentation fehlt uns aber die Fachkenntnis. Ich würde deshalb ein befristetes Angebot einer externen Spezialistin einholen und parallel Aufgaben neu priorisieren. VORGESETZTER: Gut. Holen Sie ein Angebot ein und legen Sie mir zusätzlich eine interne Alternative vor.","questions":[{"q":"Die Teamleiterin möchte die Mehrbelastung des Teams begrenzen.","o":["richtig","falsch"],"a":0,"why":"Açıkça sürekli fazla mesaiyi önlemek istiyor."},{"q":"Was soll sie als Nächstes tun?","o":["Nur Überstunden anordnen","Externes Angebot und interne Alternative vorbereiten","Das Projekt sofort abbrechen"],"a":1,"why":"Yönetici iki seçeneği istiyor."}],"plays":1},{"id":"hv1-b","type":"listening","title":"Gespräch 2","intro":"","script":"QM: Unsere Fehlerquote ist im letzten Quartal von 3,2 auf 4,1 Prozent gestiegen. Besonders häufig sind falsche Etiketten. MITARBEITER: Liegt das an der Maschine? QM: Teilweise, aber häufiger werden die Einstellungen nach Produktwechseln nicht vollständig kontrolliert. Deshalb führen wir ab Montag eine kurze Checkliste ein. Nach vier Wochen vergleichen wir die Zahlen erneut.","questions":[{"q":"Die Fehlerquote ist gesunken.","o":["richtig","falsch"],"a":1,"why":"3,2’den 4,1’e yükselmiş."},{"q":"Welche Maßnahme wird eingeführt?","o":["Neue Maschine kaufen","Checkliste nach Produktwechseln","Etiketten abschaffen"],"a":1,"why":"Pazartesiden itibaren kontrol listesi."}],"plays":1},{"id":"hv1-c","type":"listening","title":"Gespräch 3","intro":"","script":"VERTRIEB: Wir möchten unsere neue Produktlinie stärker bei kleineren Fachhändlern platzieren. HÄNDLER: Ich bin noch unsicher, ob die Nachfrage reicht. VERTRIEB: Für Neukunden bieten wir in den ersten drei Monaten flexible Mindestmengen und ein Einführungsrabatt an. HÄNDLER: Dann schicken Sie mir bitte die Konditionen; ich prüfe das.","questions":[{"q":"Der Vertrieb möchte neue Kunden gewinnen.","o":["richtig","falsch"],"a":0,"why":"Yeni Fachhändler hedefleniyor."},{"q":"Was überzeugt den Händler zumindest zu einer Prüfung?","o":["Flexible Mindestmengen und Rabatt","Längere Lieferzeit","Höhere Mindestbestellung"],"a":0,"why":"Koşullar daha cazip."}],"plays":1}],"production":{"task":"Üç konuşmadan birini 4–5 cümlede yazılı olarak özetle: sorun, öneri ve sonraki adım.","target":"Kelimeleri kopyalamadan ana durumu ve son kararı aktar.","example":"Im Projektteam fehlen für mehrere Wochen zwei Personen. Um dauerhafte Überstunden zu vermeiden, sollen Aufgaben neu priorisiert werden. Für einen spezialisierten Bereich wird zusätzlich ein externes Angebot eingeholt. Die Teamleiterin soll der Führungskraft sowohl diese Option als auch eine interne Alternative vorlegen.","mode":"write","minChars":60,"checklist":[]}},{"id":27,"unit":"DTB C1 · Hören","title":"Hören Teil 2: dört konuşmada ana argümanı eşleştirme","skills":["Dinleme","Ana fikir"],"goal":"Dört kısa konuşmayı bir kez dinleyip 6 ifadeden 4 ana görüşü seçmek.","explanation":"Burada ayrıntı değil “konuşmacının asıl mesajı” önemlidir. Her konuşma için tek cümlelik sonuç çıkar: “Der Sprecher meint, dass …”. Benzer seçeneklerde görüşün yönüne (olumlu/olumsuz/koşullu) dikkat et.","examples":[["Ein Abteilungswechsel kann Entwicklung ermöglichen.","Bölüm değişimi gelişim fırsatı olabilir.","ana argüman örneği."],["Häufige Umstrukturierung löst nicht automatisch strukturelle Probleme.","Sık yeniden yapılanma sorunları otomatik çözmez.","ana fikir."],["Offene Projektstrukturen können flexibler sein, wenn Rollen klar bleiben.","Açık proje yapıları rol netliğiyle esnek olabilir.","koşullu görüş."]],"activities":[{"id":"hv2-set","type":"listening","title":"Vier Kurzgespräche","intro":"","script":"1) MITARBEITER: Ich würde gern in den Vertrieb wechseln. Dort könnte ich meine Kundenkenntnis besser einsetzen. KOLLEGIN: Schade fürs Team, aber für deine Entwicklung wäre das sicher eine Chance.\n\n2) KOLLEGE A: Schon wieder wird unsere Abteilung neu organisiert. KOLLEGE B: Genau das stört mich. Wir verschieben ständig Zuständigkeiten, ohne die eigentlichen Prozessprobleme zu lösen.\n\n3) LEITUNG: Künftig arbeiten wir projektbezogen statt in starren Abteilungen. MITARBEITERIN: Das finde ich sinnvoll, solange Rollen und Ansprechpartner trotzdem klar bleiben.\n\n4) TEAMLEITERIN: Zwei Mitarbeitende ziehen die Stimmung herunter. KOLLEGE: Vielleicht wäre eine Versetzung für eine Person ein Neustart und würde das Team entlasten.","questions":[{"q":"Gespräch 1","o":["Ein interner Wechsel kann Entwicklungschancen eröffnen.","Umstrukturierung löst keine Probleme.","Starre Abteilungen sind immer besser.","Eine Versetzung kann Teamprobleme entschärfen.","Projektarbeit funktioniert nur ohne Rollen.","Kündigung ist die einzige Lösung."],"a":0,"why":"Kariyer gelişimi vurgulanır."},{"q":"Gespräch 2","o":["Ein interner Wechsel kann Entwicklungschancen eröffnen.","Umstrukturierung löst keine Probleme.","Starre Abteilungen sind immer besser.","Eine Versetzung kann Teamprobleme entschärfen.","Projektarbeit funktioniert nur ohne Rollen.","Kündigung ist die einzige Lösung."],"a":1,"why":"Asıl eleştiri tekrarlanan yapı değişikliğinin kök sorunu çözmemesi."},{"q":"Gespräch 3","o":["Ein interner Wechsel kann Entwicklungschancen eröffnen.","Umstrukturierung löst keine Probleme.","Projektbezogene Strukturen können sinnvoll sein, wenn Zuständigkeiten klar bleiben.","Eine Versetzung kann Teamprobleme entschärfen.","Projektarbeit funktioniert nur ohne Rollen.","Kündigung ist die einzige Lösung."],"a":2,"why":"Esneklik + rol netliği koşulu."},{"q":"Gespräch 4","o":["Ein interner Wechsel kann Entwicklungschancen eröffnen.","Umstrukturierung löst keine Probleme.","Starre Abteilungen sind immer besser.","Eine Versetzung kann Teamprobleme entschärfen.","Projektarbeit funktioniert nur ohne Rollen.","Kündigung ist die einzige Lösung."],"a":3,"why":"Versetzung bir yeniden başlangıç olarak önerilir."}],"plays":1},{"id":"hv2-focus","type":"mc","title":"Ana fikir mi ayrıntı mı?","intro":"","questions":[{"q":"Konuşmacı örnek olarak bütçeden bahsediyor ama sonunda “trotzdem sollten wir testen” diyor. Ana mesaj?","o":["Bütçe tek konudur","Deneme yapılmasını destekliyor","Hiç görüşü yok"],"a":1,"why":"Son konum/argüman ana fikri belirler."},{"q":"Bir seçenek metindeki tek bir ayrıntıyı doğru söylüyor ama görüşü özetlemiyorsa?","o":["Doğrudur","Muhtemelen çeldiricidir"],"a":1,"why":"Teil 2 ana argüman eşleştirmesidir."}]}],"production":{"task":"Dört konuşmadan birinin ana görüşünü 3–4 cümlede kendi sözlerinle açıkla ve bir gerekçe ekle.","target":"“Der Sprecher vertritt die Auffassung, dass …” gibi bir çerçeve kullan; ayrıntıyı ana fikirden ayır.","example":"Die Gesprächspartnerin hält einen internen Wechsel grundsätzlich für sinnvoll, weil er neue Entwicklungsmöglichkeiten eröffnen kann. Sie erkennt zwar an, dass das bisherige Team dadurch belastet werden könnte, sieht darin aber keinen ausreichenden Grund, die berufliche Entwicklung zu blockieren.","mode":"write","minChars":60,"checklist":[]}},{"id":28,"unit":"DTB C1 · Hören","title":"Hören Teil 3: şirket sunumunda yapı, rakam ve sonuç","skills":["Dinleme","Not alma"],"goal":"Bir şirket sunumunu bir kez dinleyip 4 MC çözmek; bölüm yapısını ve rakamsal eğilimleri izlemek.","explanation":"Uzun sunumda her ayrıntıyı yazmaya çalışma. Başlıkları zihinsel olarak ayır: örn. Umsatz, Produkt, Personal, Ausblick. Rakamın kendisinden çok artış/azalış, hedefe ulaşılıp ulaşılmadığı ve sonraki adım sorulabilir.","examples":[["Der Umsatz ist gestiegen, obwohl eine Produktlinie hinter den Erwartungen blieb.","Bir ürün hedefin altında olsa da ciro arttı.","karşıt bilgi."],["Die Zahlen werden zusammengefasst; nicht jede Einzelposition wird erläutert.","Rakamlar özetlenir; tüm ayrıntılar açıklanmaz.","sunum yapısı."],["Personalentscheidungen werden erst nach der Hochsaison getroffen.","Personel kararı yoğun dönem sonrası.","zaman ayrıntısı."]],"activities":[{"id":"hv3-set","type":"listening","title":"Unternehmenspräsentation","intro":"","script":"Guten Morgen zusammen. Ich möchte Ihnen heute einen Überblick über das vergangene Geschäftsjahr und unsere Planung geben. Zunächst zum Umsatz: Insgesamt haben wir ein Plus von 4,2 Prozent erzielt. Besonders stark war der Bereich Wartungsverträge. Unsere neue Online-Schulung blieb dagegen hinter den Erwartungen; hier wurden nur rund 70 Prozent des geplanten Umsatzes erreicht. Für das laufende Jahr wollen wir deshalb das Marketing neu ausrichten.\n\nZum Personal: Aktuell beschäftigen wir 186 feste Mitarbeitende und 12 Zeitarbeitskräfte. Aufgrund der guten Auftragslage möchten wir grundsätzlich zusätzliche feste Stellen schaffen. Die endgültige Entscheidung treffen wir jedoch erst nach dem zweiten Quartal, wenn wir die Entwicklung der Auftragseingänge besser beurteilen können.\n\nAbschließend zur Digitalisierung: Das neue Ticketsystem wurde in zwei Abteilungen erfolgreich getestet. Bis Jahresende soll es schrittweise im gesamten Unternehmen eingeführt werden.","questions":[{"q":"Was gilt für den Gesamtumsatz?","o":["Er ist gesunken.","Er ist um 4,2 Prozent gestiegen.","Er blieb unverändert."],"a":1,"why":"Plus 4,2 Prozent."},{"q":"Welche Produktlinie blieb hinter der Planung?","o":["Wartungsverträge","Online-Schulung","Ticketsystem"],"a":1,"why":"Yalnızca %70 hedefe ulaşmış."},{"q":"Wann wird endgültig über neue feste Stellen entschieden?","o":["sofort","nach dem zweiten Quartal","erst in drei Jahren"],"a":1,"why":"İkinci çeyrek sonrası."},{"q":"Was soll bis Jahresende passieren?","o":["Ticketsystem im ganzen Unternehmen einführen","Online-Schulung einstellen","Zeitarbeit komplett abschaffen"],"a":0,"why":"Kademeli şirket genel yayılım."}],"plays":1},{"id":"note-headings","type":"match","title":"Not başlığı → bilgi","intro":"","prompts":["Umsatz","Produkt","Personal","Digitalisierung"],"options":["+4,2 % insgesamt","Online-Schulung nur 70 % Plan","Entscheidung über neue Stellen nach Q2","Ticketsystem bis Jahresende ausrollen"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Sunumu 5 cümlelik yönetici özeti olarak yaz.","target":"Dört başlıktan ana sonucu seç; bütün rakamları kopyalamadan eğilim + karar/eylem belirt.","example":"Das Unternehmen hat den Gesamtumsatz um 4,2 Prozent gesteigert. Die Online-Schulung blieb allerdings deutlich hinter dem Plan, weshalb das Marketing angepasst werden soll. Über zusätzliche feste Stellen wird erst nach dem zweiten Quartal entschieden. Das erfolgreich getestete Ticketsystem soll bis Jahresende im gesamten Unternehmen eingeführt werden.","mode":"write","minChars":60,"checklist":[]}},{"id":29,"unit":"DTB C1 · Hören","title":"Hören Teil 4: telefon mesajlarında niyet ve yapılacak iş","skills":["Dinleme","Seçici dinleme"],"goal":"Beş kısa telefon mesajını bir kez dinleyip her birinin temel amacını/eylemini seçmek.","explanation":"Telefon mesajlarında konuşmacı bazen uzun bir gerekçe verir, ancak soru tek bir eylemi hedefler: bilgi vermek, termin değiştirmek, geri arama istemek, yardım istemek, bir sonucu bildirmek. Son cümleler sık sık kritiktir.","examples":[["Könnten Sie den neuen Termin bitte kurz bestätigen?","Yeni randevuyu kısaca onaylar mısınız?","eylem talebi."],["Ich wollte Sie nur über das Ergebnis informieren.","Sizi yalnızca sonuç hakkında bilgilendirmek istedim.","bilgilendirme niyeti."],["Melden Sie sich bitte sofort, falls Sie übernehmen können.","Devralabilirseniz hemen haber verin.","acil yardım talebi."]],"activities":[{"id":"hv4-1","type":"listening","title":"Nachricht 1","intro":"","script":"Guten Morgen, hier ist Frau Reuter aus der Rechtsabteilung. Wir haben die Verhandlung mit dem Lieferanten abgeschlossen und konnten eine Einigung erzielen. Die Details finden Sie in der E-Mail von heute Morgen. Bitte prüfen Sie nur noch, ob wir die Vereinbarung so freigeben können.","questions":[{"q":"Was ist der Hauptzweck?","o":["Eine Sitzung ankündigen","Verhandlungsergebnis mitteilen und Freigabe erbitten","Eine Rechnung reklamieren"],"a":1,"why":"Sonuç + onay talebi."}],"plays":1},{"id":"hv4-2","type":"listening","title":"Nachricht 2","intro":"","script":"Hallo Deniz, hier Laura. Dein Termin um 14 Uhr ist ausgefallen. Ich habe den Termin mit Herrn Weber von 16 Uhr auf 14 Uhr vorgezogen, damit keine Lücke entsteht. Im Kalender ist alles schon aktualisiert.","questions":[{"q":"Was hat Laura getan?","o":["Termin storniert","Einen späteren Termin vorgezogen","Neuen Kunden abgesagt"],"a":1,"why":"16:00 randevusu 14:00’e alınmış."}],"plays":1},{"id":"hv4-3","type":"listening","title":"Nachricht 3","intro":"","script":"Guten Tag, Praxisservice Klein. Wegen eines Personalausfalls können wir die Reinigung am Freitag nicht wie geplant um 18 Uhr durchführen. Wäre es möglich, stattdessen am Samstagvormittag zu kommen? Bitte bestätigen Sie kurz per Mail.","questions":[{"q":"Was möchte der Anrufer?","o":["Termin komplett stornieren","Flexibleren Reinigungstermin vereinbaren","Neue Rechnung schicken"],"a":1,"why":"Cumartesi sabahı alternatif istenir."}],"plays":1},{"id":"hv4-4","type":"listening","title":"Nachricht 4","intro":"","script":"Hi, ich finde die Lieferung von Nordpaket nicht im Lager. Im System ist sie als angekommen verbucht, physisch ist sie aber nicht auffindbar. Kannst du bitte prüfen, an welchem Lagerplatz sie gescannt wurde?","questions":[{"q":"Was soll geprüft werden?","o":["Wo die Lieferung gescannt wurde","Ob ein Kunde bezahlt hat","Wer Urlaub hat"],"a":0,"why":"Sistemden Lagerplatz kontrolü istenir."}],"plays":1},{"id":"hv4-5","type":"listening","title":"Nachricht 5","intro":"","script":"Hallo zusammen, wir brauchen dringend jemanden für die Tour 7. Der Fahrer ist krank nach Hause gegangen und die ersten Lieferungen müssen in 20 Minuten raus. Wer übernehmen kann, meldet sich bitte sofort.","questions":[{"q":"Was wird gesucht?","o":["Jemand, der kurzfristig die Tour übernimmt","Ein neuer Lagerplatz","Ein Kundentermin"],"a":0,"why":"Acil Ersatzfahrer."}],"plays":1}],"production":{"task":"Beş mesajdan birini meslektaşına 3–4 cümlede aktar: kim, ne oldu, ne yapılmalı.","target":"Gerekçeyi kısalt; eylemi ve süreyi öne çıkar.","example":"Frau Klein vom Praxisservice hat angerufen. Wegen eines Personalausfalls kann die Reinigung am Freitagabend nicht stattfinden. Sie möchte stattdessen am Samstagvormittag kommen und bittet um eine kurze Bestätigung per E-Mail.","mode":"write","minChars":60,"checklist":[]}},{"id":30,"unit":"DTB C1 · Hören + Schreiben","title":"Hören und Schreiben: telefon notu, tek dinleme","skills":["Dinleme","Yazma","Mediation"],"goal":"Tek telefon mesajından arama nedeni + Name + Kontakt + weitere Informationen + zu erledigen alanlarını çıkarmak.","explanation":"Bu bölüm yalnızca 5 dakikadır ve mesaj bir kez dinlenir. Dinlemeden önce alanları hazırla. İsim/telefon gibi ayrıntıları mümkün olduğunca doğru, “weitere Informationen” ve “zu erledigen” alanlarını ise anlamı koruyarak kısa yaz.","examples":[["Grund für den Anruf: Bestellung / Buchung / Angebot / Beschwerde gibi kategori.","Arama nedeni kategorisi.","ön sınıflandırma."],["Weitere Informationen: sadece kararı etkileyen ayrıntılar.","Ek bilgi: yalnızca gerekli ayrıntılar.","seçici not."],["Zu erledigen: somut sonraki eylem + gerekiyorsa süre.","Yapılacak iş.","eylem odaklı."]],"activities":[{"id":"hw-set","type":"listening","title":"Telefonmitteilung","intro":"","script":"Guten Morgen, hier ist Frau Demir von EventPlus. Es geht um Ihre Buchung für die Firmenveranstaltung am 18. November. Den Raum können wir wie vereinbart reservieren. Allerdings steht die gewünschte Technik am Vormittag nicht zur Verfügung; ab 13 Uhr wäre sie verfügbar. Alternativ könnten wir Ihnen am Vormittag ein kleineres System ohne Aufpreis anbieten. Bitte teilen Sie uns bis morgen 12 Uhr mit, welche Variante Sie bevorzugen. Sie erreichen mich unter 069 440 18 22, Durchwahl 6.","questions":[{"q":"Grund für den Anruf?","o":["Angebot","Bestellung/Buchung","Beschwerde"],"a":1,"why":"Mevcut etkinlik rezervasyonu hakkında arıyor."},{"q":"Bis wann wird eine Rückmeldung benötigt?","o":["heute 18 Uhr","morgen 12 Uhr","nächste Woche"],"a":1,"why":"Yarın 12:00’ye kadar."}],"plays":1},{"id":"hw-fields","type":"match","title":"Mesajdaki bilgi → not alanı","intro":"","prompts":["Frau Demir, EventPlus","069 440 18 22, DW 6","Technik vormittags nicht verfügbar; ab 13 Uhr möglich oder kleineres System vormittags","bis morgen 12 Uhr Variante mitteilen"],"options":["Name/Firma","Kontakt","Weitere Informationen","Zu erledigen"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Mesaj için gerçek sınavdaki gibi kısa telefon notu yaz.","target":"Dört alanı başlıklarla ayır; uzun cümle yerine yoğun, doğru bilgi kullan.","example":"Name/Firma: Frau Demir, EventPlus\nKontakt: 069 440 18 22, DW 6\nWeitere Informationen: gewünschte Technik erst ab 13 Uhr; alternativ kleineres System vormittags ohne Aufpreis\nZu erledigen: bis morgen 12 Uhr bevorzugte Variante mitteilen","mode":"write","minChars":70,"checklist":[]}},{"id":31,"unit":"DTB C1 · Sprachbausteine","title":"Sprachbausteine Teil 1: 10 kelimeden 6 boşluk","skills":["Dilbilgisi","Kelime","Yazma"],"goal":"İş e-postasında 10 seçenekten 6 doğru kelimeyi bağlam, eşdizim ve dilbilgisine göre seçmek.","explanation":"Bu görev sadece kelime anlamı değil, tipik işyeri eşdizimlerini ve metin mantığını test eder. Her seçeneği bir kez kullan; kullanılmayan çeldiriciler vardır. Önce boşluğun sözcük türünü ve sabit kalıbı belirle.","examples":[["auf eine Frist verzichten","bir süreden feragat etmek","fiil + Präposition."],["unter bestimmten Bedingungen","belirli koşullar altında","sabit ifade."],["zu einem weiteren Gespräch kommen","başka bir görüşmeye gelmek","iş bağlamı."]],"activities":[{"id":"sb1-set","type":"cloze","title":"6 boşluk · 10 seçenek","intro":"","text":"Sehr geehrte Frau Baum, ___ habe ich meinen derzeitigen Arbeitgeber über den Wechsel informiert. Er ist bereit, auf einen Teil der Kündigungsfrist zu ___. Dadurch könnte ich die neue Stelle früher ___. Allerdings habe ich bereits eine Reise gebucht, die ich nur ungern ___. Könnten Sie mir bitte mitteilen, unter welchen ___ der frühere Beginn möglich wäre? Für die Klärung komme ich gern zu einem weiteren ___ in Ihr Haus.","blanks":[{"label":"1","options":["inzwischen","dagegen","Kauf","bestätigen","verzichten","antreten","stornieren","Bedingungen","Gespräch","immer"],"a":0,"why":"Metin zaman ilerlemesi gösterir."},{"label":"2","options":["inzwischen","dagegen","Kauf","bestätigen","verzichten","antreten","stornieren","Bedingungen","Gespräch","immer"],"a":4,"why":"auf ... verzichten."},{"label":"3","options":["inzwischen","dagegen","Kauf","bestätigen","verzichten","antreten","stornieren","Bedingungen","Gespräch","immer"],"a":5,"why":"eine Stelle antreten."},{"label":"4","options":["inzwischen","dagegen","Kauf","bestätigen","verzichten","antreten","stornieren","Bedingungen","Gespräch","immer"],"a":6,"why":"eine Reise stornieren."},{"label":"5","options":["inzwischen","dagegen","Kauf","bestätigen","verzichten","antreten","stornieren","Bedingungen","Gespräch","immer"],"a":7,"why":"unter welchen Bedingungen."},{"label":"6","options":["inzwischen","dagegen","Kauf","bestätigen","verzichten","antreten","stornieren","Bedingungen","Gespräch","immer"],"a":8,"why":"zu einem Gespräch kommen."}]}],"production":{"task":"Sprachbausteine’den 5 işyeri kalıbını kullanarak 5–6 cümlelik kısa e-posta yaz.","target":"Kalıpları doğal bağlamda kullan; yalnızca listeleme yapma.","example":"Inzwischen habe ich meinen Arbeitgeber informiert. Er ist bereit, auf einen Teil der Kündigungsfrist zu verzichten, sodass ich die Stelle früher antreten könnte. Unter welchen Bedingungen wäre ein Beginn zum Monatsanfang möglich? Gern komme ich zur Klärung zu einem weiteren Gespräch.","mode":"write","minChars":60,"checklist":[]}},{"id":32,"unit":"DTB C1 · Sprachbausteine","title":"Sprachbausteine Teil 2: 6 üç seçenekli yapı","skills":["Dilbilgisi","Kelime","Nüans"],"goal":"Bağlam içinde deyimsel, yapısal ve bağlayıcı ifadelerden en uygun olanı seçmek.","explanation":"Teil 2’de seçenekler tek tek gramatik görünebilir; farkı bağlam ve sabit kullanım belirler: “wie befürchtet”, “jemanden vertrösten”, “aus meiner Sicht”, “etwas in Kauf nehmen”, “ob sich das … lässt”.","examples":[["Wie befürchtet fällt der Kollege länger aus.","Korkulduğu gibi meslektaş daha uzun süre yok.","sabit başlangıç."],["Wir sollten die zusätzliche Belastung in Kauf nehmen.","Ek yükü göze almalıyız.","deyimsel ifade."],["Bitte prüfen Sie, ob sich das so umsetzen lässt.","Bunun böyle uygulanıp uygulanamayacağını kontrol edin.","ob + reflexiv yapı."]],"activities":[{"id":"sb2-set","type":"cloze","title":"6 boşluk · her biri 3 seçenek","intro":"","text":"___ fällt unsere Kollegin länger aus. Das bedeutet ___, dass wir den Zeitplan anpassen müssen. Wenn wir den Kunden nicht weiter ___, sollten wir kurzfristig Aufgaben umverteilen. Das kann ___ anstrengend werden, wäre aber vertretbar. Die zusätzliche Belastung müssten wir vorübergehend ___. Bitte teilen Sie mir mit, ___ so organisieren lässt.","blanks":[{"label":"1","options":["Wie befürchtet","Ob zu befürchten","Als fürchten"],"a":0,"why":"Sabit zarf ifadesi."},{"label":"2","options":["dann wohl","wohl kaum nicht","erst gewesen"],"a":0,"why":"Muhtemel sonuç çıkarımı."},{"label":"3","options":["vertrösten wollen","vertrösten","trösten haben"],"a":1,"why":"Kunden vertrösten = ertelemek/oyalamak."},{"label":"4","options":["aus meiner Sicht","aus meinem Ansehen","zu meiner Ansicht"],"a":0,"why":"Doğru ifade “aus meiner Sicht”."},{"label":"5","options":["in Kauf nehmen","in Anspruch nehmen","zur Verfügung stehen"],"a":0,"why":"Olumsuz sonucu göze almak."},{"label":"6","options":["ob sich das","wann ihr das","wie mir dies"],"a":0,"why":"ob sich das ... organisieren lässt."}]}],"production":{"task":"C1 iş e-postasında bu yapılardan en az üçünü kullanarak 5–7 cümle yaz.","target":"Sabit ifadeyi doğru fiil/edatla kullan; bağlamı doğal tut.","example":"Wie befürchtet hat sich der Liefertermin erneut verschoben. Aus meiner Sicht sollten wir den Kunden nicht weiter vertrösten. Eine kurzfristige Umplanung wäre zwar aufwendig, diese Belastung müssten wir jedoch in Kauf nehmen. Bitte prüfen Sie, ob sich die Alternative bis Freitag umsetzen lässt.","mode":"write","minChars":60,"checklist":[]}},{"id":33,"unit":"DTB C1 · Schreiben","title":"Stellungnahme: pro/contra, örnek, görüş ve sonuç","skills":["Yazma","Argümantasyon"],"goal":"Yönetime yazılan Stellungnahme’yi açık yapılandırmak: konu çerçevesi, avantaj, dezavantaj, örnek, kendi görüşü, sonuç.","explanation":"Resmi görev, iki konudan birini seçip avantaj/dezavantaj tartmayı, örnek vermeyi, kendi görüşünü ve Fazit’i ister. C1 puanı için liste değil bağlantılı argüman gerekir. Her paragrafın bir işlevi olmalı.","examples":[["Einerseits kann die Maßnahme …, andererseits besteht das Risiko, dass …","İki yönlü tartışma.","pro/contra."],["Ein konkretes Beispiel dafür ist …","Somut örnek.","kanıt/gerekçe."],["Unter diesen Voraussetzungen überwiegen aus meiner Sicht die Vorteile.","Bu koşullarda bana göre avantajlar ağır basıyor.","nüanslı görüş."]],"activities":[{"id":"write-structure","type":"match","title":"Bölüm → işlev","intro":"","prompts":["Einleitung","Vorteil","Nachteil","Beispiel","eigener Standpunkt","Fazit"],"options":["Konuyu ve kararı çerçevelemek","Olumlu etkiyi gerekçelendirmek","Risk/maliyeti açıklamak","Argümanı somutlaştırmak","Kendi değerlendirmesini tartarak vermek","Sonuç/öneri ile bitirmek"],"answers":[0,1,2,3,4,5],"why":[]},{"id":"write-quality","type":"mc","title":"Argüman kalitesi","intro":"","questions":[{"q":"Hangisi daha C1 düzeyinde?","o":["Homeoffice ist gut. Es ist flexibel.","Homeoffice erhöht zwar die Flexibilität, kann jedoch die spontane Abstimmung im Team erschweren.","Homeoffice, ja."],"a":1,"why":"İki yönü bağlayıp nüans kurar."},{"q":"Fazit ne yapmalı?","o":["Yeni, alakasız konu açmalı","Argümanlardan türetilmiş sonuç/öneri vermeli","Metni yarıda bırakmalı"],"a":1,"why":"Sonuç önceki tartışmaya dayanır."},{"q":"Örnek neden gerekir?","o":["Sadece kelime sayısını artırmak için","Argümanı somutlaştırıp desteklemek için","Giriş yerine geçmek için"],"a":1,"why":"Gerekçeyi görünür kılar."}]}],"production":{"task":"180–230 kelimelik Stellungnahme yaz: “Şirket tüm ekipler için haftada iki zorunlu ofis günü getirmeyi düşünüyor.” Avantaj/dezavantaj, örnek, kendi görüş ve Fazit ekle.","target":"Net paragraflar, çeşitli bağlayıcılar, işyeri bağlamı ve dengeli argümantasyon kullan.","example":"Einheitliche Präsenztage können die Zusammenarbeit erleichtern, weil Besprechungen und spontane Abstimmungen planbarer werden. Gleichzeitig besteht jedoch das Risiko, dass Teams mit sehr unterschiedlichen Aufgaben unnötig an Flexibilität verlieren. Ein Beispiel sind Mitarbeitende, die überwiegend konzentrierte Einzelarbeit leisten und lange Arbeitswege haben. Aus meiner Sicht wäre deshalb ein verbindlicher Rahmen sinnvoll, sofern Ausnahmen für geeignete Tätigkeiten möglich bleiben. Abschließend würde ich ein Modell empfehlen, das gemeinsame Teamtage vorsieht, aber begründete Abweichungen zulässt.","mode":"write","minChars":350,"checklist":["Vorteil ve Nachteil var","En az bir somut örnek","Kendi görüş net ama nüanslı","Fazit önceki argümanlardan çıkıyor","Paragraflar ve bağlayıcılar açık"]}},{"id":34,"unit":"DTB C1 · Schreiben","title":"Resmî yazma değerlendirmesi: 4 kriteri aktif kullan","skills":["Yazma","Öz değerlendirme"],"goal":"Kendi metnini DTB’nin dört kriterine göre değerlendirmek ve zayıf noktayı somut revizyonla düzeltmek.","explanation":"Yazmada Kriter I görev/bağlam uyumunu; Kriter II metin örgüsü ve bağlantıları; Kriter III formel doğruluğu; Kriter IV kelime/yapı çeşitliliğini değerlendirir. C1 “hatasızlık” değil, karmaşık yapıları büyük ölçüde doğru ve esnek kullanma düzeyidir.","examples":[["Kriter I: Aufgabenbewältigung – görev gerçekten yerine getirildi mi?","İçerik ve adresat uyumu.","I"],["Kriter II: kommunikative Gestaltung – metin açık ve bağlı mı?","Yapı ve geçişler.","II"],["Kriter III: formale Richtigkeit – karmaşık yapılar büyük ölçüde doğru mu?","Gramer, yazım, noktalama.","III"],["Kriter IV: Spektrum – geniş kelime ve yapı repertuvarı var mı?","Çeşitlilik ve parafraz.","IV"]],"activities":[{"id":"rubric-map","type":"match","title":"Kriter → soru","intro":"","prompts":["I · Aufgabenbewältigung","II · Kommunikative Gestaltung","III · Formale Richtigkeit","IV · Spektrum sprachlicher Mittel"],"options":["Görev, durum ve resmiyet derecesi uygun mu?","Paragraflar ve bağlantılar mantıklı mı?","Karmaşık yapılar ve yazım büyük ölçüde doğru mu?","Kelime/yapı çeşitliliği ve parafraz yeterli mi?"],"answers":[0,1,2,3],"why":[]},{"id":"rubric-diagnose","type":"mc","title":"Sorunu teşhis et","intro":"","questions":[{"q":"Metin çok doğru ama görevin bir maddesini hiç işlemiyor. En doğrudan hangi kriter düşer?","o":["I Aufgabenbewältigung","III Richtigkeit","IV Spektrum"],"a":0,"why":"Görev içeriği eksik."},{"q":"Metin fikirleri art arda sıralıyor, geçiş yok.","o":["II Gestaltung","I Aufgabenbewältigung","IV Spektrum"],"a":0,"why":"Bağlantı ve yapı sorunu."},{"q":"Aynı “gut, machen, wichtig” sürekli tekrar ediliyor.","o":["IV Spektrum","II Gestaltung","I Aufgabenbewältigung"],"a":0,"why":"Kelime/yapı repertuvarı sınırlı."},{"q":"Çok sayıda karmaşık cümle var ama fiil konumu sıkça yanlış.","o":["III Formale Richtigkeit","IV Spektrum yalnız","I Aufgabenbewältigung"],"a":0,"why":"Doğruluk sorunu."}]}],"production":{"task":"Önce 160–220 kelimelik bir Stellungnahme yaz; sonra kendin için 4 satırlık revizyon notu ekle: I, II, III, IV kriterlerinde birer güçlü/zayıf nokta.","target":"Metni sadece tamamlamış olma; ölçütlere göre revize edilebilir hale getir.","example":"I: Tüm görev noktalarını ele aldım, ancak örneği daha somutlaştırabilirim.\nII: Paragraflar açık; ikinci ve üçüncü paragraf arasında geçiş eklemeliyim.\nIII: Konjunktiv II cümlelerindeki fiil sırasını tekrar kontrol etmeliyim.\nIV: “wichtig” yerine “entscheidend/maßgeblich” gibi ifadeleri çeşitlendirebilirim.","mode":"write","minChars":350,"checklist":[]}},{"id":35,"unit":"DTB C1 · Sprechen","title":"Sprechen Teil 1A: 2 dakikalık hazırlıksız monolog","skills":["Konuşma","Akıcılık"],"goal":"İki konudan birini seçip yaklaşık 2 dakika hazırlıksız, açık yapılı ve örnekli konuşmak.","explanation":"Model test 12 tema alanı verir. Amaç ezberlenmiş metin değil; temayı seçip hızlı yapı kurmaktır: giriş → 2–3 ana nokta → somut örnek → kısa sonuç. C1’de spontanlık ve uygun register önemlidir.","examples":[["Ich möchte das Thema aus drei Perspektiven betrachten.","Konuyu üç açıdan ele almak istiyorum.","yapı sinyali."],["Ein konkretes Beispiel aus meiner Berufserfahrung ist …","Mesleki deneyimimden somut bir örnek …","örnek."],["Zusammenfassend kommt es für mich vor allem darauf an, dass …","Özetle benim için esas olan …","sonuç."]],"activities":[{"id":"topic-bank","type":"info","title":"12 tema alanı","body":"Sınavda iki tema sunulur; bu bankadaki her alan için 60–120 saniye prova yap.","items":["Büyük etkisi olan bir mesleki karar ve sonuçları","Kendi eğitim/mesleki eğitim yolun ve güçlü/zayıf yönleri","Bir hizmetin hedef grubu, özellikleri, avantaj/dezavantajı","Bir ürünün üretim süreci ve gerekli beceriler","İyi bir yöneticinin özellikleri ve davranışı","Kendi iş fikrin: hedef grup, pazar, finansman","Serbest çalışma ile çalışan olmanın karşılaştırılması","Bir şirketi başarılı yapan faktörler","Müşteri bağlılığını güçlendiren faktörler","İş için yararlı olan veya olmasını istediğin bir uygulama","Başarılı bulduğun bir reklam kampanyası","Bir şirketin sosyal medyayı nasıl etkili kullandığı"]},{"id":"monolog-structure","type":"match","title":"Monolog bölümü → amaç","intro":"","prompts":["Giriş","Ana nokta 1/2","Örnek","Sonuç"],"options":["Konuyu ve planı çerçevelemek","Görüşü gerekçelendirmek","Soyut fikri somutlaştırmak","Ana mesajı kapatmak"],"answers":[0,1,2,3],"why":[]},{"id":"monolog-traps","type":"mc","title":"Sözlü strateji","intro":"","questions":[{"q":"Hazırlık süresi olmadığı için en iyi yaklaşım?","o":["Tam metin ezberlemek","Basit bir zihinsel yapı şablonu kullanmak","Uzun süre sessiz kalmak"],"a":1,"why":"Esnek yapı spontanlığı destekler."},{"q":"Konu zor gelirse?","o":["Hiç konuşmamak","Bildik bir örneğe bağlayıp açık yapı kurmak","Sadece tek cümle söylemek"],"a":1,"why":"Dil performansı ve iletişim ön plandadır."}]}],"production":{"task":"12 tema alanından birini seç ve yaklaşık 2 dakika Almanca konuşarak kaydet.","target":"Giriş + 2–3 ana nokta + örnek + sonuç; doğal tempo ve çeşitli C1 yapıları.","example":"Ich möchte kurz erläutern, was für mich eine gute Führungskraft ausmacht. Zunächst sind klare Kommunikation und verlässliche Entscheidungen entscheidend. Ebenso wichtig ist es, Verantwortung zu übertragen und konstruktives Feedback zu geben. In meinem bisherigen Arbeitsumfeld habe ich erlebt, dass Teams besonders motiviert arbeiten, wenn Ziele transparent sind. Zusammenfassend ist gute Führung für mich eine Verbindung aus Klarheit, Vertrauen und Konsequenz.","mode":"speak","minChars":0,"checklist":["≈2 dakika","Açık yapı","Somut örnek","Doğal ve spontan ifade"]}},{"id":36,"unit":"DTB C1 · Sprechen","title":"Sprechen Teil 1B: Prüferfragen’a spontan cevap","skills":["Konuşma","Etkileşim"],"goal":"Monolog sonrasında gelen derinleştirici sorulara doğrudan, gerekçeli ve örnekli cevap vermek.","explanation":"1B’de sınav görevlisi konuşmandaki içeriği derinleştirir. İyi cevap önce soruya doğrudan yanıt verir, sonra gerekçe/örnek ekler. Soruyu anlamadıysan nazikçe açıklama isteyebilirsin; ezberlenmiş metne dönme.","examples":[["Das hängt meines Erachtens stark davon ab, ob …","Bence bu büyük ölçüde … olup olmadığına bağlı.","nüanslı cevap."],["Ein konkretes Gegenbeispiel wäre …","Somut bir karşı örnek …","derinleştirme."],["Wenn ich Ihre Frage richtig verstehe, geht es darum, ob …","Sorunuzu doğru anlıyorsam mesele … olup olmadığı.","açıklama/teyit."]],"activities":[{"id":"question-types","type":"match","title":"Soru türü → cevap stratejisi","intro":"","prompts":["Beispiel?","Nachteil?","Vergleich?","Empfehlung?"],"options":["somut durum ver","kendi görüşünün sınırını kabul et","iki bağlamı ölçütlerle karşılaştır","eyleme dönük öneri + gerekçe"],"answers":[0,1,2,3],"why":[]},{"id":"followup","type":"mc","title":"Cevap kalitesi","intro":"","questions":[{"q":"Prüfer: „Welche Nachteile könnte das haben?“ En iyi başlangıç?","o":["Keine Ahnung.","Ein möglicher Nachteil wäre, dass …","Ich wiederhole meinen Vortrag."],"a":1,"why":"Soruyu doğrudan yanıtlar."},{"q":"Soruyu tam anlamadıysan?","o":["Tahmin ederek alakasız cevap ver","Nazikçe açıklama iste","Sessiz kal"],"a":1,"why":"Klärung istemek iletişim stratejisidir."},{"q":"Cevap uzunluğu nasıl olmalı?","o":["Sadece ja/nein","Soruyu cevaplayacak kadar geliştirilmiş, ama gereksiz monolog değil","Her zaman 5 dakika"],"a":1,"why":"Doğrudan + gerekçe + örnek yeterli."}]}],"production":{"task":"Şu üç soruya sırayla sesli cevap ver: 1) Können Sie ein konkretes Beispiel nennen? 2) Welche Nachteile könnte Ihre Position haben? 3) Was würden Sie einer Führungskraft konkret empfehlen?","target":"Her cevapta önce doğrudan yanıt, sonra kısa gerekçe veya örnek ver.","example":"Ein konkretes Beispiel aus meinem Arbeitsalltag ist die Einführung eines neuen Ticketsystems. Ein möglicher Nachteil besteht darin, dass die Umstellung zunächst zusätzliche Zeit kostet. Einer Führungskraft würde ich daher empfehlen, die Einführung schrittweise zu planen und frühzeitig Feedback aus dem Team einzuholen.","mode":"speak","minChars":0,"checklist":[]}},{"id":37,"unit":"DTB C1 · Sprechen","title":"Sprechen Teil 1C: partnerin söylediğini kendi sözlerinle açıklama","skills":["Konuşma","Mediation","Parafraz"],"goal":"Partnerin cevabındaki bir yönü yaklaşık 30 saniyede anlamı koruyarak yeniden açıklamak.","explanation":"1C aslında sözlü Mediation/parafrazdır. Sadece “Er hat gesagt …” deyip aynı kelimeleri tekrarlamak yeterli değildir. Önce ana noktayı belirle, sonra başka yapı/kelimelerle açıkla; gerekirse bağlamı kısaca ekle.","examples":[["Wenn ich ihn richtig verstanden habe, meint er im Kern, dass …","Doğru anladıysam özünde … demek istiyor.","parafraz giriş."],["Anders formuliert geht es darum, dass …","Başka biçimde söylersek mesele …","yeniden ifade."],["Sein entscheidender Punkt war nicht X, sondern Y.","Asıl noktası X değil Y idi.","odak belirleme."]],"activities":[{"id":"paraphrase-spoken","type":"mc","title":"Sözlü parafraz","intro":"","questions":[{"q":"Partner: „Homeoffice spart Pendelzeit, kann aber spontane Abstimmung erschweren.“ En iyi parafraz?","o":["Er sagt: Homeoffice spart Pendelzeit, kann aber spontane Abstimmung erschweren.","Im Kern sieht er einen Zeitgewinn, weist jedoch darauf hin, dass der informelle Austausch im Team schwieriger werden kann.","Homeoffice ist immer schlecht."],"a":1,"why":"Anlam korunur, kelimeler yeniden yapılandırılır."},{"q":"1C’de ne yapılmalı?","o":["Yeni kendi görüşünü uzun uzun anlatmak","Partnerin bir yönünü açıklamak","Soru sormadan susmak"],"a":1,"why":"Görev partnerin söylediğini açıklamaktır."}]},{"id":"para-tools","type":"match","title":"Parafraz aracı → işlev","intro":"","prompts":["im Kern","anders formuliert","entscheidend ist","damit meint er"],"options":["ana özü seçmek","başka yapıyla söylemek","odak noktasını belirtmek","referansı açıklamak"],"answers":[0,1,2,3],"why":[]}],"production":{"task":"Şu ifadeyi 30–45 saniyede kendi sözlerinle sesli açıkla: “Flexible Arbeitszeiten erhöhen die Autonomie, funktionieren aber nur, wenn Erreichbarkeit und Übergaben klar geregelt sind.”","target":"Aynı kelimeleri mümkün olduğunca tekrarlama; ana fikir + koşul ilişkisini koru.","example":"Anders formuliert meint die Aussage, dass Beschäftigte mehr Freiheit bei ihrer Arbeitszeit bekommen können. Diese Freiheit ist jedoch nur dann praktikabel, wenn im Team eindeutig festgelegt ist, wann jemand erreichbar ist und wie Aufgaben übergeben werden.","mode":"speak","minChars":0,"checklist":[]}},{"id":38,"unit":"DTB C1 · Sprechen","title":"Sprechen Teil 2: iş arkadaşlarıyla doğal informel sohbet","skills":["Konuşma","Etkileşim","Kayıt"],"goal":"Yaklaşık 3 dakika iki iş arkadaşı gibi doğal, informel ama anlaşılır biçimde tema geliştirmek.","explanation":"Teil 2 bir sunum değildir. Konuşmayı başlatmak, karşıdakinin söylediklerine tepki vermek, kısa kendi deneyimi eklemek ve soruyla konuşmayı geri vermek gerekir. Register iş arkadaşı bağlamına uygun olmalı; aşırı resmî sunum dili doğal görünmez.","examples":[["Echt? Das ist ja heftig. Wie machen die das denn jeden Tag?","Gerçekten mi? Bu bayağı zor. Her gün bunu nasıl yapıyorlar?","doğal tepki + soru."],["Bei mir ist es etwas anders, weil …","Bende durum biraz farklı, çünkü …","kişisel bağlantı."],["Das könnte funktionieren. Hast du so etwas schon erlebt?","Bu işe yarayabilir. Böyle bir şey yaşadın mı?","etkileşimi sürdürme."]],"activities":[{"id":"smalltalk-function","type":"match","title":"İşlev → ifade","intro":"","prompts":["tepki","kendi deneyimi","karşı görüş","soru ile geri verme"],"options":["Das ist ja interessant.","Bei uns war das ähnlich.","Ich sehe das etwas anders.","Wie ist das bei dir?"],"answers":[0,1,2,3],"why":[]},{"id":"smalltalk-register","type":"mc","title":"Hangisi doğal iş arkadaşı sohbeti?","intro":"","questions":[{"q":"Pendeln konusu açıldı.","o":["Hiermit nehme ich Bezug auf Ihren Arbeitsweg.","120 Kilometer am Tag? Das wäre mir ehrlich gesagt zu viel. Wie siehst du das?","Sehr geehrte Kollegin, …"],"a":1,"why":"Informel, tepkili ve etkileşimli."},{"q":"Konuşmayı sürdürmek için?","o":["Uzun tek taraflı sunum","Karşıdakinin noktasına tepki + soru","Sadece evet/hayır"],"a":1,"why":"Etkileşim değerlendirilir."}]},{"id":"smalltalk-bank","type":"info","title":"Prova konuları","body":"Her konuyu 2–3 dakika doğal sohbet olarak prova et.","items":["uzun işe gidiş/pendeln","toplu taşıma aksaması veya grev","mola alışkanlıkları","çocuk bakımı ve çalışma saatleri","ekipte tatil planlaması","iş sonrası spor/aktivite"]}],"production":{"task":"Konulardan birini seç ve 2–3 dakika iş arkadaşı sohbeti gibi kaydet.","target":"En az 2 tepki ifadesi, 1 kişisel deneyim ve 2 açık soru kullan.","example":"Das ist ja interessant. Bei mir ist der Arbeitsweg zum Glück deutlich kürzer, aber im Winter ist der Verkehr trotzdem oft schwierig. Ich könnte mir vorstellen, dass flexible Anfangszeiten helfen würden. Wie ist das bei dir? Würdest du dafür auch früher anfangen?","mode":"speak","minChars":0,"checklist":[]}},{"id":39,"unit":"DTB C1 · Sprechen","title":"Sprechen Teil 3: işyeri sorununa ortak çözüm ve görev paylaşımı","skills":["Konuşma","Problem çözme","Etkileşim"],"goal":"Yaklaşık 4 dakika içinde Sofortmaßnahmen, langfristige Maßnahmen ve “kim ne yapacak?” görev dağılımını birlikte geliştirmek.","explanation":"Teil 3’te sadece fikir sunmak yetmez. Partnerin önerisine tepki ver, alternatif üret, öncelik belirle ve sonunda görevleri somutlaştır. Model test açıkça kısa vadeli ve uzun vadeli önlemleri ayırır.","examples":[["Zunächst sollten wir …; langfristig wäre es sinnvoll, …","Önce …; uzun vadede … mantıklı olur.","zaman ufku."],["Das klingt sinnvoll. Ich würde allerdings noch ergänzen, dass …","Mantıklı. Ancak şunu da eklerdim …","partner katkısı."],["Ich übernehme die Kundenkommunikation; könntest du die Logistik klären?","Müşteri iletişimini ben üstleneyim; lojistiği sen çözebilir misin?","görev paylaşımı."]],"activities":[{"id":"problem-actions","type":"match","title":"Eylem → tür","intro":"","prompts":["müşteriyi hemen aramak","geçici personel görevlendirmek","kalıcı kontrol süreci kurmak","sorumlulukları yazılı netleştirmek"],"options":["Sofortmaßnahme","langfristige Maßnahme"],"answers":[0,0,1,1],"why":[]},{"id":"problem-dialogue","type":"mc","title":"Etkileşim kalitesi","intro":"","questions":[{"q":"Partner bir öneri yaptı. En iyi cevap?","o":["Benim fikrim daha iyi.","Das klingt sinnvoll. Ergänzend könnten wir …","Hiç tepki vermeden yeni monolog başlat."],"a":1,"why":"Partner katkısını kabul edip geliştirir."},{"q":"Görev sonunda ne netleşmeli?","o":["Sadece genel görüş","Ne yapılacak ve kim üstlenecek","Yeni konu"],"a":1,"why":"Somut görev paylaşımı beklenir."}]},{"id":"problem-bank","type":"info","title":"Problem bankası","body":"Her senaryoda Sofortmaßnahme + langfristige Maßnahme + Zuständigkeit çalış.","items":["önemli müşteriye yanlış ürün gönderildi","yeni çalışan çelişkili talimatlar alıyor","müşteri hizmetlerinde cevap süreleri uzadı","vardiyada ani personel eksikliği","ofiste aşırı sıcaklık/teknik sorun","tekrarlayan veri giriş hataları"]}],"production":{"task":"Problem bankasından bir senaryo seç ve 3–4 dakika çözüm tartışması gibi kaydet.","target":"En az 1 Sofortmaßnahme, 1 langfristige Maßnahme, partner önerisine tepki ve net görev paylaşımı.","example":"Zunächst sollten wir den betroffenen Kunden sofort informieren und eine Ersatzlieferung organisieren. Das klingt für mich sinnvoll; zusätzlich würde ich intern prüfen, an welcher Stelle der Fehler entstanden ist. Ich übernehme die Kundenkommunikation, während du die Logistik klärst. Langfristig sollten wir vor dem Versand eine zweite Kontrolle einführen.","mode":"speak","minChars":0,"checklist":[]}},{"id":40,"unit":"DTB C1 · Sınav stratejisi","title":"Tam sınav stratejisi, puanlama ve son kontrol","skills":["Strateji","Okuma","Dinleme","Yazma","Konuşma"],"goal":"135 dakikalık yazılı ve yaklaşık 16 dakikalık sözlü sınavı zaman, puan ve güçlü/zayıf beceri açısından planlamak.","explanation":"Dört beceri 60’ar puandır. Toplamda en az 144/240 gerekir; ayrıca en az üç beceride 36/60 veya üstü gerekir. Bir beceri telafi edilecekse 24/60’ın altına düşmemelidir. Son hazırlıkta “çok soru çözmek” yerine puan kaynağını tanı: Lesen/Hören 20’şer item, Schreiben karma görevler + kriterler, Sprechen bölüm bazlı Aufgabenbewältigung + üç genel dil kriteri.","examples":[["Lesen: 60 puan = 20 item × 3.","Okuma puanı.","net yapı."],["Hören: 60 puan = 20 item × 3.","Dinleme puanı.","net yapı."],["Schreiben und Sprechen werden zusätzlich kriterlerle bewertet.","Yazma/konuşma kriter bazlı değerlendirilir.","öz değerlendirme."]],"activities":[{"id":"final-format","type":"mc","title":"Format ve geçme","intro":"","questions":[{"q":"Toplam puan?","o":["100","240","300"],"a":1,"why":"4 × 60."},{"q":"Toplam geçme eşiği?","o":["120","144","160"],"a":1,"why":"%60."},{"q":"En az kaç beceri 36/60 veya üstünde olmalı?","o":["2","3","4 zorunlu"],"a":1,"why":"En az üç beceri."},{"q":"Telafi edilebilen bir beceri en az yaklaşık kaç puan olmalı?","o":["24","10","0"],"a":0,"why":"%40 altı telafi edilemez."},{"q":"Sözlü sınavda hazırlık?","o":["20 dk","10 dk","yok"],"a":2,"why":"Hazırlık süresi yok."},{"q":"Hören kayıtları model formatta?","o":["Her zaman iki kez","Bir kez","İstenildiği kadar"],"a":1,"why":"Model testte ilgili konuşmalar/mesajlar bir kez dinlenir."}]},{"id":"final-time","type":"match","title":"Bölüm → süre","intro":"","prompts":["Lesen","Lesen und Schreiben","Hören","Hören und Schreiben","Sprachbausteine und Schreiben","Sprechen"],"options":["45 dk","20 dk","5 dk","≈16–17 dk"],"answers":[0,1,1,2,0,3],"why":[]},{"id":"final-criteria","type":"match","title":"Üretim → değerlendirme odağı","intro":"","prompts":["Schreiben I","Schreiben II","Schreiben III","Schreiben IV","Sprechen II","Sprechen III","Sprechen IV"],"options":["Aufgabenbewältigung","kommunikative Gestaltung","formale Richtigkeit","Spektrum sprachlicher Mittel","Aussprache/Intonation"],"answers":[0,1,2,3,4,2,3],"why":[]}],"production":{"task":"Kendi sınav planını Almanca 6–8 cümlede yaz: hangi beceride risk var, hangi görevi önce güçlendireceksin, zaman stratejin ne olacak?","target":"Planı ölçülebilir yap: örn. “Hören Teil 2’de 4/4 hedefliyorum” veya “Stellungnahme’de 5 dakika planlama ayırıyorum”.","example":"Mein größtes Risiko liegt derzeit im Hörverstehen, besonders bei kurzen Gesprächen mit ähnlichen Antwortoptionen. Deshalb werde ich in den nächsten zwei Wochen täglich ein Einmal-Hören-Training durchführen. Beim Schreiben plane ich vor jeder Stellungnahme etwa fünf Minuten für Gliederung und Argumente ein. Im mündlichen Teil möchte ich besonders Teil 1C trainieren, damit ich Aussagen schnell paraphrasieren kann.","mode":"write","minChars":60,"checklist":[]}}],"grammarSets":[{"id":"passiv","title":"Edilgen yapı (Passiv)","subtitle":"Süreç, durum ve öznesiz edilgen yapı","questions":[{"q":"Die Kommission ___ den Antrag gestern ___.","o":["hat / abgelehnt","ist / abgelehnt worden","wurde / abgelehnt worden","war / ablehnen"],"a":1,"why":"Perfekt Vorgangspassiv: ist + Partizip II + worden."},{"q":"Aktiv: Man diskutiert über die Folgen. Doğru Passiv?","o":["Die Folgen werden diskutiert über.","Über die Folgen wird diskutiert.","Über die Folgen werden diskutiert.","Es diskutiert über die Folgen."],"a":1,"why":"Akkusativ nesnesi olmadığı için öznesiz pasif; fiil tekil."},{"q":"“Die Tür ist geschlossen.” neyi vurgular?","o":["Kapanma sürecini","Ortaya çıkmış durumu","Failin kim olduğunu","Geleceği"],"a":1,"why":"sein + Partizip II = Zustandspassiv."},{"q":"Das Gebäude wurde ___ ein Erdbeben beschädigt.","o":["von","durch","mit","bei"],"a":1,"why":"Nedensel/araçsal etken için “durch + Akk.” uygundur."},{"q":"Welche Form ist korrekt?","o":["Die Daten sind geprüft geworden.","Die Daten sind geprüft worden.","Die Daten haben geprüft worden.","Die Daten wurden geprüft gewesen."],"a":1,"why":"Perfekt Passiv’te “worden” kullanılır."},{"q":"Niemand hat eine Lösung gefunden. →","o":["Keine Lösung ist gefunden.","Es wurde keine Lösung gefunden.","Keine Lösung wurde finden.","Niemand wurde eine Lösung gefunden."],"a":1,"why":"Niemand çoğu zaman pasifte olumsuzlukla ifade edilir."},{"q":"Der Antrag ___ bereits genehmigt; wir warten nur auf die Zustellung.","o":["wird","ist","wurde gerade","würde"],"a":1,"why":"Burada sonuç durumu vurgulanıyor."},{"q":"Man half den Betroffenen sofort. →","o":["Die Betroffenen wurden sofort geholfen.","Den Betroffenen wurde sofort geholfen.","Den Betroffenen wurden sofort geholfen.","Es wurden die Betroffenen geholfen."],"a":1,"why":"helfen Dativ alır; öznesiz pasif tekil “wurde”."}]},{"id":"nvv","title":"İsim-fiil birleşimleri","subtitle":"Nomen-Verb-Verbindungen ve işlevsel fiil yapıları","questions":[{"q":"eine Entscheidung ___","o":["machen","treffen","tun","setzen"],"a":1,"why":"Standart eşdizim: eine Entscheidung treffen."},{"q":"Kritik ___ an der Reform","o":["üben","machen","stellen","geben"],"a":0,"why":"Kritik an etwas üben."},{"q":"etwas in Erwägung ___","o":["bringen","ziehen","nehmen","führen"],"a":1,"why":"in Erwägung ziehen = değerlendirmek."},{"q":"zur Verfügung ___","o":["sein/stehen","machen","ziehen","setzen"],"a":0,"why":"zur Verfügung stehen / stellen."},{"q":"in Kraft ___","o":["kommen","treten","gehen","laufen"],"a":1,"why":"in Kraft treten = yürürlüğe girmek."},{"q":"Maßnahmen ___","o":["ergreifen","nehmen","leisten","stellen"],"a":0,"why":"Maßnahmen ergreifen = önlem almak."},{"q":"eine Frage zur Sprache ___","o":["bringen","ziehen","treffen","halten"],"a":0,"why":"zur Sprache bringen = gündeme getirmek."},{"q":"einen Beitrag zu etwas ___","o":["leisten","machen","setzen","führen"],"a":0,"why":"einen Beitrag leisten."}]},{"id":"modal_obj","title":"Kip fiilleri – nesnel kullanım","subtitle":"Modalverben: zorunluluk, izin, olasılık ve niyet","questions":[{"q":"Du ___ hier nicht parken. Es ist verboten.","o":["musst","darfst","kannst","sollst"],"a":1,"why":"nicht dürfen = yasak."},{"q":"Wir ___ die Frist nicht einhalten; es war unmöglich.","o":["durften","konnten","sollten","wollten"],"a":1,"why":"nicht können = olanaksız/yetersiz olmak."},{"q":"Es ist nicht notwendig, dass du kommst. → Du ___ kommen.","o":["darfst nicht","musst nicht","sollst nicht","willst nicht"],"a":1,"why":"nicht müssen = zorunda olmamak."},{"q":"Perfekt: Wir ___ früher abreisen ___.","o":["haben / müssen","sind / gemusst","haben / gemusst","wurden / müssen"],"a":0,"why":"Ersatzinfinitiv: haben + Infinitiv + Modalinfinitiv."},{"q":"Man erwartet von uns, dass wir den Bericht überarbeiten. → Wir ___ den Bericht überarbeiten.","o":["sollen","dürfen","mögen","können"],"a":0,"why":"sollen görev/beklenti aktarır."},{"q":"Er weigert sich zu unterschreiben. → Er ___ nicht unterschreiben.","o":["will","darf","kann","muss"],"a":0,"why":"nicht wollen = isteksizlik/ret."},{"q":"Die Genehmigung erlaubt uns die Nutzung. → Wir ___ das Gebäude nutzen.","o":["dürfen","müssen","sollen","wollen"],"a":0,"why":"dürfen = izin."},{"q":"Sie ist fähig, komplexe Daten zu analysieren. → Sie ___ komplexe Daten analysieren.","o":["soll","kann","darf","muss"],"a":1,"why":"können = yetenek."}]},{"id":"modal_subj","title":"Kip fiilleri – öznel kullanım","subtitle":"Modalverben: tahmin, çıkarım, söylenti ve mesafe","questions":[{"q":"Er ___ schon angekommen sein; sein Auto steht draußen. (çok güçlü çıkarım)","o":["könnte","muss","soll","will"],"a":1,"why":"subjektives müssen = güçlü çıkarım."},{"q":"Die Preise ___ nächstes Jahr leicht sinken. (olasılık)","o":["könnten","müssen","wollen","sollen"],"a":0,"why":"könnte = belirsiz olasılık."},{"q":"Die Ministerin ___ bereits informiert gewesen sein. (duyuma göre)","o":["muss","soll","will","darf"],"a":1,"why":"sollen = ikinci el/doğrulanmamış bilgi."},{"q":"Der Zeuge ___ alles gesehen haben. (kendisi iddia ediyor, konuşan mesafeli)","o":["will","muss","darf","soll"],"a":0,"why":"wollen subjektiv = kişinin kendi iddiası, konuşan şüpheci olabilir."},{"q":"Die Ursache ___ in der neuen Software liegen. (muhtemelen)","o":["dürfte","soll","will","muss immer"],"a":0,"why":"dürfte = yüksek olasılık/varsayım."},{"q":"Das ___ kein Zufall sein. (güçlü olumsuz çıkarım)","o":["kann","muss","soll","darf"],"a":0,"why":"“Das kann kein … sein” = kesinlikle olamaz."},{"q":"Vergangenheit: Vielleicht hat er den Termin vergessen. → Er ___ den Termin vergessen haben.","o":["könnte","soll","will","muss"],"a":0,"why":"könnte + Infinitiv Perfekt."},{"q":"Rat: Du ___ deine Argumente klarer strukturieren.","o":["solltest","willst","darfst","kannst nur"],"a":0,"why":"Konjunktiv II von sollen = tavsiye."}]},{"id":"k2","title":"Dilek/varsayım kipi (Konjunktiv II)","subtitle":"Konjunktiv II ile gerçek dışılık, ihtiyat ve tavsiye","questions":[{"q":"___ mehr Daten vorhanden, ließe sich die Hypothese besser prüfen.","o":["Wären","Sind","Seien","Wurden"],"a":0,"why":"İrreal koşul: Wären …, ließe …"},{"q":"Geçmiş pişmanlık: Wir ___ früher reagieren ___.","o":["hätten / sollen","würden / sollen","seien / sollen","haben / sollen"],"a":0,"why":"hätten + Infinitiv + sollen."},{"q":"Temkinli öneri hangisidir?","o":["Das ist so.","Es wäre denkbar, dass …","Das muss so sein.","Mach das!"],"a":1,"why":"Konjunktiv II iddiayı yumuşatır."},{"q":"Wenn ich mehr Zeit ___, ___ ich den Bericht überarbeiten.","o":["hätte / würde","habe / werde","sei / würde","hatte / würde"],"a":0,"why":"İrreal şart."},{"q":"Es ___ sinnvoll, die Stichprobe zu vergrößern.","o":["wäre","sei","wird","war immer"],"a":0,"why":"Temkinli değerlendirme."},{"q":"Er tut so, als ___ er alles.","o":["wüsste","weiß","wisse","wusste immer"],"a":0,"why":"als ob/als + Konjunktiv II irreal karşılaştırma."},{"q":"Das ___ ich an deiner Stelle vermeiden.","o":["würde","werde","sei","habe"],"a":0,"why":"Tavsiye için Konjunktiv II."},{"q":"Hätten wir die Warnung ernst genommen, ___ es nicht so weit gekommen.","o":["wäre","ist","sei","würde jetzt"],"a":0,"why":"Geçmiş irreal koşul: wäre … gekommen."}]},{"id":"k1","title":"Dolaylı anlatım kipi (Konjunktiv I)","subtitle":"Konjunktiv I ile dolaylı anlatım ve kaynak mesafesi","questions":[{"q":"Die Autorin sagt, die Daten ___ eindeutig.","o":["seien","sind","wären nur","werden gewesen"],"a":0,"why":"Konjunktiv I plural: seien."},{"q":"Er erklärt, er ___ keine Kenntnis davon.","o":["habe","hat","hätte immer","haben"],"a":0,"why":"Konjunktiv I: habe."},{"q":"Der Sprecher behauptet, die Maßnahme ___ Wirkung.","o":["zeige","zeigt","zeigte zwingend","würde gezeigt"],"a":0,"why":"Konjunktiv I: zeige."},{"q":"Indikativ ve Konjunktiv I çakışırsa sık kullanılan çözüm?","o":["Konjunktiv II","Imperativ","Passiv zorunlu","Futur II"],"a":0,"why":"Mesafeyi görünür kılmak için Ersatzkonjunktiv II."},{"q":"Sie sagten, sie ___ nichts bemerkt.","o":["hätten","haben","seien bemerken","würden bemerkt"],"a":0,"why":"Plural biçimde Konjunktiv I “haben” ile çakıştığı için “hätten”."},{"q":"Konjunktiv I’in temel amacı?","o":["Kaynağı mesafeli aktarmak","Geleceği kesinleştirmek","Emir vermek","Soru sormak"],"a":0,"why":"Özellikle haber/rapor dilinde aktarım işlevi."},{"q":"Die Expertin betont, man ___ die Daten vorsichtig interpretieren.","o":["müsse","muss","musste","würde müssen gewesen"],"a":0,"why":"Konjunktiv I von müssen: müsse."},{"q":"Er meint, das Ergebnis ___ überraschend.","o":["sei","ist","wäre nur vielleicht","war"],"a":0,"why":"Konjunktiv I von sein: sei."}]},{"id":"nom","title":"Adlaştırma / fiilleştirme","subtitle":"Nominalisierung / Verbalisierung: yoğun akademik yapı ↔ açık fiil cümlesi","questions":[{"q":"“wegen der steigenden Kosten” →","o":["weil die Kosten steigen","obwohl die Kosten steigen","damit die Kosten steigen","wenn die Kosten nicht steigen"],"a":0,"why":"wegen = neden."},{"q":"“trotz der Kritik” →","o":["obwohl es Kritik gibt","weil es Kritik gibt","damit es Kritik gibt","bevor es Kritik gibt"],"a":0,"why":"trotz = taviz, obwohl."},{"q":"“nach Abschluss der Studie” →","o":["nachdem die Studie abgeschlossen worden war","weil die Studie beginnt","bevor man die Studie abschließt","falls die Studie endet"],"a":0,"why":"nach = zaman ilişkisi, nachdem."},{"q":"“zur Verbesserung der Qualität” →","o":["damit die Qualität verbessert wird","weil die Qualität schlecht ist","obwohl die Qualität steigt","nachdem die Qualität sank"],"a":0,"why":"zur + nominal amaç = damit/um … zu."},{"q":"“bei einer weiteren Verschärfung” →","o":["wenn sich die Lage weiter verschärft","obwohl die Lage besser wird","weil niemand reagiert","nachdem alles vorbei ist"],"a":0,"why":"bei + durum çoğu kez wenn/falls."},{"q":"“aufgrund fehlender Daten” →","o":["weil Daten fehlen","obwohl Daten fehlen","damit Daten fehlen","bevor Daten fehlen"],"a":0,"why":"aufgrund = neden."},{"q":"“während der Auswertung” →","o":["während die Daten ausgewertet werden","weil die Daten fehlen","nachdem alles fertig ist","damit man beginnt"],"a":0,"why":"Eş zamanlılık."},{"q":"Nominal yapı ne zaman özellikle uygundur?","o":["Bilgiyi yoğun ve resmî biçimde paketlemek gerektiğinde","Her konuşma cümlesinde","Sadece A1 düzeyinde","Sadece sorularda"],"a":0,"why":"Akademik/resmî registerda yoğunluk sağlar."}]},{"id":"cohesion","title":"Bağlaşıklık ve bağlaçlar","subtitle":"C1 düzeyinde metin ilişkileri","questions":[{"q":"Taviz: ___ die Stichprobe klein ist, sind die Ergebnisse relevant.","o":["Wenngleich","Folglich","Dadurch","Zumal"],"a":0,"why":"Wenngleich = her ne kadar."},{"q":"Sonuç: Die Nachfrage sank. ___ wurde das Angebot reduziert.","o":["Folglich","Wenngleich","Indem","Während"],"a":0,"why":"Folglich = bunun sonucunda."},{"q":"Karşılaştırmalı karşıtlık: Gruppe A profitiert. ___ entstehen Gruppe B Nachteile.","o":["Demgegenüber","Infolgedessen","Daher","Somit"],"a":0,"why":"Demgegenüber iki grubu karşı karşıya getirir."},{"q":"Koşul: Die Regel gilt, ___ keine Ausnahme genehmigt wird.","o":["sofern","obwohl","zumal","wodurch"],"a":0,"why":"sofern = şu koşulla ki/eğer."},{"q":"Ek gerekçe: Die Maßnahme ist teuer, ___ ihr Nutzen unklar ist.","o":["zumal","folglich","hingegen","indem"],"a":0,"why":"zumal ek/kuvvetlendirici gerekçe verir."},{"q":"Araç/yöntem: Man senkt Kosten, ___ man Prozesse automatisiert.","o":["indem","obwohl","sofern","während dagegen"],"a":0,"why":"indem = nasıl/yöntem."},{"q":"Gönderim: Es wurden zwei Modelle getestet. ___ erwies sich als robuster.","o":["Letzteres","Folglich","Wenngleich","Daher dass"],"a":0,"why":"Letzteres ikinci modele gider."},{"q":"“Nichtsdestotrotz” hangi ilişkiyi verir?","o":["Taviz/karşıtlık","Amaç","Zaman","Koşul"],"a":0,"why":"Beklenen sonuca rağmen karşıt durum."}]}],"styleSets":[{"id":"register","title":"Kayıt ve üslup","questions":[{"q":"Yarı resmî e-posta için en uygun ifade?","o":["Das ist echt Mist.","Ich möchte Sie auf eine Unstimmigkeit aufmerksam machen.","Ey, könnt ihr das fixen?","Mega nervig."],"a":1,"why":"Nazik, açık ve profesyonel kayıt."},{"q":"Akademik temkinli ifade?","o":["Das beweist hundertprozentig …","Die Befunde legen nahe, dass …","Jeder weiß, dass …","Ganz klar …"],"a":1,"why":"“legen nahe” kanıt derecesini uygun tutar."},{"q":"Tartışmada kibar itiraz?","o":["Unsinn.","Ich sehe den Punkt, allerdings …","Falsch!","Quatsch."],"a":1,"why":"Partneradäquat ve etkileşimli."},{"q":"Resmî öneri?","o":["Mach doch einfach …","Als mögliche Lösung schlage ich vor, …","Du musst halt …","Easy: …"],"a":1,"why":"Uygun register."},{"q":"Nötr görüş belirtme?","o":["Meines Erachtens …","Ich schwöre …","Voll krass …","Safe …"],"a":0,"why":"Nötr/resmî argümantasyon."},{"q":"Resmî talep?","o":["Wäre es möglich, …?","Gib mir …","Los, mach …","Kannste …?"],"a":0,"why":"Nazik ve uygun."},{"q":"Akademik sınırlama?","o":["Dies gilt allerdings nur unter der Voraussetzung, dass …","Das gilt immer.","Keine Ahnung, aber …","Ist halt so."],"a":0,"why":"Koşulu açıklar."},{"q":"Sunum geçişi?","o":["Jetzt mal egal.","Damit komme ich zum zweiten Aspekt.","Whatever.","Und so."],"a":1,"why":"Dinleyiciye yapı sinyali verir."}]},{"id":"paraphrase","title":"Parafraz","questions":[{"q":"“berücksichtigen” ≈","o":["in Betracht ziehen","verwerfen","bestreiten","verschweigen"],"a":0,"why":"İkisi de değerlendirmeye katmak."},{"q":"“auf etwas zurückzuführen sein” ≈","o":["durch etwas bedingt sein","etwas verhindern","etwas verbergen","etwas beschleunigen"],"a":0,"why":"Nedeni belirtir."},{"q":"“von großer Bedeutung” ≈","o":["maßgeblich","belanglos","zufällig","überflüssig"],"a":0,"why":"maßgeblich = önemli/belirleyici."},{"q":"“etwas außer Acht lassen” ≈","o":["etwas ignorieren","etwas fördern","etwas belegen","etwas erweitern"],"a":0,"why":"Göz ardı etmek."},{"q":"“einen Einwand erheben” ≈","o":["widersprechen","zustimmen","abschließen","zusammenfassen"],"a":0,"why":"İtiraz etmek."},{"q":"“sich als tragfähig erweisen” ≈","o":["funktionieren / belastbar sein","scheitern","verboten sein","unverständlich sein"],"a":0,"why":"Uygulanabilir/sağlam çıkmak."},{"q":"“die These untermauern” ≈","o":["die These stützen","die These vergessen","die These vermeiden","die These abschwächen"],"a":0,"why":"Kanıt/argümanla desteklemek."},{"q":"“eine Entwicklung zeichnet sich ab” ≈","o":["eine Entwicklung wird erkennbar","alles bleibt gleich","etwas wird verboten","etwas endet sofort"],"a":0,"why":"Bir eğilim görünür hale gelir."}]},{"id":"collocations","title":"C1 eşdizimler","questions":[{"q":"eine Schlussfolgerung ___","o":["ziehen","machen","bauen","stellen"],"a":0,"why":"eine Schlussfolgerung ziehen."},{"q":"eine Maßnahme ___","o":["ergreifen","schreiben","legen","laufen"],"a":0,"why":"Maßnahmen ergreifen."},{"q":"zur Debatte ___","o":["stehen","laufen","ziehen","fallen immer"],"a":0,"why":"zur Debatte stehen."},{"q":"einen Zusammenhang ___","o":["herstellen","kochen","setzen","laufen"],"a":0,"why":"einen Zusammenhang herstellen."},{"q":"eine Annahme ___","o":["in Frage stellen","ins Haus bringen","zu Fuß setzen","in Kraft machen"],"a":0,"why":"eine Annahme in Frage stellen."},{"q":"Verantwortung ___","o":["übernehmen","nehmen auf","machen","bauen"],"a":0,"why":"Verantwortung übernehmen."},{"q":"einen Antrag ___","o":["stellen","setzen","machen immer","ziehen"],"a":0,"why":"einen Antrag stellen."},{"q":"unter Druck ___","o":["geraten","kommen zu","ziehen","leisten"],"a":0,"why":"unter Druck geraten/stehen."}]},{"id":"nuance","title":"Nüans ve kanıt derecesi","questions":[{"q":"“legt nahe” hangi güçte?","o":["işaret ediyor / olası sonuç","kesin kanıtlıyor","reddediyor","yasaklıyor"],"a":0,"why":"Temkinli sonuç."},{"q":"“dürfte” (öznel) çoğu zaman?","o":["muhtemelen","kesinlikle","yasaktır","geçmiş emir"],"a":0,"why":"Yüksek olasılık/varsayım."},{"q":"“keineswegs” ne yapar?","o":["güçlü olumsuzlama","örnek verir","sonuç çıkarır","zaman gösterir"],"a":0,"why":"Kesinlikle değil."},{"q":"“durchaus” hangi nüansı taşıyabilir?","o":["beklenenden daha olumlu/onaylayıcı vurgu","tam ret","zaman","sayısal kesinlik"],"a":0,"why":"“gayet / durchaus” olumlu vurgu yapabilir."},{"q":"“nur bedingt” ne demektir?","o":["yalnızca sınırlı ölçüde","tamamen","kesinlikle","hiçbir koşulda"],"a":0,"why":"Koşullu/sınırlı geçerlilik."},{"q":"“weitgehend” ≈","o":["büyük ölçüde","hiç","tam olarak her zaman","rastgele"],"a":0,"why":"Tam değil ama büyük ölçüde."},{"q":"“kaum” ne ifade eder?","o":["çok az / neredeyse hiç","çok fazla","kesin","gereklilik"],"a":0,"why":"Düşük derece."},{"q":"“angeblich” ne sinyali verir?","o":["iddia edilen, doğrulanmamış bilgi","kesin kanıt","emir","izin"],"a":0,"why":"Kaynağa mesafe."}]}],"readingPractice":{"part1":{"title":"Bölüm 1 · Sözcük boşlukları","text":"Viele Städte testen sogenannte Superblocks. Dabei werden mehrere Straßen zu größeren Wohnbereichen zusammengefasst, in denen der Durchgangsverkehr stark begrenzt wird. Die Idee zielt ___(1)___, öffentlichen Raum neu zu verteilen. Flächen, die zuvor fast ausschließlich Autos ___(2)___, können für Bäume, Sitzplätze oder Spielbereiche genutzt werden. Kritiker weisen jedoch ___(3)___, dass Verkehr nicht einfach verschwindet, sondern sich verlagern kann. Deshalb kommt es ___(4)___ eine sorgfältige Planung an. Erste Auswertungen zeigen, dass die Akzeptanz steigt, wenn Anwohner frühzeitig ___(5)___ die Gestaltung einbezogen werden. Entscheidend ist außerdem, die Auswirkungen nicht nur kurzfristig, ___(6)___ über mehrere Jahre zu beobachten. So lässt sich prüfen, ob die Maßnahmen tatsächlich ___(7)___ einer besseren Luftqualität beitragen und ob benachbarte Straßen unverhältnismäßig ___(8)___ werden.","items":[{"o":["darauf ab","davon aus","dazu bei","damit ein"],"a":0},{"o":["zur Verfügung standen","in Anspruch nahmen","zugrunde lagen","in Kraft traten"],"a":1},{"o":["darauf hin","darüber aus","dazu bei","davon ab"],"a":0},{"o":["auf","an","um","für"],"a":1},{"o":["an","in","bei","zu"],"a":1},{"o":["aber auch","sondern","obwohl","währenddessen"],"a":1},{"o":["zu","bei","mit","an"],"a":0},{"o":["belastet","überzeugt","verfasst","erfasst"],"a":0}]},"part2":{"title":"Bölüm 2 · Yoğun bilgi içeren makale","text":"Immer mehr Unternehmen erproben eine Vier-Tage-Woche, doch hinter dem Begriff verbergen sich unterschiedliche Modelle. Manche reduzieren die Wochenarbeitszeit bei gleichem Lohn, andere verteilen die bisherige Arbeitszeit lediglich auf vier längere Tage. Für die Bewertung ist diese Unterscheidung entscheidend. Studien zu Pilotprojekten berichten häufig von höherer Zufriedenheit und weniger Fehltagen. Gleichzeitig warnen Forschende davor, aus kleinen, freiwillig teilnehmenden Stichproben allgemeine Schlüsse zu ziehen. Unternehmen, die sich für Pilotprojekte melden, sind oft bereits offen für flexible Arbeitsformen und verfügen über günstige organisatorische Voraussetzungen.\n\nEin zentrales Ergebnis vieler Versuche ist, dass die Produktivität nicht automatisch sinkt, wenn Arbeitszeit reduziert wird. Teams streichen etwa wenig wirksame Besprechungen, bündeln Kommunikationszeiten und automatisieren Routinen. Diese Verdichtung kann jedoch problematisch werden, wenn die gleiche Arbeitsmenge lediglich in weniger Zeit erledigt werden soll. Beschäftigte berichten dann zwar von einem zusätzlichen freien Tag, aber auch von stärkerem Zeitdruck an den übrigen Tagen. Besonders in Bereichen mit Schichtbetrieb oder direktem Kundenkontakt ist die Umsetzung kompliziert, weil Öffnungszeiten und Besetzung weiterhin gewährleistet werden müssen.\n\nAuch die langfristige Wirkung ist noch nicht abschließend geklärt. Während die Motivation zu Beginn eines Pilotprojekts häufig deutlich steigt, kann ein Teil dieses Effekts auf den Neuigkeitswert zurückzuführen sein. Daher fordern Arbeitsforscher längere Beobachtungszeiträume. Sie betonen zudem, dass die Vier-Tage-Woche kein einzelnes Instrument ist, das unabhängig von Führung, Personaldecke und Arbeitsorganisation funktioniert. Ein erfolgreiches Modell müsse an Branche und Tätigkeit angepasst werden.\n\nFür Beschäftigte ist nicht nur die Zahl der Arbeitstage relevant. Planbarkeit, Autonomie und die Möglichkeit, konzentriert zu arbeiten, spielen ebenfalls eine große Rolle. Einige Untersuchungen zeigen sogar, dass Beschäftigte eine geringere Wochenarbeitszeit mit etwas weniger Einkommen akzeptieren würden, wenn sie dafür verlässlich über ihre Zeit verfügen könnten. Das spricht dafür, Arbeitszeitpolitik nicht auf eine einzige Kennzahl zu reduzieren.\n\nIn der öffentlichen Debatte wird die Vier-Tage-Woche häufig entweder als Zukunftsmodell oder als unrealistische Wohlfühlidee dargestellt. Die Forschung zeichnet ein differenzierteres Bild: Unter passenden Bedingungen kann sie Vorteile bringen, doch sie löst weder Personalmangel noch schlechte Prozesse von selbst. Entscheidend ist somit weniger die Zahl Vier als die Frage, wie Arbeit organisiert wird.","items":[{"q":"Warum ist der Begriff Vier-Tage-Woche laut Text nicht eindeutig?","o":["Weil nur öffentliche Betriebe ihn nutzen.","Weil unterschiedliche Modelle dahinterstehen.","Weil die Wochenarbeitszeit immer gleich bleibt."],"a":1},{"q":"Warum mahnen Forschende bei Pilotstudien zur Vorsicht?","o":["Teilnehmende Unternehmen können nicht repräsentativ sein.","Die Produktivität wird nie gemessen.","Die Projekte dauern immer zu lange."],"a":0},{"q":"Wie kann Produktivität trotz weniger Arbeitszeit stabil bleiben?","o":["Durch längere Pausen.","Durch effizientere Abläufe und weniger unwirksame Tätigkeiten.","Durch zusätzliche unbezahlte Arbeit."],"a":1},{"q":"Welches Risiko nennt der Text bei Arbeitsverdichtung?","o":["Mehr Zeitdruck an den Arbeitstagen.","Zu viele freie Mitarbeiter.","Sinkende Öffnungszeiten in allen Branchen."],"a":0},{"q":"Warum sind längere Studien nötig?","o":["Um einen möglichen Neuigkeitseffekt von dauerhaften Wirkungen zu trennen.","Weil bisher keine Daten existieren.","Weil nur Gehälter untersucht wurden."],"a":0},{"q":"Was ist Beschäftigten laut Text ebenfalls wichtig?","o":["Nur die Zahl der Urlaubstage.","Planbarkeit und Autonomie.","Einheitliche Arbeitszeiten für alle Branchen."],"a":1},{"q":"Welche Schlussfolgerung zieht der Text?","o":["Vier Tage sind grundsätzlich optimal.","Die konkrete Arbeitsorganisation ist wichtiger als die reine Zahl der Tage.","Das Modell ist nur im Schichtbetrieb sinnvoll."],"a":1}]},"part3":{"title":"Bölüm 3 · Cümleleri yeniden yerleştirme","segments":["Digitale Lernplattformen versprechen, Unterricht stärker zu individualisieren. "," Lehrkräfte erhalten dadurch detaillierte Informationen über Lernfortschritte. "," Gerade hier beginnt jedoch die Debatte über Datenschutz. "," Solche Daten können pädagogisch hilfreich sein, zugleich lassen sich daraus umfassende Profile ableiten. "," Hinzu kommt, dass algorithmische Empfehlungen nicht neutral sind. "," Werden bestimmte Aufgabentypen häufiger vorgeschlagen, kann dies langfristig beeinflussen, welche Kompetenzen Lernende entwickeln. "," Deshalb fordern Fachleute transparente Kriterien und die Möglichkeit, automatisierte Empfehlungen zu übersteuern. "," Entscheidend ist am Ende, dass Technik pädagogische Entscheidungen unterstützt, nicht ersetzt. "," Nur dann kann Personalisierung einen echten Mehrwert bieten."],"candidates":["A: Systeme können Aufgaben automatisch an das bisherige Leistungsniveau anpassen.","B: Dafür müssen allerdings große Mengen an Nutzungsdaten verarbeitet werden.","C: Aus diesem Grund sollten Schulen sämtliche digitalen Angebote vermeiden.","D: Denn Modelle spiegeln immer auch die Daten und Annahmen wider, auf denen sie beruhen.","E: Eine technische Empfehlung kann also unbemerkt zu einer pädagogischen Vorgabe werden.","F: Gleichzeitig bleibt die professionelle Beurteilung durch Lehrkräfte unverzichtbar.","G: Viele Schulen ersetzen deshalb alle Lehrbücher durch Tablets.","H: Besonders wichtig ist, dass Betroffene nachvollziehen können, wie eine Empfehlung entsteht.","I: Diese Forderung betrifft sowohl Anbieter als auch Bildungseinrichtungen.","J: Personalisierung wird damit zu einer Frage der Kontrolle und Verantwortlichkeit."],"answers":[0,1,9,3,4,7,8,5]},"part4":{"title":"Bölüm 4 · Görüşleri eşleştirme","texts":[{"name":"A · Prof. Berger","text":"Generative KI kann Studierenden beim Strukturieren helfen. Problematisch wird es, wenn der Denkprozess ausgelagert wird. Ich würde die Werkzeuge daher nicht verbieten, sondern Aufgaben so gestalten, dass Zwischenschritte und Quellen transparent gemacht werden müssen."},{"name":"B · Dr. Kaya","text":"Für mich steht Chancengleichheit im Vordergrund. Wenn leistungsfähige Systeme kostenpflichtig sind, dürfen Prüfungen nicht voraussetzen, dass alle Studierenden Zugang haben. Institutionen müssten entweder gleichwertige Zugänge bereitstellen oder die Nutzung begrenzen."},{"name":"C · Lena Hoffmann","text":"Ich nutze KI vor allem, um Gegenargumente zu finden. Das zwingt mich, meine Position zu schärfen. Texte lasse ich aber nicht vollständig erzeugen, weil ich sonst kaum merke, ob ich den Stoff wirklich verstanden habe."},{"name":"D · Markus Voss","text":"Die Debatte konzentriert sich zu stark auf Betrug. Interessanter ist, welche Kompetenzen künftig relevant sind. Wer KI-Ergebnisse prüfen, korrigieren und sinnvoll einordnen kann, besitzt eine neue Form von Fachkompetenz. Hochschulen sollten das systematisch lehren."}],"items":[{"q":"Wer sieht Transparenz über den Arbeitsprozess als zentral an?","a":0},{"q":"Wer betont ungleichen Zugang zu Technik?","a":1},{"q":"Wer nutzt KI gezielt zur Prüfung der eigenen Argumente?","a":2},{"q":"Wer fordert, KI-Kompetenz ausdrücklich zu unterrichten?","a":3},{"q":"Wer lehnt ein generelles Verbot ab?","a":0},{"q":"Wer verbindet die Frage mit Fairness in Prüfungen?","a":1},{"q":"Wer nennt eigenes Verständnis als Grenze der Nutzung?","a":2}]}},"listeningPractice":{"part1":{"title":"Bölüm 1 · Podcast eşleştirme","plays":1,"script":"Willkommen zu „Ideen im Alltag“. Heute stelle ich drei neue Sachbücher vor. Das erste Buch, „Leise Städte“, untersucht, wie Lärm unsere Gesundheit beeinflusst. Besonders stark ist der historische Vergleich: Die Autorin zeigt, wie sich Geräuschquellen seit der Industrialisierung verändert haben und warum absolute Stille in einer Stadt weder realistisch noch unbedingt wünschenswert ist. Das zweite Buch, „Reparieren statt ersetzen“, beschäftigt sich mit Produktdesign. Der Autor besucht Werkstätten, Start-ups und kommunale Reparaturzentren. Er argumentiert, dass langlebige Produkte nicht nur eine technische, sondern auch eine politische Frage sind. Das dritte Buch heißt „Die Kunst des Wartens“. Eine Psychologin verbindet Forschung zu Aufmerksamkeit mit persönlichen Beobachtungen. Sie erklärt, warum Wartezeiten heute als besonders belastend erlebt werden und wie kleine Unterbrechungen sogar kreative Prozesse fördern können.","labels":["A · Leise Städte","B · Reparieren statt ersetzen","C · Die Kunst des Wartens"],"items":[{"q":"Historische Entwicklungen spielen eine wichtige Rolle.","a":0},{"q":"Politische Rahmenbedingungen werden thematisiert.","a":1},{"q":"Persönliche Erfahrungen werden mit Forschung verbunden.","a":2},{"q":"Es geht um die Lebensdauer von Gegenständen.","a":1},{"q":"Ein vermeintlich negativer Zustand kann Vorteile haben.","a":2},{"q":"Völlige Abwesenheit des Problems wird nicht als Ziel dargestellt.","a":0}]},"part2":{"title":"Bölüm 2 · Uzman röportajı","plays":2,"script":"Moderatorin: Herr Neumann, viele Menschen glauben, Multitasking spare Zeit. Stimmt das? Experte: Bei einfachen, automatisierten Tätigkeiten können mehrere Prozesse parallel laufen. Bei anspruchsvollen Denkaufgaben wechseln wir jedoch meist schnell zwischen Aufgaben. Dieser Wechsel kostet Zeit und erhöht die Fehlerquote. Moderatorin: Ist das bei jungen Menschen anders? Experte: Sie sind oft an häufige Unterbrechungen gewöhnt, aber Gewöhnung bedeutet nicht automatisch bessere Leistung. In unseren Studien sehen wir eher, dass Personen ihre eigene Effizienz überschätzen. Moderatorin: Hilft es, Benachrichtigungen auszuschalten? Experte: Ja, allerdings reicht das allein nicht. Wer ständig erwartet, dass eine Nachricht kommen könnte, bleibt innerlich aufmerksam für mögliche Unterbrechungen. Sinnvoll sind deshalb klar definierte Phasen, in denen Kommunikationskanäle geschlossen werden. Moderatorin: Manche Unternehmen führen Fokuszeiten ein. Experte: Das kann funktionieren, wenn die Organisation es ernst meint. Es bringt wenig, zwei Stunden als Fokuszeit zu deklarieren und gleichzeitig schnelle Antworten zu erwarten. Moderatorin: Gibt es Tätigkeiten, bei denen Unterbrechungen sogar nützlich sind? Experte: Bei kreativen Problemen kann eine Pause helfen. Das ist aber etwas anderes als eine zufällige Nachricht. Eine bewusst gewählte Unterbrechung kann Distanz schaffen; unvorhersehbare Unterbrechungen fragmentieren eher die Aufmerksamkeit.","items":[{"q":"Bei komplexen Aufgaben erledigt das Gehirn mehrere Denkprozesse gleichzeitig.","a":1},{"q":"Häufiger Aufgabenwechsel kann die Fehlerquote erhöhen.","a":0},{"q":"Jüngere Menschen sind nachweislich effizienter im Multitasking.","a":1},{"q":"Menschen überschätzen laut Experte teilweise ihre Multitasking-Leistung.","a":0},{"q":"Ausgeschaltete Benachrichtigungen lösen das Problem vollständig.","a":1},{"q":"Fokuszeiten funktionieren nur, wenn Erwartungen im Unternehmen dazu passen.","a":0},{"q":"Der Experte empfiehlt Fokuszeiten von genau zwei Stunden.","a":2},{"q":"Bewusste Pausen können bei kreativen Problemen hilfreich sein.","a":0},{"q":"Jede Form von Unterbrechung wirkt gleich auf Aufmerksamkeit.","a":1}],"labels":["stimmt","stimmt nicht","dazu wird nichts gesagt"]},"part3":{"title":"Bölüm 3 · Tartışma","plays":1,"segments":[{"script":"Moderator: Sollten Innenstädte komplett autofrei werden? Stadtplanerin: Ein vollständiges Verbot klingt einfach, ignoriert aber Lieferverkehr und Menschen mit eingeschränkter Mobilität. Ich plädiere für deutlich weniger privaten Autoverkehr, aber mit klar definierten Ausnahmen. Händler: Mein Hauptproblem ist nicht die Reduktion an sich, sondern die Planbarkeit. Wenn Regeln ständig wechseln, können Betriebe Logistik kaum organisieren.","items":[{"q":"Was fordert die Stadtplanerin?","o":["Ein ausnahmsloses Verbot","Weniger privaten Autoverkehr mit Ausnahmen","Mehr Parkplätze"],"a":1},{"q":"Was kritisiert der Händler vor allem?","o":["Unklare und wechselnde Regeln","Zu viele Fahrräder","Zu wenig Lieferverkehr"],"a":0}]},{"script":"Moderator: Häufig heißt es, weniger Autos machten Zentren automatisch attraktiver. Händler: Das kann stimmen, wenn gleichzeitig gute Erreichbarkeit geschaffen wird. Wer nur Parkplätze entfernt, ohne ÖPNV und Lieferzonen zu verbessern, verlagert Probleme. Stadtplanerin: Genau deshalb müssen Maßnahmen als Paket geplant werden. Aufenthaltsqualität entsteht nicht durch Verbote allein.","items":[{"q":"Wovon hängt Attraktivität laut Händler ab?","o":["Nur von weniger Parkplätzen","Von alternativer Erreichbarkeit und Logistik","Von höheren Mieten"],"a":1},{"q":"Worin sind sich beide einig?","o":["Einzelmaßnahmen reichen nicht","Autos müssen unverändert bleiben","ÖPNV spielt keine Rolle"],"a":0}]},{"script":"Moderator: Wie reagieren Bewohner? Stadtplanerin: Am Anfang gibt es oft Widerstand, weil Menschen Verluste stärker wahrnehmen als mögliche Gewinne. Nach Umbauten steigt die Zustimmung häufig, wenn der öffentliche Raum tatsächlich besser nutzbar wird. Händler: Erfahrungen aus anderen Städten sind hilfreich, aber sie lassen sich nicht eins zu eins übertragen.","items":[{"q":"Wie erklärt die Stadtplanerin anfänglichen Widerstand?","o":["Menschen gewichten Verluste stark","Alle sind gegen Veränderungen","Es fehlen Daten"],"a":0},{"q":"Was sagt der Händler zu anderen Städten?","o":["Erfahrungen sind wertlos","Modelle müssen an lokale Bedingungen angepasst werden","Man soll alles kopieren"],"a":1}]},{"script":"Moderator: Was wäre ein vernünftiger nächster Schritt? Händler: Pilotzonen mit klaren Messkriterien. Dann kann man sehen, wie sich Umsätze, Lieferzeiten und Besucherzahlen entwickeln. Stadtplanerin: Dem stimme ich zu. Zusätzlich würde ich Luftqualität und Aufenthaltsdauer messen. Entscheidungen sollten danach auf mehreren Kriterien beruhen, nicht nur auf Verkehrszahlen.","items":[{"q":"Was schlägt der Händler vor?","o":["Sofortiges dauerhaftes Verbot","Pilotzonen mit Messkriterien","Keine Veränderung"],"a":1},{"q":"Was ergänzt die Stadtplanerin?","o":["Weitere Qualitätsindikatoren","Nur Verkehrszahlen zählen","Keine Messung nötig"],"a":0}]}]},"part4":{"title":"Bölüm 4 · Sunum","plays":2,"script":"Sehr geehrte Damen und Herren, ich möchte heute über Bürgerwissenschaft, auch Citizen Science genannt, sprechen. Gemeint sind Forschungsprojekte, an denen Menschen ohne professionelle wissenschaftliche Ausbildung aktiv mitwirken. Besonders bekannt sind Projekte zur Beobachtung von Vögeln, Insekten oder Wetterphänomenen. Der größte Vorteil liegt in der räumlichen und zeitlichen Reichweite: Ein kleines Forschungsteam könnte unmöglich gleichzeitig Daten aus Tausenden Orten sammeln. Freiwillige können diese Lücke schließen. Allerdings entstehen neue methodische Fragen. Wenn viele Personen Daten erfassen, unterscheiden sich Erfahrung und Genauigkeit. Gute Projekte reagieren darauf mit klaren Protokollen, Schulungen und automatischen Plausibilitätsprüfungen. Ein zweiter Punkt betrifft Motivation. Teilnehmende bleiben eher langfristig aktiv, wenn sie erfahren, wozu ihre Daten beitragen. Deshalb veröffentlichen erfolgreiche Projekte Zwischenergebnisse und erklären, wie einzelne Beobachtungen in größere Analysen einfließen. Bürgerwissenschaft ersetzt professionelle Forschung nicht. Sie erweitert vielmehr die Datengrundlage und kann Themen sichtbar machen, die sonst wenig Aufmerksamkeit erhalten. Gleichzeitig entsteht ein gesellschaftlicher Effekt: Wer selbst Daten erhebt, entwickelt oft ein genaueres Verständnis dafür, wie wissenschaftliche Erkenntnisse zustande kommen – einschließlich Unsicherheit, Fehlern und notwendigen Kontrollen. Damit Citizen Science zuverlässig funktioniert, müssen Aufgaben jedoch so gestaltet sein, dass sie ohne Spezialgeräte und mit vertretbarem Aufwand durchgeführt werden können. Besonders komplexe Messungen bleiben daher Fachleuten vorbehalten. Die Zukunft liegt vermutlich in hybriden Modellen, in denen große Freiwilligennetze mit professionellen Laboren und digitalen Prüfverfahren zusammenarbeiten.","items":[{"q":"Was ist ein Hauptvorteil von Citizen Science?","o":["Forschung wird ohne Fachleute möglich","Große räumliche und zeitliche Datenerfassung","Jede Messung wird genauer"],"a":1},{"q":"Welches Problem entsteht durch viele Freiwillige?","o":["Unterschiedliche Datengenauigkeit","Zu wenige Orte","Keine Motivation von Forschern"],"a":0},{"q":"Wie sichern gute Projekte Qualität?","o":["Sie verzichten auf Regeln","Durch Protokolle, Schulung und Plausibilitätsprüfungen","Nur durch Bezahlung"],"a":1},{"q":"Was stärkt langfristige Motivation?","o":["Wenn Ergebnisse und Nutzen sichtbar werden","Wenn Daten geheim bleiben","Wenn Aufgaben schwieriger werden"],"a":0},{"q":"Wie wird Citizen Science im Vortrag eingeordnet?","o":["Als Ersatz professioneller Forschung","Als Ergänzung professioneller Forschung","Als reine Bildungsmaßnahme"],"a":1},{"q":"Welchen gesellschaftlichen Effekt nennt der Vortrag?","o":["Mehr Verständnis für wissenschaftliche Prozesse","Weniger Interesse an Wissenschaft","Sichere Beseitigung aller Unsicherheit"],"a":0},{"q":"Was bleibt eher Fachleuten vorbehalten?","o":["Einfache Beobachtungen","Komplexe Messungen mit Spezialanforderungen","Das Lesen von Zwischenergebnissen"],"a":1}]}},"writingForum":[{"id":"wf1","title":"Üniversitede zorunlu staj","prompt":"Bir eğitim forumunda üniversite programlarında zorunlu stajın gerekli olup olmadığını tartışın.","points":["Zorunlu stajın bir avantajını açıklayın.","Olası bir dezavantajı gerekçelendirin.","Kendi ülkenizden veya deneyiminizden bir örnek verin.","Hangi koşullarda zorunlu olmasını uygun gördüğünüzü değerlendirin."],"target":230,"model":"Zorunlu staj, teorik bilginin iş yaşamıyla bağını güçlendirebilir. Özellikle öğrenciler mesleğin günlük gerçeklerini henüz tanımıyorsa, kısa süreli de olsa uygulama deneyimi kararlarını daha bilinçli hâle getirir. Bununla birlikte, her stajın otomatik olarak nitelikli bir öğrenme ortamı sunduğunu varsaymak doğru değildir. Öğrencilerin yalnızca rutin işler yaptığı ve ücret almadığı durumlarda zorunluluk haksız bir yük yaratabilir.\n\nBu nedenle bana göre belirleyici olan “staj olsun mu olmasın mı?” sorusu değil, stajın hangi standartlara göre düzenlendiğidir. Örneğin üniversite, öğrenme hedeflerini önceden belirleyebilir ve kurumdan düzenli geribildirim isteyebilir. Ayrıca ekonomik durumu sınırlı öğrencilerin ücretsiz çalışmak zorunda kalmaması için asgari bir ödeme veya burs sistemi düşünülmelidir.\n\nTürkiye’de ve Almanya’da bazı programlarda uygulama dönemi zaten önemli bir rol oynuyor. Başarılı örneklerde öğrenci, stajın ardından yaptığı işi analiz eden bir rapor hazırlıyor. Bu, deneyimi yalnızca “işte bulunmak” olmaktan çıkarıp öğrenme sürecine dönüştürüyor.\n\nSonuç olarak zorunlu stajı genel olarak destekliyorum; ancak yalnızca kalite ölçütleri, akademik rehberlik ve makul maddi koşullar garanti edildiğinde."},{"id":"wf2","title":"Dört günlük çalışma haftası","prompt":"Bir çevrimiçi forumda dört günlük çalışma haftasının yaygınlaştırılıp yaygınlaştırılmaması hakkında yazın.","points":["Modelin olası faydalarını açıklayın.","Bir uygulama sorununu tartışın.","Bir örnekle görüşünüzü destekleyin.","Sonuçta hangi yaklaşımı önerdiğinizi belirtin."],"target":230,"model":""},{"id":"wf3","title":"Yapay zekâ ile eğitim","prompt":"Üniversitelerde üretken yapay zekâ kullanımının nasıl düzenlenmesi gerektiğini tartışın.","points":["Bir fırsatı açıklayın.","Bir riski gerekçelendirin.","Somut bir kullanım örneği verin.","Kendi düzenleme önerinizi sunun."],"target":230,"model":""},{"id":"wf4","title":"Şehir merkezinde otomobil","prompt":"Şehir merkezlerinde özel otomobil kullanımının ciddi biçimde sınırlandırılması hakkında görüş yazın.","points":["Bir çevresel veya sosyal faydayı açıklayın.","Bir karşı argümanı ele alın.","Başka bir şehir/ülkeden örnek verin.","Dengeli bir çözüm önerin."],"target":230,"model":""},{"id":"wf5","title":"Ücretsiz yükseköğretim","prompt":"Yükseköğretimin herkes için tamamen ücretsiz olması gerekip gerekmediğini tartışın.","points":["Bir eşitlik argümanı sunun.","Finansman açısından bir sorun ele alın.","Bir sistem örneği verin.","Kendi sonucunuzu gerekçelendirin."],"target":230,"model":""},{"id":"wf6","title":"Uzaktan çalışma hakkı","prompt":"Uygun mesleklerde çalışanların haftanın belirli günlerinde uzaktan çalışma hakkına sahip olup olmaması üzerine yazın.","points":["Çalışan açısından bir faydayı açıklayın.","İşveren açısından bir riski tartışın.","Bir örnek verin.","Hangi koşullarda hakkı desteklediğinizi açıklayın."],"target":230,"model":""}],"writingEmail":[{"id":"we1","title":"Kütüphane çalışma alanı","prompt":"Üniversite kütüphanesinde rezervasyon yaptığınız sessiz çalışma odası sürekli grup toplantıları için kullanılıyor. Kütüphane yönetimine yazın.","points":["Sorunu açıklayın.","Bunun çalışmanızı nasıl etkilediğini belirtin.","Somut bir çözüm önerin.","Nazikçe hızlı yanıt/anlayış isteyin."],"target":120,"model":"Sehr geehrte Damen und Herren,\n\nich möchte Sie auf ein Problem mit den als „still“ ausgewiesenen Arbeitsräumen aufmerksam machen. Obwohl ich mehrfach einen Einzelarbeitsplatz reserviert habe, wurden die Räume gleichzeitig für lautere Gruppentreffen genutzt. Dadurch ist konzentriertes Arbeiten, insbesondere während meiner Prüfungsvorbereitung, kaum möglich.\n\nIch schlage vor, die Nutzungsregeln bei der Reservierung deutlicher anzuzeigen und für Gruppen separate Räume vorzusehen. Zusätzlich könnte das Bibliothekspersonal bei wiederholten Verstößen gezielt darauf hinweisen.\n\nIch wäre Ihnen dankbar, wenn Sie prüfen könnten, wie die vereinbarte ruhige Nutzung künftig besser gewährleistet werden kann. Vielen Dank für Ihr Verständnis.\n\nMit freundlichen Grüßen\nAylin Demir"},{"id":"we2","title":"Seminer tarihi değişikliği","prompt":"Bir seminer tarihi kısa süre önce değiştirildi ve yeni tarih zorunlu bir iş vardiyanızla çakışıyor. Öğretim görevlisine yazın.","points":["Durumu açıklayın.","Neden katılamadığınızı belirtin.","Bir alternatif önerin.","Anlayış rica edin."],"target":120,"model":""},{"id":"we3","title":"Yanlış fatura","prompt":"Bir dil kursu size anlaşılmış ücretten daha yüksek bir fatura gönderdi. Kurs yönetimine yazın.","points":["Farkı açıklayın.","Anlaşmayı referans gösterin.","Düzeltme önerin/isteyin.","Nazik kapanış yapın."],"target":120,"model":""},{"id":"we4","title":"Ofiste gürültü","prompt":"Yeni açık ofiste sürekli telefon görüşmeleri işinizi ciddi biçimde etkiliyor. Yöneticinize yazın.","points":["Sorunu somutlaştırın.","İş üzerindeki etkisini açıklayın.","Uygulanabilir çözüm önerin.","İşbirliğine açık olduğunuzu gösterin."],"target":120,"model":""},{"id":"we5","title":"Kurs materyali erişimi","prompt":"Çevrimiçi kurs materyallerine iki gündür erişemiyorsunuz ve son teslim tarihi yaklaşıyor. Teknik desteğe yazın.","points":["Sorunu tarif edin.","Denediğiniz adımları belirtin.","Acil çözüm/uzatma önerin.","Yanıt rica edin."],"target":120,"model":""},{"id":"we6","title":"Toplantı gündemi","prompt":"Toplantı gündeminde sizin alanınızla ilgili kritik bir konu eksik. Organizatöre yazın.","points":["Eksik konuyu belirtin.","Neden önemli olduğunu açıklayın.","Gündeme eklenmesini önerin.","Nazikçe teyit isteyin."],"target":120,"model":""}],"speakingPresentations":[{"id":"sp1","title":"Üniversitelerde yapay zekâ","intro":"Bir seminerde üretken yapay zekânın üniversite eğitimindeki rolü üzerine kısa bir sunum yapın.","points":["Somut bir kullanım örneği verin.","Bir fırsatı ve bir riski karşılaştırın.","Hangi kuralların gerekli olduğunu açıklayın.","Kendi değerlendirmenizle sonuçlandırın."],"questions":["Welche Kompetenz sollten Studierende im Umgang mit KI unbedingt lernen?","Wo würden Sie eine klare Grenze ziehen?"]},{"id":"sp2","title":"Şehirde yeşil alan","intro":"Büyük şehirlerde yeşil alanların genişletilmesi hakkında sunum yapın.","points":["Bir güncel sorunu örnekleyin.","Çevresel ve sosyal etkileri açıklayın.","Olası maliyet/çatışmaları tartışın.","Bir öncelik önerin."],"questions":["Wer sollte solche Projekte finanzieren?","Wie kann man Nutzungskonflikte lösen?"]},{"id":"sp3","title":"Dört günlük çalışma haftası","intro":"Dört günlük çalışma haftasının fırsat ve sınırlarını sunun.","points":["Bir model tanımlayın.","Fayda ve riski tartışın.","Bir sektör örneği verin.","Kendi koşullu görüşünüzü belirtin."],"questions":["Für welche Branchen wäre das Modell besonders schwierig?","Wie könnte man Produktivität sinnvoll messen?"]},{"id":"sp4","title":"Üniversitede devam zorunluluğu","intro":"Üniversite derslerinde devam zorunluluğunu değerlendirin.","points":["Bir gerekçe sunun.","Karşı görüşü ele alın.","Kendi deneyiminizden örnek verin.","Alternatif bir model önerin."],"questions":["Sollte Anwesenheit benotet werden?","Wie könnte man aktive Teilnahme anders messen?"]},{"id":"sp5","title":"Toplu taşıma ücretsiz mi?","intro":"Şehir içi toplu taşımanın ücretsiz olması gerekip gerekmediğini tartışan bir sunum yapın.","points":["Bir avantaj açıklayın.","Finansman sorununu ele alın.","Bir şehir örneği verin.","Kendi çözümünüzü önerin."],"questions":["Wer sollte die Kosten tragen?","Würde kostenloser ÖPNV automatisch den Autoverkehr senken?"]},{"id":"sp6","title":"Uzaktan çalışma","intro":"Uzaktan çalışmanın uzun vadeli etkileri üzerine sunum yapın.","points":["Çalışan açısından bir etki açıklayın.","Şirket açısından bir etki açıklayın.","Takım iletişimini değerlendirin.","Hibrit bir model önerin."],"questions":["Wie viel Präsenz halten Sie für sinnvoll?","Welche Aufgaben eignen sich nicht fürs Homeoffice?"]}],"speakingDiscussions":[{"id":"sd1","title":"KI ile yazılmış ödevler","input":"Bir üniversite, üretken yapay zekâ ile hazırlanmış ödevlerin tamamen yasaklanmasını tartışıyor.","points":["Yasak ne kadar uygulanabilir?","Öğrenme hedefleri nasıl korunur?","Şeffaflık kuralları yeterli olabilir mi?","Ortak bir öneri geliştirin."]},{"id":"sd2","title":"Şehir merkezinde araç kısıtlaması","input":"Belediye, merkezde özel araç trafiğini yarıya indirmeyi planlıyor.","points":["Çevresel etkiler","Esnaf ve erişilebilirlik","Alternatif ulaşım","Ortak öncelikler"]},{"id":"sd3","title":"Zorunlu gönüllü hizmet","input":"Genç yetişkinler için altı aylık toplumsal hizmet zorunluluğu öneriliyor.","points":["Toplumsal fayda","Bireysel özgürlük","Eğitim/işe etkisi","Olası alternatif model"]},{"id":"sd4","title":"Dört günlük çalışma haftası","input":"Bir şirket ücret azaltmadan dört günlük haftayı kalıcılaştırmak istiyor.","points":["Verimlilik","Müşteri erişimi","Çalışan yükü","Pilot uygulama ölçütleri"]},{"id":"sd5","title":"Üniversite harcı","input":"Devlet üniversitelerinde düşük miktarlı genel öğrenim harcı öneriliyor.","points":["Finansman","Eşitlik","Muafiyet/burs","Ortak çözüm"]},{"id":"sd6","title":"Sosyal medyada yaş sınırı","input":"16 yaş altı için sosyal medya hesaplarına daha sıkı yaş doğrulaması öneriliyor.","points":["Çocuk koruma","Mahremiyet","Uygulanabilirlik","Ebeveyn/eğitim rolü"]}],"goetheMock":{"reading":{"part1":{"title":"Bölüm 1 · Sözcük boşlukları","text":"Solaranlagen und begrünte Dächer wurden lange als konkurrierende Nutzungen betrachtet. Neuere Planungsansätze versuchen jedoch, beide Systeme auf derselben Fläche ___(1)___. Pflanzen können durch Verdunstung und Schatten dazu beitragen, dass sich Solarmodule an heißen Tagen weniger stark erwärmen und dadurch effizienter ___(2)___. Allerdings eignet sich nicht jedes Gebäude für eine solche Kombination. Tragfähigkeit, Windlast und Zugang für die Wartung müssen bereits in der Planung ___(3)___ werden. Fachleute weisen außerdem darauf hin, dass die Auswahl der Pflanzen an die besonderen Bedingungen auf dem Dach ___(4)___ sein muss. Arten, die viel Wasser benötigen, sind in trockenen Sommern problematisch. Gut geplante Systeme können dagegen Regenwasser zurückhalten und die Artenvielfalt fördern. Ob sich die höheren Anfangskosten langfristig ___(5)___, hängt von Standort, Bauweise und Pflege ab. Entscheidend ist deshalb, die Wirkung nicht anhand einzelner Beispiele zu beurteilen, ___(6)___ über mehrere Jahre systematisch zu erfassen. Erst dann lässt sich verlässlich sagen, unter welchen Bedingungen sich beide Nutzungen gegenseitig ___(7)___ und wo Zielkonflikte entstehen. Kommunen, die solche Projekte fördern möchten, sollten daher nicht nur technische Standards festlegen, ___(8)___ auch Beratung und langfristige Evaluation einplanen.","items":[{"o":["zu verbinden","verbunden","verbindlich","Verbindung"],"a":0},{"o":["arbeiten","wirken","leisten","erzeugen"],"a":1},{"o":["berücksichtigt","beobachtet","begründet","verhindert"],"a":0},{"o":["angepasst","angewiesen","aufgeteilt","ausgelöst"],"a":0},{"o":["auszahlen","auszahlt","bezahlen","bezahlt"],"a":1},{"o":["sondern","obwohl","damit","während"],"a":0},{"o":["ergänzen","ersetzen","vermeiden","begrenzen"],"a":0},{"o":["aber","sondern","dennoch","obwohl"],"a":1}]},"part2":{"title":"Bölüm 2 · Ana fikirler ve ayrıntılı bilgiler","text":"Viele Hochschulen versuchen seit einigen Jahren, Prinzipien der offenen Wissenschaft stärker zu verankern. Häufig wird darunter vor allem verstanden, wissenschaftliche Artikel kostenlos zugänglich zu machen. Open Science umfasst jedoch deutlich mehr: Auch Forschungsdaten, Methoden und teilweise sogar Auswertungsschritte sollen so dokumentiert werden, dass andere Forschende Ergebnisse nachvollziehen und - soweit möglich - überprüfen können.\n\nBefürworter sehen darin einen wichtigen Beitrag zur Qualitätssicherung. Wenn Datensätze und Analysewege zugänglich sind, lassen sich Fehler leichter entdecken und Ergebnisse eher reproduzieren. Zudem können bereits erhobene Daten für neue Fragestellungen genutzt werden. Das spart unter Umständen Zeit und Ressourcen. Allerdings ist nicht jeder Datensatz ohne Weiteres veröffentlichbar. Besonders in Medizin, Psychologie und Sozialforschung können Angaben enthalten sein, die Rückschlüsse auf einzelne Personen zulassen. Datenschutz und informierte Einwilligung müssen deshalb von Beginn an berücksichtigt werden.\n\nEin weiteres Problem ist der Arbeitsaufwand. Daten so aufzubereiten, dass Außenstehende sie tatsächlich verstehen, erfordert klare Dokumentation, standardisierte Formate und häufig zusätzliche Metadaten. Forschende kritisieren, dass diese Arbeit in vielen Karrieresystemen bislang kaum anerkannt wird. Wer Zeit in saubere Dokumentation investiert, hat nicht automatisch bessere Chancen bei Bewerbungen oder Förderanträgen. Fachleute fordern daher, offene Forschungspraktiken auch bei Leistungsbewertungen stärker zu berücksichtigen.\n\nKontrovers diskutiert wird außerdem, ob Offenheit in jedem Stadium sinnvoll ist. Bei laufenden Projekten kann eine zu frühe Veröffentlichung Ideen gefährden, an denen Teams über Jahre gearbeitet haben. Andere halten dagegen, dass transparente Vorregistrierungen gerade verhindern können, dass nur erwünschte Resultate veröffentlicht werden. Ein einheitliches Modell für alle Disziplinen dürfte daher kaum funktionieren.\n\nDie Debatte zeigt, dass offene Wissenschaft weder eine einfache technische Lösung noch ein Selbstzweck ist. Sie kann Vertrauen und Nachprüfbarkeit fördern, wenn rechtliche, ethische und organisatorische Voraussetzungen stimmen. Entscheidend ist weniger, möglichst alles öffentlich zu machen, als nachvollziehbar zu begründen, was geteilt werden kann, was geschützt werden muss und wie wissenschaftliche Arbeit dafür angemessen honoriert wird.","items":[{"q":"Was umfasst Open Science laut Text über frei zugängliche Artikel hinaus?","o":["Nur öffentliche Vorträge","Auch Daten, Methoden und Auswertungsschritte","Ausschließlich kostenlose Lehrbücher"],"a":1},{"q":"Welchen Vorteil nennen Befürworter?","o":["Fehler und Ergebnisse lassen sich leichter überprüfen.","Forschung wird grundsätzlich billiger.","Datenschutz wird überflüssig."],"a":0},{"q":"Warum können Forschungsdaten nicht immer vollständig veröffentlicht werden?","o":["Weil Dateien meist zu groß sind.","Weil Rückschlüsse auf Personen möglich sein können.","Weil Zeitschriften dies grundsätzlich verbieten."],"a":1},{"q":"Welche Schwierigkeit betrifft die Aufbereitung von Daten?","o":["Sie erfordert zusätzliche Dokumentation und Zeit.","Sie ist nur mit kommerzieller Software möglich.","Sie verhindert weitere Forschung mit den Daten."],"a":0},{"q":"Was wird an heutigen Karrieresystemen kritisiert?","o":["Offene Forschungspraktiken werden oft zu wenig anerkannt.","Veröffentlichungen spielen überhaupt keine Rolle.","Forschende dürfen keine Metadaten erstellen."],"a":0},{"q":"Warum ist eine zu frühe Offenlegung umstritten?","o":["Sie kann langjährig entwickelte Ideen gefährden.","Sie macht Vorregistrierungen unmöglich.","Sie ist in allen Fächern gesetzlich verboten."],"a":0},{"q":"Welche Schlussfolgerung zieht der Text?","o":["Alle Forschungsdaten sollten ohne Ausnahme öffentlich sein.","Offenheit muss fachlich, rechtlich und ethisch differenziert gestaltet werden.","Open Science ist vor allem eine technische Speicherfrage."],"a":1}]},"part3":{"title":"Bölüm 3 · Cümleleri yeniden yerleştirme","segments":["Da sommerliche Hitze in Städten zunimmt, gewinnt die kühlende Wirkung von Bäumen an Bedeutung. ___(1)___","Pauschale Angaben wie „ein Baum senkt die Temperatur um mehrere Grad“ sind deshalb nur begrenzt aussagekräftig. ___(2)___","Hinzu kommt, dass Stadtbäume selbst stärker unter Trockenheit und Hitze leiden. ___(3)___","Planerinnen und Planer setzen daher zunehmend auf eine größere Artenvielfalt. ___(4)___","Vielfalt allein reicht jedoch nicht aus. Auch der Wasserbedarf muss berücksichtigt werden. ___(5)___","Ein weiterer Faktor ist das Alter der Bäume. Große, etablierte Kronen können deutlich mehr Schatten spenden als junge Pflanzungen. ___(6)___","Bei neuen Programmen stellt sich außerdem die Frage, in welchen Stadtteilen zuerst investiert werden soll. ___(7)___","Damit wird Stadtbegrünung nicht nur zu einer ästhetischen, sondern auch zu einer langfristigen Gesundheits- und Gerechtigkeitsfrage. ___(8)___"],"candidates":["A: Denn die Wirkung hängt unter anderem von Art, Alter, Kronengröße und Wasserversorgung ab.","B: Dieses Thema spielt ausschließlich in ländlichen Regionen eine Rolle.","C: Klimamodelle deuten darauf hin, dass manche traditionell verwendeten Arten künftig stärker unter Stress geraten.","D: Monokulturen können bei einer einzigen Krankheit besonders große Verluste erleiden.","E: Dadurch sinken die Pflegekosten in jedem Fall auf null.","F: Das Fällen ausgewachsener Bäume lässt sich daher kurzfristig kaum durch Neupflanzungen ausgleichen.","G: Priorität sollten besonders heiße und bislang schlecht mit Grünflächen versorgte Quartiere erhalten.","H: Vor allem in trockenen Regionen muss geklärt werden, woher zusätzliches Bewässerungswasser kommen kann.","I: Ziel sollte es sein, in jeder Straße dieselbe Baumart zu pflanzen.","J: Der Blick verschiebt sich damit von heutigen Standortbedingungen auf die Widerstandsfähigkeit der nächsten Jahrzehnte."],"answers":[0,9,2,3,7,5,6,4]},"part4":{"title":"Bölüm 4 · Görüşleri eşleştirme","texts":[{"name":"A · Dr. Richter","text":"Aufzeichnungen von Lehrveranstaltungen können das Nacharbeiten erleichtern. Eine permanente Aufnahme kann aber offene Diskussionen hemmen, besonders bei sensiblen Themen. Deshalb sollte je nach Veranstaltungsform entschieden werden."},{"name":"B · Prof. Lang","text":"Ich halte Aufzeichnungen grundsätzlich für sinnvoll. Studierende mit Krankheit, Betreuungspflichten oder Sprachbarrieren profitieren besonders. Entscheidend ist, dass Lehrende wissen, wann aufgezeichnet wird und welche Beiträge später veröffentlicht werden."},{"name":"C · Dr. Seidel","text":"Die Debatte konzentriert sich zu stark auf Technik. Eine Aufnahme ersetzt keine gute Lehrgestaltung. Wenn Studierende wissen, dass alles später verfügbar ist, kann sogar die aktive Teilnahme sinken. Aufzeichnungen sollten daher nur ergänzend eingesetzt werden."},{"name":"D · Prof. Kramer","text":"Bei großen Vorlesungen überwiegen für mich die Vorteile. In kleinen Seminaren mit persönlicher Diskussion würde ich dagegen meist darauf verzichten. Eine einheitliche Regel für alle Lehrveranstaltungen wäre pädagogisch wenig sinnvoll."}],"items":[{"q":"Wer warnt ausdrücklich davor, dass Aufzeichnungen offene Diskussionen beeinträchtigen können?","a":0},{"q":"Wer betont besonders den Nutzen für Studierende mit erschwertem Zugang zur Veranstaltung?","a":1},{"q":"Wer befürchtet, dass die aktive Teilnahme durch die spätere Verfügbarkeit sinken kann?","a":2},{"q":"Wer unterscheidet klar zwischen großen Vorlesungen und kleinen Seminaren?","a":3},{"q":"Wer hält transparente Regeln darüber, was aufgezeichnet und veröffentlicht wird, für entscheidend?","a":1},{"q":"Wer argumentiert, dass Technik gute Didaktik nicht ersetzen kann?","a":2},{"q":"Wer lehnt eine einheitliche Regel für alle Veranstaltungsformen ab?","a":3}]}},"listening":{"part1":{"title":"Bölüm 1 · Podcast eşleştirme","plays":1,"script":"Willkommen zu „Ideen im Alltag“. Heute stelle ich drei neue Sachbücher vor. Das erste Buch, „Leise Städte“, untersucht, wie Lärm unsere Gesundheit beeinflusst. Besonders stark ist der historische Vergleich: Die Autorin zeigt, wie sich Geräuschquellen seit der Industrialisierung verändert haben und warum absolute Stille in einer Stadt weder realistisch noch unbedingt wünschenswert ist. Das zweite Buch, „Reparieren statt ersetzen“, beschäftigt sich mit Produktdesign. Der Autor besucht Werkstätten, Start-ups und kommunale Reparaturzentren. Er argumentiert, dass langlebige Produkte nicht nur eine technische, sondern auch eine politische Frage sind. Das dritte Buch heißt „Die Kunst des Wartens“. Eine Psychologin verbindet Forschung zu Aufmerksamkeit mit persönlichen Beobachtungen. Sie erklärt, warum Wartezeiten heute als besonders belastend erlebt werden und wie kleine Unterbrechungen sogar kreative Prozesse fördern können.","labels":["A · Leise Städte","B · Reparieren statt ersetzen","C · Die Kunst des Wartens"],"items":[{"q":"Historische Entwicklungen spielen eine wichtige Rolle.","a":0},{"q":"Politische Rahmenbedingungen werden thematisiert.","a":1},{"q":"Persönliche Erfahrungen werden mit Forschung verbunden.","a":2},{"q":"Es geht um die Lebensdauer von Gegenständen.","a":1},{"q":"Ein vermeintlich negativer Zustand kann Vorteile haben.","a":2},{"q":"Völlige Abwesenheit des Problems wird nicht als Ziel dargestellt.","a":0}]},"part2":{"title":"Bölüm 2 · Uzman röportajı","plays":2,"script":"Moderatorin: Herr Neumann, viele Menschen glauben, Multitasking spare Zeit. Stimmt das? Experte: Bei einfachen, automatisierten Tätigkeiten können mehrere Prozesse parallel laufen. Bei anspruchsvollen Denkaufgaben wechseln wir jedoch meist schnell zwischen Aufgaben. Dieser Wechsel kostet Zeit und erhöht die Fehlerquote. Moderatorin: Ist das bei jungen Menschen anders? Experte: Sie sind oft an häufige Unterbrechungen gewöhnt, aber Gewöhnung bedeutet nicht automatisch bessere Leistung. In unseren Studien sehen wir eher, dass Personen ihre eigene Effizienz überschätzen. Moderatorin: Hilft es, Benachrichtigungen auszuschalten? Experte: Ja, allerdings reicht das allein nicht. Wer ständig erwartet, dass eine Nachricht kommen könnte, bleibt innerlich aufmerksam für mögliche Unterbrechungen. Sinnvoll sind deshalb klar definierte Phasen, in denen Kommunikationskanäle geschlossen werden. Moderatorin: Manche Unternehmen führen Fokuszeiten ein. Experte: Das kann funktionieren, wenn die Organisation es ernst meint. Es bringt wenig, zwei Stunden als Fokuszeit zu deklarieren und gleichzeitig schnelle Antworten zu erwarten. Moderatorin: Gibt es Tätigkeiten, bei denen Unterbrechungen sogar nützlich sind? Experte: Bei kreativen Problemen kann eine Pause helfen. Das ist aber etwas anderes als eine zufällige Nachricht. Eine bewusst gewählte Unterbrechung kann Distanz schaffen; unvorhersehbare Unterbrechungen fragmentieren eher die Aufmerksamkeit.","items":[{"q":"Bei komplexen Aufgaben erledigt das Gehirn mehrere Denkprozesse gleichzeitig.","a":1},{"q":"Häufiger Aufgabenwechsel kann die Fehlerquote erhöhen.","a":0},{"q":"Jüngere Menschen sind nachweislich effizienter im Multitasking.","a":1},{"q":"Menschen überschätzen laut Experte teilweise ihre Multitasking-Leistung.","a":0},{"q":"Ausgeschaltete Benachrichtigungen lösen das Problem vollständig.","a":1},{"q":"Fokuszeiten funktionieren nur, wenn Erwartungen im Unternehmen dazu passen.","a":0},{"q":"Der Experte empfiehlt Fokuszeiten von genau zwei Stunden.","a":2},{"q":"Bewusste Pausen können bei kreativen Problemen hilfreich sein.","a":0},{"q":"Jede Form von Unterbrechung wirkt gleich auf Aufmerksamkeit.","a":1}],"labels":["stimmt","stimmt nicht","dazu wird nichts gesagt"]},"part3":{"title":"Bölüm 3 · Tartışma","plays":1,"segments":[{"script":"Moderator: Sollten Innenstädte komplett autofrei werden? Stadtplanerin: Ein vollständiges Verbot klingt einfach, ignoriert aber Lieferverkehr und Menschen mit eingeschränkter Mobilität. Ich plädiere für deutlich weniger privaten Autoverkehr, aber mit klar definierten Ausnahmen. Händler: Mein Hauptproblem ist nicht die Reduktion an sich, sondern die Planbarkeit. Wenn Regeln ständig wechseln, können Betriebe Logistik kaum organisieren.","items":[{"q":"Was fordert die Stadtplanerin?","o":["Ein ausnahmsloses Verbot","Weniger privaten Autoverkehr mit Ausnahmen","Mehr Parkplätze"],"a":1},{"q":"Was kritisiert der Händler vor allem?","o":["Unklare und wechselnde Regeln","Zu viele Fahrräder","Zu wenig Lieferverkehr"],"a":0}]},{"script":"Moderator: Häufig heißt es, weniger Autos machten Zentren automatisch attraktiver. Händler: Das kann stimmen, wenn gleichzeitig gute Erreichbarkeit geschaffen wird. Wer nur Parkplätze entfernt, ohne ÖPNV und Lieferzonen zu verbessern, verlagert Probleme. Stadtplanerin: Genau deshalb müssen Maßnahmen als Paket geplant werden. Aufenthaltsqualität entsteht nicht durch Verbote allein.","items":[{"q":"Wovon hängt Attraktivität laut Händler ab?","o":["Nur von weniger Parkplätzen","Von alternativer Erreichbarkeit und Logistik","Von höheren Mieten"],"a":1},{"q":"Worin sind sich beide einig?","o":["Einzelmaßnahmen reichen nicht","Autos müssen unverändert bleiben","ÖPNV spielt keine Rolle"],"a":0}]},{"script":"Moderator: Wie reagieren Bewohner? Stadtplanerin: Am Anfang gibt es oft Widerstand, weil Menschen Verluste stärker wahrnehmen als mögliche Gewinne. Nach Umbauten steigt die Zustimmung häufig, wenn der öffentliche Raum tatsächlich besser nutzbar wird. Händler: Erfahrungen aus anderen Städten sind hilfreich, aber sie lassen sich nicht eins zu eins übertragen.","items":[{"q":"Wie erklärt die Stadtplanerin anfänglichen Widerstand?","o":["Menschen gewichten Verluste stark","Alle sind gegen Veränderungen","Es fehlen Daten"],"a":0},{"q":"Was sagt der Händler zu anderen Städten?","o":["Erfahrungen sind wertlos","Modelle müssen an lokale Bedingungen angepasst werden","Man soll alles kopieren"],"a":1}]},{"script":"Moderator: Was wäre ein vernünftiger nächster Schritt? Händler: Pilotzonen mit klaren Messkriterien. Dann kann man sehen, wie sich Umsätze, Lieferzeiten und Besucherzahlen entwickeln. Stadtplanerin: Dem stimme ich zu. Zusätzlich würde ich Luftqualität und Aufenthaltsdauer messen. Entscheidungen sollten danach auf mehreren Kriterien beruhen, nicht nur auf Verkehrszahlen.","items":[{"q":"Was schlägt der Händler vor?","o":["Sofortiges dauerhaftes Verbot","Pilotzonen mit Messkriterien","Keine Veränderung"],"a":1},{"q":"Was ergänzt die Stadtplanerin?","o":["Weitere Qualitätsindikatoren","Nur Verkehrszahlen zählen","Keine Messung nötig"],"a":0}]}]},"part4":{"title":"Bölüm 4 · Sunum","plays":2,"script":"Sehr geehrte Damen und Herren, ich möchte heute über Bürgerwissenschaft, auch Citizen Science genannt, sprechen. Gemeint sind Forschungsprojekte, an denen Menschen ohne professionelle wissenschaftliche Ausbildung aktiv mitwirken. Besonders bekannt sind Projekte zur Beobachtung von Vögeln, Insekten oder Wetterphänomenen. Der größte Vorteil liegt in der räumlichen und zeitlichen Reichweite: Ein kleines Forschungsteam könnte unmöglich gleichzeitig Daten aus Tausenden Orten sammeln. Freiwillige können diese Lücke schließen. Allerdings entstehen neue methodische Fragen. Wenn viele Personen Daten erfassen, unterscheiden sich Erfahrung und Genauigkeit. Gute Projekte reagieren darauf mit klaren Protokollen, Schulungen und automatischen Plausibilitätsprüfungen. Ein zweiter Punkt betrifft Motivation. Teilnehmende bleiben eher langfristig aktiv, wenn sie erfahren, wozu ihre Daten beitragen. Deshalb veröffentlichen erfolgreiche Projekte Zwischenergebnisse und erklären, wie einzelne Beobachtungen in größere Analysen einfließen. Bürgerwissenschaft ersetzt professionelle Forschung nicht. Sie erweitert vielmehr die Datengrundlage und kann Themen sichtbar machen, die sonst wenig Aufmerksamkeit erhalten. Gleichzeitig entsteht ein gesellschaftlicher Effekt: Wer selbst Daten erhebt, entwickelt oft ein genaueres Verständnis dafür, wie wissenschaftliche Erkenntnisse zustande kommen – einschließlich Unsicherheit, Fehlern und notwendigen Kontrollen. Damit Citizen Science zuverlässig funktioniert, müssen Aufgaben jedoch so gestaltet sein, dass sie ohne Spezialgeräte und mit vertretbarem Aufwand durchgeführt werden können. Besonders komplexe Messungen bleiben daher Fachleuten vorbehalten. Die Zukunft liegt vermutlich in hybriden Modellen, in denen große Freiwilligennetze mit professionellen Laboren und digitalen Prüfverfahren zusammenarbeiten.","items":[{"q":"Was ist ein Hauptvorteil von Citizen Science?","o":["Forschung wird ohne Fachleute möglich","Große räumliche und zeitliche Datenerfassung","Jede Messung wird genauer"],"a":1},{"q":"Welches Problem entsteht durch viele Freiwillige?","o":["Unterschiedliche Datengenauigkeit","Zu wenige Orte","Keine Motivation von Forschern"],"a":0},{"q":"Wie sichern gute Projekte Qualität?","o":["Sie verzichten auf Regeln","Durch Protokolle, Schulung und Plausibilitätsprüfungen","Nur durch Bezahlung"],"a":1},{"q":"Was stärkt langfristige Motivation?","o":["Wenn Ergebnisse und Nutzen sichtbar werden","Wenn Daten geheim bleiben","Wenn Aufgaben schwieriger werden"],"a":0},{"q":"Wie wird Citizen Science im Vortrag eingeordnet?","o":["Als Ersatz professioneller Forschung","Als Ergänzung professioneller Forschung","Als reine Bildungsmaßnahme"],"a":1},{"q":"Welchen gesellschaftlichen Effekt nennt der Vortrag?","o":["Mehr Verständnis für wissenschaftliche Prozesse","Weniger Interesse an Wissenschaft","Sichere Beseitigung aller Unsicherheit"],"a":0},{"q":"Was bleibt eher Fachleuten vorbehalten?","o":["Einfache Beobachtungen","Komplexe Messungen mit Spezialanforderungen","Das Lesen von Zwischenergebnissen"],"a":1}]}},"writing":{"forum":{"id":"mock-w1","title":"Künstliche Intelligenz in der Hochschullehre","prompt":"Sie schreiben einen Diskussionsbeitrag in einem Hochschulforum. Diskutieren Sie, wie der Einsatz generativer künstlicher Intelligenz an Hochschulen geregelt werden sollte.","points":["Erläutern Sie eine Chance.","Begründen Sie ein Risiko.","Veranschaulichen Sie Ihre Argumentation an einem konkreten Beispiel.","Machen Sie einen Vorschlag für sinnvolle Regeln."],"target":230,"model":""},"email":{"id":"mock-w2","title":"Arbeitsraum in der Bibliothek","prompt":"Sie haben in der Universitätsbibliothek wiederholt einen als ruhig ausgewiesenen Arbeitsraum reserviert. Der Raum wird jedoch regelmäßig für laute Gruppentreffen genutzt. Schreiben Sie an die Bibliotheksleitung.","points":["Machen Sie auf das Problem aufmerksam.","Beschreiben Sie die Auswirkungen auf Ihre Arbeit.","Schlagen Sie eine konkrete Lösung vor.","Bitten Sie höflich um eine zeitnahe Reaktion."],"target":120,"model":""}},"speaking":{"presentation":{"id":"mock-sp1","title":"Künstliche Intelligenz an Hochschulen","intro":"Sie nehmen an einem Seminar zu aktuellen Fragen teil und halten einen kurzen Vortrag über generative künstliche Intelligenz in der Hochschullehre.","points":["Geben Sie ein konkretes Anwendungsbeispiel.","Vergleichen Sie eine Chance und ein Risiko.","Erläutern Sie, welche Regeln Sie für notwendig halten.","Schließen Sie mit Ihrer eigenen Bewertung."],"questions":["Welche Kompetenz sollten Studierende im Umgang mit KI unbedingt lernen?","Wo würden Sie eine klare Grenze für den Einsatz ziehen?"]},"discussion":{"id":"mock-sd1","title":"Autoverkehr im Stadtzentrum","input":"Eine Stadt plant, den privaten Autoverkehr im Zentrum innerhalb von fünf Jahren deutlich zu reduzieren.","points":["Umwelt- und Gesundheitswirkungen","Erreichbarkeit und lokale Wirtschaft","Alternativen zum privaten Auto","Prioritäten für einen tragfähigen Kompromiss"]}}},"telc":{"overview":[{"name":"Okuduğunu anlama","detail":"90 dk. · Bölüm 1: 6 metin rekonstrüksiyonu · Bölüm 2: 6 seçici okuma · Bölüm 3: 11 doğru/yanlış/metinde yok + 1 başlık","points":48},{"name":"Dil yapıları","detail":"22 adet 4 seçenekli dilbilgisi/kelime sorusu","points":22},{"name":"Ara","detail":"20 dk.","points":0},{"name":"Dinlediğini anlama","detail":"yakl. 40 dk. · 8 genel eşleştirme · 10 ayrıntı sorusu · 10 bilgi aktarımı","points":48},{"name":"Yazılı anlatım","detail":"70 dk. · 2 konudan 1 uzun tartışmacı/görüş bildiren metin","points":48},{"name":"Sözlü anlatım","detail":"20 dk hazırlık + yakl. 16 dk çift sınav · sunum, partner özeti/sorular ve tartışma","points":48}],"reading1":{"text":"Wissenschaftliche Konferenzen galten lange als unverzichtbare Orte der persönlichen Begegnung. Die Erfahrungen mit digitalen Veranstaltungen haben jedoch gezeigt, dass sich manche Funktionen auch online erfolgreich ___(1)___. Besonders für kurze Fachbeiträge und internationale Teilnahme ___(2)___ virtuelle Formate deutliche Vorteile. Gleichzeitig wurde häufig darauf hingewiesen, dass zufällige Begegnungen und informelle Gespräche online schwerer ___(3)___. Viele Einrichtungen versuchen deshalb inzwischen, beide Formate nicht gegeneinander ___(4)___, sondern je nach Ziel zu kombinieren. Damit hybride Veranstaltungen funktionieren, müssen Online-Teilnehmende aktiv in die Diskussion ___(5)___ werden. Andernfalls bleiben sie leicht in einer passiven Zuschauerrolle. Die zentrale Frage der Konferenzplanung lautet künftig daher nicht mehr „digital oder vor Ort?“, sondern welche Funktion in welchem Format am besten ___(6)___ werden kann.","options":[["verbieten lassen","übersehen lassen","erfüllen lassen","absagen lassen"],["bieten","verschließen","bestreiten","verhindern"],["bestanden","ertragen","verloren","entstehen"],["auszugeben","auszuspielen","auszulassen","auszurichten"],["entzogen","umgangen","einbezogen","verschoben"],["erfüllt","vermutet","verschwiegen","vermieden"]],"answers":[2,0,3,1,2,0]},"reading2":{"texts":[{"id":"A","text":"Die Universitätsbibliothek bleibt künftig auch nachts geöffnet. In den unbesetzten Zeiten ist der Zutritt jedoch nur mit Bibliotheksausweis möglich; eine persönliche Beratung wird dann nicht angeboten."},{"id":"B","text":"Ein neuer Forschungsfonds fördert ausschließlich Projekte, an denen mindestens zwei Teams aus unterschiedlichen Fakultäten beteiligt sind. Anträge aus nur einem Fachbereich werden nicht berücksichtigt."},{"id":"C","text":"Das Sprachenzentrum bietet im Sommer einen Intensivkurs Deutsch an. Der Unterricht findet vormittags statt. Für die Anmeldung ist ein B2-Zertifikat oder ein entsprechendes Ergebnis im Einstufungstest erforderlich."},{"id":"D","text":"Das Fahrradverleihsystem auf dem Campus wird erneuert. Die ersten 30 Minuten jeder Fahrt sind kostenlos, längere Nutzungszeiten werden berechnet. Für Studierende und Beschäftigte gelten dieselben Bedingungen."},{"id":"E","text":"Das Career Center bietet Absolventinnen und Absolventen Online-Beratung an. In den ersten zwei Jahren nach dem Abschluss ist dieser Service kostenlos, danach fällt eine Gebühr an."},{"id":"F","text":"Die theoretische Labor-Sicherheitsschulung kann vollständig online absolviert werden. Der praktische Teil muss dagegen persönlich auf dem Campus durchgeführt werden."}],"items":[{"q":"Wer braucht für die Nutzung außerhalb normaler Zeiten eine Karte?","a":"A"},{"q":"Wo ist Zusammenarbeit zwischen Fachbereichen Voraussetzung?","a":"B"},{"q":"Wo muss ein bestimmtes Sprachniveau nachgewiesen werden?","a":"C"},{"q":"Welches Angebot ist nur für kurze Nutzung vollständig kostenlos?","a":"D"},{"q":"Welches Angebot bleibt nach Abschluss nur zeitlich begrenzt gratis?","a":"E"},{"q":"Wo kann ein Teil digital, ein anderer aber nur vor Ort absolviert werden?","a":"F"}]},"reading3":{"text":"Peer-Review-Verfahren sollen wissenschaftliche Qualität sichern, indem Fachkolleginnen und Fachkollegen Manuskripte vor der Veröffentlichung prüfen. Das System ist jedoch nicht einheitlich. Bei manchen Zeitschriften kennen Gutachter die Namen der Autorinnen und Autoren, bei anderen bleiben beide Seiten anonym. Befürworter stärkerer Anonymisierung hoffen, dass institutionelles Prestige oder bekannte Namen weniger Einfluss haben. Vollständige Anonymität lässt sich in kleinen Fachgebieten allerdings oft nicht gewährleisten, weil Thema, Datensatz oder Zitierweise Rückschlüsse zulassen.\n\nKritisiert wird außerdem, dass Gutachten meist unbezahlt erstellt werden. Für Forschende ist diese Arbeit Teil der wissenschaftlichen Selbstverwaltung, konkurriert aber mit Forschung, Lehre und Verwaltung. Einige Verlage experimentieren deshalb mit Anerkennungssystemen, etwa dokumentierten Reviewer-Profilen oder formellen Zertifikaten. Eine direkte Bezahlung ist dagegen umstritten, weil sie neue Interessenkonflikte schaffen könnte.\n\nAuch Geschwindigkeit ist ein Problem. Ein sorgfältiges Gutachten braucht Zeit, während Autorinnen und Autoren Ergebnisse möglichst schnell veröffentlichen möchten. Preprints umgehen diese Verzögerung, indem Manuskripte bereits vor dem Peer Review öffentlich zugänglich gemacht werden. Dadurch kann Wissen schneller zirkulieren, doch die Texte sind zu diesem Zeitpunkt noch nicht formal begutachtet. Leser müssen den Status daher richtig einordnen.\n\nTrotz aller Kritik wird Peer Review nicht einfach als überholt betrachtet. Viele Fachleute sehen vielmehr Reformbedarf: transparentere Kriterien, bessere Anerkennung der Gutachterarbeit und klarere Kennzeichnung unterschiedlicher Veröffentlichungsstadien.","items":[{"q":"Bei allen Zeitschriften bleiben Autor und Gutachter anonym.","a":1},{"q":"Anonymisierung soll den Einfluss bekannter Namen reduzieren.","a":0},{"q":"In kleinen Fachgebieten kann Anonymität schwer sicherzustellen sein.","a":0},{"q":"Der Text nennt eine feste Zahl von Tagen, innerhalb derer jedes Peer-Review abgeschlossen sein muss.","a":2},{"q":"Zertifikate werden als mögliche Anerkennung erprobt.","a":0},{"q":"Direkte Bezahlung ist völlig unumstritten.","a":1},{"q":"Preprints erscheinen erst nach abgeschlossenem Peer Review.","a":1},{"q":"Preprints können Forschung schneller sichtbar machen.","a":0},{"q":"Der Text gibt an, wie hoch die Honorare für Gutachterinnen und Gutachter durchschnittlich sind.","a":2},{"q":"Der Text fordert die vollständige Abschaffung von Peer Review.","a":1},{"q":"Es wird Reformbedarf bei Kriterien und Anerkennung gesehen.","a":0}],"labels":["richtig","falsch","nicht im Text"],"heading":{"q":"Welche Überschrift passt am besten?","o":["Peer Review zwischen Qualitätssicherung und Reformbedarf","Warum wissenschaftliche Zeitschriften verschwinden","Die Geschichte der Universitätsbibliothek"],"a":0}},"languageBlocks":[{"q":"Die Ergebnisse ___ bereits im vergangenen Jahr veröffentlicht ___.","o":["haben / werden","sind / worden","wurden / geworden","sind / geworden"],"a":1,"why":"Perfekt Vorgangspassiv: sein + Partizip II + worden."},{"q":"An der Sitzung ___ ausführlich über die neue Prüfungsordnung diskutiert.","o":["wird worden","hat","ist geworden","wurde"],"a":3,"why":"Unpersönliches Vorgangspassiv."},{"q":"Die Tür ist seit acht Uhr ___.","o":["geschlossen","geschlossen worden","schließen","schloss"],"a":0,"why":"Zustandspassiv: sein + Partizip II."},{"q":"Die Forschenden ___ zu dem Ergebnis, dass weitere Daten nötig sind.","o":["machen","setzen","kommen","führen"],"a":2,"why":"Nomen-Verb-Verbindung: zu dem Ergebnis kommen."},{"q":"Die neue Regelung tritt im Januar in ___.","o":["Gang","Kraft","Folge","Sicht"],"a":1,"why":"Feste Verbindung: in Kraft treten."},{"q":"Die Aussage des Ministers ___ auf heftige Kritik.","o":["stieß","geriet","nahm","setzte"],"a":0,"why":"Feste Verbindung: auf Kritik stoßen."},{"q":"Nach den vorliegenden Daten ___ die Nachfrage in den nächsten Monaten steigen.","o":["soll","will","magst","dürfte"],"a":3,"why":"dürfte = wahrscheinliche Vermutung."},{"q":"Die Ursache ___ in einem technischen Defekt gelegen haben; alle anderen Möglichkeiten wurden ausgeschlossen.","o":["soll","will","muss","kann nur nicht"],"a":2,"why":"muss + Infinitiv Perfekt = starke Schlussfolgerung."},{"q":"Der Konzern ___ bereits seit Monaten von den Problemen gewusst haben. Das berichten mehrere Zeitungen.","o":["soll","muss","will","darf"],"a":0,"why":"soll = Information aus zweiter Hand."},{"q":"Der Zeuge ___ den Vorfall genau beobachtet haben, doch seine Angaben widersprechen sich.","o":["muss","will","darf","sollte"],"a":1,"why":"will = behauptete, vom Sprecher distanzierte Aussage."},{"q":"An Ihrer Stelle ___ ich die Daten vor der Veröffentlichung noch einmal prüfen.","o":["werde","war","wurde","würde"],"a":3,"why":"Konjunktiv II für Rat."},{"q":"Wenn die Finanzierung früher gesichert worden wäre, ___ das Projekt bereits begonnen.","o":["würde","wäre","hätte","sei"],"a":2,"why":"Irrealer Bedingungssatz Vergangenheit: hätte ... begonnen."},{"q":"Der Sprecher erklärte, die Verhandlungen ___ noch nicht abgeschlossen.","o":["sind","seien","wären gewesen","werden"],"a":1,"why":"Konjunktiv I der indirekten Rede."},{"q":"Die Autorin betonte, sie ___ die Daten selbst ausgewertet.","o":["habe","hat","hätte","würde haben"],"a":0,"why":"Indirekte Rede: sie habe ... ausgewertet."},{"q":"___ die Nachfrage stark gestiegen ist, wurde das Angebot erweitert.","o":["Trotz","Wegen","Da","Infolge"],"a":2,"why":"Kausaler Nebensatz mit da."},{"q":"___ des starken Anstiegs der Nachfrage wurde das Angebot erweitert.","o":["Da","Obwohl","Damit","Wegen"],"a":3,"why":"Nominalisierung: wegen + Genitiv."},{"q":"Die Maßnahme ist teuer. ___ könnte sie sich langfristig auszahlen.","o":["Daher","Dennoch","Folglich","Indem"],"a":1,"why":"Dennoch markiert eine Konzession."},{"q":"Die Studie zeigt einen Zusammenhang, ___ sie keine eindeutige Kausalität belegt.","o":["damit","sodass","wobei","deshalb"],"a":2,"why":"wobei kann eine einschränkende Zusatzinformation einleiten."},{"q":"Die Daten wurden anonymisiert, ___ Rückschlüsse auf einzelne Personen verhindert werden.","o":["damit","obwohl","denn","während"],"a":0,"why":"Finalsatz mit damit."},{"q":"Es handelt sich um ein Verfahren, ___ Zuverlässigkeit noch geprüft werden muss.","o":["deren","dem","das","dessen"],"a":3,"why":"Genitiv-Relativpronomen: dessen (Verfahren, Neutrum)."},{"q":"Die Ergebnisse sind nicht nur statistisch signifikant, ___ auch praktisch relevant.","o":["obwohl","sondern","jedoch","denn"],"a":1,"why":"Korrelat: nicht nur ..., sondern auch ..."},{"q":"Je genauer die Kriterien definiert sind, ___ lassen sich die Ergebnisse vergleichen.","o":["so dass besser","obwohl besser","desto besser","damit besser"],"a":2,"why":"Je ..., desto ..."}],"listening1":{"scripts":["Für meine Dissertation brauche ich einen ruhigen Arbeitsplatz. Das neue Großraumbüro ist modern, aber für konzentrierte Analyse ungeeignet.","Ich finde die neue Datenbank grundsätzlich gut, nur die Suchfilter sind so kompliziert, dass ich oft länger brauche als vorher.","Die internationale Summer School war fachlich stark. Besonders wertvoll waren für mich aber die Kontakte zu Forschenden aus anderen Ländern.","Online-Vorlesungen sind praktisch, wenn ich krank bin. Dauerhaft fehlt mir jedoch der direkte Austausch im Seminarraum.","Ich würde gern häufiger mit dem Fahrrad kommen, doch es gibt zu wenige sichere Abstellplätze am Campus.","Die Mensa hat mehr vegane Angebote als früher. Leider sind die Warteschlangen zwischen zwölf und eins inzwischen extrem lang.","Das Schreibzentrum hat mir nicht den Text korrigiert, sondern gezeigt, wie ich meine Argumentation selbst überarbeiten kann. Genau das war hilfreich.","Für den Statistik-Kurs wäre eine kurze Wiederholung der Grundlagen sinnvoll. Viele steigen direkt mit komplexer Software ein und verlieren den Anschluss."],"options":["A Ruhiger Arbeitsplatz fehlt","B Suchsystem schwer bedienbar","C Internationale Kontakte besonders wertvoll","D Präsenz-Austausch bleibt wichtig","E Fahrradinfrastruktur unzureichend","F Lange Wartezeit beim Essen","G Beratung fördert selbstständiges Überarbeiten","H Grundlagen fehlen","I Mehr Prüfungen gewünscht","J Wohnheim zu teuer"],"answers":[0,1,2,3,4,5,6,7]},"listening2":{"script":"Moderator: Frau Stein, Universitäten sprechen viel über interdisziplinäre Forschung. Warum ist sie so schwierig? Expertin: Weil Disziplinen nicht nur unterschiedliche Themen haben, sondern auch unterschiedliche Qualitätskriterien, Methoden und sogar Vorstellungen davon, was als überzeugender Beleg gilt. Moderator: Reicht es, Forschende aus zwei Fächern in ein Projekt zu setzen? Expertin: Nein. Wenn Rollen und Begriffe nicht früh geklärt werden, arbeiten Teams oft parallel statt gemeinsam. Erfolgreiche Projekte investieren am Anfang erstaunlich viel Zeit in gemeinsame Sprache. Moderator: Kostet das nicht Effizienz? Expertin: Kurzfristig ja. Langfristig verhindert es Missverständnisse. Ein zweiter Faktor ist Karrierebewertung. Wer interdisziplinär publiziert, findet manchmal schwerer die “richtige” Fachzeitschrift und wird in traditionellen Bewertungssystemen schlechter eingeordnet. Moderator: Was können Universitäten tun? Expertin: Gemeinsame Infrastruktur schaffen, Moderation finanzieren und bei Berufungs- oder Förderentscheidungen interdisziplinäre Beiträge angemessen anerkennen. Moderator: Ist Interdisziplinarität immer besser? Expertin: Nein. Sie ist sinnvoll, wenn die Forschungsfrage tatsächlich mehrere Perspektiven braucht. Ein Projekt wird nicht automatisch gut, nur weil viele Disziplinen beteiligt sind.","items":[{"q":"Warum ist interdisziplinäre Zusammenarbeit laut Stein anspruchsvoll?","o":["Weil Fächer unterschiedliche Methoden und Gütekriterien haben","Weil Forschende nicht kommunizieren dürfen","Weil nur zwei Fächer erlaubt sind"],"a":0},{"q":"Was reicht nicht aus?","o":["Gemeinsame Begriffe zu entwickeln","Menschen aus mehreren Fächern zusammenzusetzen","Rollen früh zu klären"],"a":1},{"q":"Wofür investieren erfolgreiche Teams am Anfang Zeit?","o":["Für gemeinsame Sprache und Begriffe","Nur für Budgetplanung","Für Publikation nach Projektende"],"a":0},{"q":"Wie bewertet Stein diese Anfangsinvestition?","o":["Kurzfristig aufwendig, langfristig nützlich","Völlig unnötig","Nur für große Unternehmen wichtig"],"a":0},{"q":"Welches Karriereproblem nennt sie?","o":["Interdisziplinäre Arbeit passt schlecht in traditionelle Bewertung","Es gibt zu viele Professuren","Publikationen sind verboten"],"a":0},{"q":"Was können Universitäten finanzieren?","o":["Moderation und gemeinsame Infrastruktur","Nur Einzelbüros","Private Reisen ohne Bezug"],"a":0},{"q":"Was soll bei Entscheidungen anerkannt werden?","o":["Interdisziplinäre Beiträge","Nur Anzahl der Arbeitsstunden","Alter der Forschenden"],"a":0},{"q":"Ist Interdisziplinarität immer überlegen?","o":["Ja","Nein","Nur im ersten Projektjahr"],"a":1},{"q":"Wann ist sie besonders sinnvoll?","o":["Wenn die Frage mehrere Perspektiven erfordert","Wenn ein Projekt wenig Zeit hat","Wenn keine Methode vorhanden ist"],"a":0},{"q":"Was macht ein Projekt laut Stein nicht automatisch gut?","o":["Viele beteiligte Disziplinen","Klare Begriffe","Passende Forschungsfrage"],"a":0}]},"listening3":{"script":"In meinem Vortrag geht es um wissenschaftliches Schreiben als Prozess. Erstens sollte die Fragestellung vor der eigentlichen Textproduktion präzisiert werden. Eine zu breite Frage führt fast zwangsläufig zu einem oberflächlichen Text. Zweitens lohnt es sich, Literatur nicht nur nach Themen, sondern nach Funktion zu ordnen: Welche Quelle liefert Theorie, welche Methode, welche Gegenposition? Drittens empfehle ich, eine Arbeitsgliederung früh anzulegen, sie aber nicht als unveränderlich zu behandeln. Beim Schreiben entstehen neue Zusammenhänge, die eine Umstrukturierung sinnvoll machen können. Viertens sollte die Überarbeitung in mehreren Durchgängen erfolgen. Inhaltliche Logik, Absatzstruktur und sprachliche Korrektheit sind unterschiedliche Ebenen; wer alles gleichzeitig korrigieren will, übersieht leicht Probleme. Fünftens ist Feedback besonders nützlich, wenn die schreibende Person konkrete Fragen stellt. “Ist der Text gut?” führt selten zu hilfreichen Antworten. “Ist die Verbindung zwischen Abschnitt zwei und drei nachvollziehbar?” ist wesentlich produktiver. Schließlich gehört Quellenmanagement von Beginn an zum Prozess. Fehlende Seitenzahlen oder unklare Dateinamen kurz vor der Abgabe zu rekonstruieren kostet unnötig Zeit.","items":[{"q":"1. Vor dem Schreiben soll die ______ präzisiert werden.","answers":["Fragestellung","Forschungsfrage"]},{"q":"2. Literatur kann nach ihrer ______ im Text geordnet werden.","answers":["Funktion","Rolle"]},{"q":"3. Eine frühe Gliederung soll nicht als ______ betrachtet werden.","answers":["unveränderlich","starr"]},{"q":"4. Neue Zusammenhänge können eine ______ nötig machen.","answers":["Umstrukturierung","Neustrukturierung"]},{"q":"5. Überarbeitung sollte in mehreren ______ erfolgen.","answers":["Durchgängen","Schritten"]},{"q":"6. Logik, Absatzstruktur und Sprache sind unterschiedliche ______.","answers":["Ebenen"]},{"q":"7. Für gutes Feedback sollte man ______ Fragen stellen.","answers":["konkrete","präzise"]},{"q":"8. Die Verbindung zwischen Abschnitten ist ein Beispiel für eine ______ Feedbackfrage.","answers":["konkrete","präzise"]},{"q":"9. Quellenmanagement soll von ______ an erfolgen.","answers":["Beginn","Anfang"]},{"q":"10. Fehlende Seitenzahlen kurz vor Abgabe kosten unnötig ______.","answers":["Zeit"]}]},"writingPrompts":[{"title":"Digitale Lehrmaterialien an Hochschulen","prompt":"Erörtern Sie, ob Hochschulen gedruckte Pflichtmaterialien weitgehend durch digitale Materialien ersetzen sollten. Berücksichtigen Sie Lernqualität, Kosten/Zugang, Nachhaltigkeit und Ihre eigene Position."},{"title":"Bewertung wissenschaftlicher Leistung","prompt":"Nehmen Sie Stellung dazu, ob wissenschaftliche Leistung stärker nach gesellschaftlicher Wirkung statt nach Publikationszahlen bewertet werden sollte. Gehen Sie auf Chancen, Probleme, Beispiele und eine mögliche Lösung ein."}],"speaking":{"presentationTopics":["Sollten Vorlesungen grundsätzlich aufgezeichnet werden?","Wie verändert künstliche Intelligenz wissenschaftliches Arbeiten?"],"summaryGuide":"Fassen Sie die Präsentation Ihres Partners bzw. Ihrer Partnerin in etwa 30–60 Sekunden zusammen: Hauptthese, zwei wesentliche Punkte und Schluss. Stellen Sie anschließend mindestens eine passende Anschlussfrage.","discussionQuote":"„Eine Universität sollte nicht Wissen vermitteln, sondern vor allem lehren, wie man Wissen kritisch prüft.“","discussionPoints":["Erläutern Sie das Zitat.","Begründen Sie, in welchen Punkten Sie zustimmen oder widersprechen.","Führen Sie ein konkretes Beispiel an.","Formulieren Sie eine gemeinsame Schlussfolgerung oder eine klare Differenz."]}},"dtb":{"overview":{"title":"Deutsch-Test für den Beruf C1","writtenMinutes":135,"speakingMinutes":16,"skills":{"reading":60,"listening":60,"writing":60,"speaking":60},"passTotal":144,"passSkill":36,"compensationMin":24},"reading":{"part1":{"people":["Mira möchte wissen, wie sie nach mehreren Jahren Berufserfahrung in eine Leitungsrolle hineinwachsen kann.","Deniz sucht Informationen dazu, wie Unternehmen ihre Arbeitszeiten familienfreundlicher organisieren.","Elif interessiert sich dafür, wie kleine Betriebe Kunden trotz großer Konkurrenz langfristig binden.","Kemal überlegt, ob eine berufliche Weiterbildung während einer Vollzeitstelle realistisch ist.","Seda möchte erfahren, wie Betriebe nachhaltiger einkaufen können, ohne die Kosten völlig aus dem Blick zu verlieren."],"articles":[{"title":"A · Führung lernen statt nur befördert werden","text":"Ein neues Mentoringprogramm begleitet Fachkräfte zwölf Monate lang beim Wechsel in erste Führungsverantwortung. Im Mittelpunkt stehen Delegation, Feedback und schwierige Gespräche."},{"title":"B · Mehr Kunden durch Rabattaktionen?","text":"Eine Studie untersucht, warum kurzfristige Preisnachlässe zwar Umsatz bringen, aber nicht automatisch die Kundenbindung stärken."},{"title":"C · Weiterbildung neben dem Beruf","text":"Mehrere Anbieter setzen auf modulare Abend- und Onlinekurse, die sich mit einer Vollzeitbeschäftigung verbinden lassen. Wichtig sind klare Zeitfenster und Unterstützung durch den Arbeitgeber."},{"title":"D · Nachhaltige Beschaffung mit Augenmaß","text":"Ein Praxisleitfaden zeigt, wie Lieferanten nach Umwelt- und Sozialkriterien bewertet werden können, ohne Wirtschaftlichkeit und Lieferfähigkeit zu vernachlässigen."},{"title":"E · Familienfreundliche Schichtmodelle","text":"Betriebe testen Wunschdienstpläne, Tauschbörsen und verlässliche Kernzeiten. Erste Auswertungen zeigen weniger kurzfristige Ausfälle."},{"title":"F · Wenn Teams zu groß werden","text":"Der Beitrag erläutert, warum sehr große Abteilungen häufiger Kommunikationsprobleme haben und wie Teilteams helfen können."},{"title":"G · Kundentreue im lokalen Handel","text":"Kleine Unternehmen punkten gegenüber Ketten durch persönliche Beratung, schnelle Reklamationsbearbeitung und nachvollziehbare Serviceversprechen."},{"title":"H · Pendeln kostet Energie","text":"Arbeitspsychologen beschreiben Belastungen langer Arbeitswege und mögliche Entlastung durch Homeoffice-Tage."}],"answers":[0,4,6,2,3]},"part2":{"texts":["Sicherheitsinformation: Besucherinnen und Besucher dürfen die Werkstatt nur in Begleitung betreten. Schutzbrillen sind im markierten Produktionsbereich verpflichtend. Mitarbeitende, die dort nur Unterlagen abgeben, müssen ebenfalls eine Schutzbrille tragen. Persönliche Schutzausrüstung liegt am Eingang bereit.","Datenschutzinformation: Kundendaten dürfen ausschließlich in den vorgesehenen Systemen gespeichert werden. Private Cloud-Dienste sind untersagt. Ausdrucke mit personenbezogenen Daten müssen nach Gebrauch in die verschlossenen Datenschutzbehälter gegeben werden. Bei Unsicherheiten ist zunächst die interne Datenschutzstelle zu kontaktieren."],"items":[{"q":"Auch Mitarbeitende, die nur kurz Unterlagen in den Produktionsbereich bringen, brauchen dort eine Schutzbrille.","o":["richtig","falsch"],"a":0},{"q":"Besucher dürfen die Werkstatt allein betreten, wenn sie Schutzkleidung tragen.","o":["richtig","falsch"],"a":1},{"q":"Wo dürfen Kundendaten gespeichert werden?","o":["In jedem verschlüsselten privaten Cloud-Dienst","Nur in den dafür vorgesehenen betrieblichen Systemen","Auf privaten Geräten, wenn sie passwortgeschützt sind"],"a":1},{"q":"Was soll bei einer Unsicherheit zum Datenschutz zuerst geschehen?","o":["Die Daten sofort löschen","Die interne Datenschutzstelle kontaktieren","Den Kunden um eine neue Einwilligung bitten"],"a":1}]},"part3":{"questions":["Ich soll seit Wochen zusätzliche Aufgaben übernehmen. Wie kann ich ansprechen, dass meine Kapazität erreicht ist, ohne unkooperativ zu wirken?","Mein Team arbeitet teils zu Hause, teils im Büro. Informationen gehen verloren. Wie könnten wir die Übergaben verbessern?","Ich würde gern eine berufliche Fortbildung machen, weiß aber nicht, wie ich das mit meiner Arbeitszeit verbinden kann.","Unsere neue Kollegin erhält von verschiedenen Personen widersprüchliche Anweisungen. Was können wir tun?"],"tips":["Vor einem Gespräch mit der Führungskraft würde ich konkrete Beispiele sammeln: Welche Aufgaben kamen hinzu, wie viel Zeit brauchen sie und welche Prioritäten kollidieren? So lässt sich sachlich über Entlastung oder Priorisierung sprechen.","Wir haben für hybride Arbeit ein kurzes digitales Übergabeprotokoll eingeführt. Am Ende des Tages werden offene Punkte, Zuständigkeiten und Fristen in drei Minuten dokumentiert.","Bei uns gibt es eine Lernzeit-Regel: Für anerkannte Fortbildungen können Mitarbeitende monatlich einige Arbeitsstunden nutzen. Frag Personalabteilung oder Betriebsrat, ob es bei euch etwas Ähnliches gibt.","Für die Einarbeitung sollte eine Person die fachliche Koordination übernehmen. Andere Kolleginnen und Kollegen können unterstützen, aber Änderungen werden zuerst mit dieser Person abgestimmt.","Ich würde einfach später ins Büro kommen. Bei mir ist morgens weniger Verkehr, deshalb spare ich viel Zeit.","Unser Team macht jeden Freitag ein gemeinsames Frühstück. Das verbessert die Stimmung, löst aber fachliche Probleme nicht automatisch."],"answers":[0,1,2,3]},"part4":{"text":"Protokoll Bereichsmeeting · Thema Kundenservice. Die Geschäftsführung berichtet, dass die Antwortzeiten im Support zuletzt deutlich gestiegen sind. Ursache seien vor allem unklare Zuständigkeiten bei komplexen Reklamationen. Die Serviceleitung schlägt vor, für solche Fälle eine feste Eskalationsgruppe einzurichten. Die IT weist darauf hin, dass im Ticketsystem bereits eine Funktion zur Priorisierung vorhanden ist, die bisher aber kaum genutzt wird. Beschluss: Die IT aktiviert bis Ende des Monats eine vereinfachte Prioritätsansicht und schult die Teamleitungen. Parallel erstellt die Serviceleitung eine Liste von Fällen, die direkt an die Eskalationsgruppe gehen. Der Vertrieb bittet darum, bei Großkunden weiterhin eine persönliche Rückmeldung innerhalb eines Arbeitstags zu garantieren. Die Geschäftsführung stimmt zu, verlangt aber, dass diese Zusage im CRM sichtbar dokumentiert wird. Für das nächste Quartal soll außerdem geprüft werden, ob wiederkehrende Reklamationsgründe systematisch ausgewertet werden können. Verantwortlich dafür sind Service und Qualitätsmanagement gemeinsam.","items":[{"q":"Was gilt als Hauptgrund für die längeren Antwortzeiten?","o":["Zu wenige Großkunden","Unklare Zuständigkeiten bei schwierigen Reklamationen","Ein Ausfall des Ticketsystems"],"a":1},{"q":"Was soll die IT bis Ende des Monats tun?","o":["Ein völlig neues Ticketsystem kaufen","Eine Prioritätsansicht vereinfachen und Teamleitungen schulen","Alle Reklamationen selbst bearbeiten"],"a":1},{"q":"Was wird für Großkunden beibehalten?","o":["Eine persönliche Rückmeldung innerhalb eines Arbeitstags","Ein Rabatt bei jeder Reklamation","Eine telefonische Hotline rund um die Uhr"],"a":0},{"q":"Wo soll die besondere Zusage für Großkunden dokumentiert werden?","o":["Im CRM","Im Intranet","Nur im Protokoll"],"a":0},{"q":"Wer soll wiederkehrende Reklamationsgründe auswerten?","o":["Vertrieb allein","IT und Geschäftsführung","Service und Qualitätsmanagement gemeinsam"],"a":2}]},"readWrite":{"context":"Teamleitung an Sie: Bitte antworten Sie Frau Kramer. Entschuldigen Sie sich für die verspätete Lieferung. Erklären Sie, dass ein Artikel kurzfristig nicht verfügbar war. Bieten Sie entweder Teillieferung morgen oder komplette Lieferung am Freitag an. Fragen Sie, welche Variante sie bevorzugt.\n\nKundin Frau Kramer: Guten Tag, wir warten seit Montag auf die bestellten Präsentationsmaterialien. Für Donnerstag ist eine wichtige Veranstaltung geplant. Bisher habe ich weder Ware noch eine verlässliche Information erhalten. Bitte teilen Sie mir umgehend mit, wann wir mit der Lieferung rechnen können.","items":[{"q":"Was ist das Hauptproblem der Kundin?","o":["Die Rechnung ist zu hoch","Die Lieferung ist verspätet und der Termin ist kritisch","Sie möchte die Bestellung erweitern"],"a":1},{"q":"Welche zwei Lösungen soll die Antwort anbieten?","o":["Rabatt oder Stornierung","Teillieferung morgen oder vollständige Lieferung am Freitag","Abholung heute oder neue Bestellung nächste Woche"],"a":1}],"task":"Schreiben Sie Frau Kramer eine professionelle E-Mail. Setzen Sie alle Punkte der Teamleitung um und wählen Sie einen angemessenen Grad an Formalität."}},"listening":{"part1":{"conversations":[{"script":"Leiterin: Zwei Kolleginnen sind diese Woche krank. Wir schaffen die Hotline so nicht. Vorgesetzter: Für die nächsten Tage kann das Backoffice jeweils zwei Stunden unterstützen. Bitte erstelle zusätzlich einen Plan, welche Anfragen wirklich sofort bearbeitet werden müssen. Leiterin: Gut, dann haben wir zumindest eine Übergangslösung.","items":[{"q":"Die Teamleiterin sucht eine kurzfristige Lösung für personelle Ausfälle.","o":["richtig","falsch"],"a":0},{"q":"Was soll die Teamleiterin zusätzlich vorbereiten?","o":["Eine Prioritätenliste für Anfragen","Eine externe Stellenausschreibung","Einen Urlaubsplan"],"a":0}]},{"script":"Kollege: Im Lager werden dieselben Fehler immer wieder unterschiedlich dokumentiert. Kollegin: Dann können wir die Ursachen kaum auswerten. Lass uns ein einheitliches Formular testen und nach zwei Wochen schauen, ob es funktioniert. Kollege: Einverstanden, aber bitte so kurz, dass es im Alltag wirklich genutzt wird.","items":[{"q":"Die beiden wollen die Fehlerdokumentation vereinheitlichen.","o":["richtig","falsch"],"a":0},{"q":"Welche Bedingung nennt der Kollege?","o":["Das Formular soll sehr ausführlich sein","Das Formular soll im Alltag schnell nutzbar sein","Nur Führungskräfte sollen es ausfüllen"],"a":1}]},{"script":"Vertrieb: Unsere Bestandskunden bestellen stabil, aber wir gewinnen kaum neue Firmen. Marketing: Dann sollten wir die Testpakete gezielt an Interessenten schicken, die schon auf Messen Kontakt mit uns hatten. Vertrieb: Gute Idee. Ein allgemeiner Rabatt für alle wäre mir zu teuer.","items":[{"q":"Das Unternehmen hat vor allem Schwierigkeiten, neue Firmenkunden zu gewinnen.","o":["richtig","falsch"],"a":0},{"q":"Welche Maßnahme wird bevorzugt?","o":["Allgemeiner Rabatt für alle","Gezielte Testpakete für bereits interessierte Kontakte","Preiserhöhung für Bestandskunden"],"a":1}]}]},"part2":{"scripts":["Ich halte einen Abteilungswechsel nicht für eine Niederlage. Wenn jemand in einem anderen Bereich seine Stärken besser einsetzen kann, profitieren am Ende beide Teams.","Bei jeder Umstrukturierung neue Organigramme zu zeichnen, löst unser eigentliches Problem nicht. Wir müssen zuerst klären, wer welche Entscheidung treffen darf.","Offene Büros funktionieren nur, wenn es Rückzugsräume gibt. Sonst wird aus “mehr Austausch” schnell dauernde Unterbrechung.","Kontinuität ist wichtig, aber nicht um jeden Preis. Wenn Prozesse seit Jahren niemand mehr hinterfragt, wird Stabilität zum Stillstand."],"options":["A Ein Wechsel kann neue berufliche Möglichkeiten eröffnen.","B Kündigung ist meist die beste Lösung.","C Strukturen helfen nur, wenn Zuständigkeiten klar sind.","D Offene Arbeitsformen brauchen auch Rückzugsmöglichkeiten.","E Veränderungen sollten grundsätzlich vermieden werden.","F Zu viel unveränderte Routine kann Fortschritt behindern."],"answers":[0,2,3,5]},"part3":{"script":"Guten Morgen zusammen. Ich möchte kurz die Ergebnisse unseres ersten Halbjahres vorstellen. Der Umsatz liegt sechs Prozent über dem Vorjahreswert. Das liegt allerdings nicht daran, dass wir deutlich mehr Stück verkauft hätten; vielmehr konnten wir bei zwei Produktlinien höhere Preise durchsetzen. Bei den Serviceverträgen haben wir unser Ziel dagegen noch nicht erreicht. Dort fehlen uns vor allem Abschlüsse bei mittelgroßen Kunden. Für das zweite Halbjahr plant der Vertrieb deshalb eine gezielte Kampagne. Positiv ist die Entwicklung bei den Kosten: Durch neue Lieferverträge liegen die Materialkosten niedriger als geplant. Einen allgemeinen Personalabbau wird es nicht geben. In der Logistik brauchen wir sogar zusätzliche Kapazität, weil ab September ein neuer Großkunde beliefert wird. Für alle anderen Bereiche gilt zunächst der aktuelle Stellenplan.","items":[{"q":"Warum ist der Umsatz gestiegen?","o":["Vor allem wegen höherer Stückzahlen","Unter anderem wegen höherer Preise bei zwei Produktlinien","Weil Serviceverträge das Ziel übertroffen haben"],"a":1},{"q":"Wo wurde das Ziel noch nicht erreicht?","o":["Bei Serviceverträgen","Bei Materialkosten","Bei Großkunden in der Logistik"],"a":0},{"q":"Wie haben sich die Materialkosten entwickelt?","o":["Sie liegen unter Plan","Sie liegen deutlich über Plan","Dazu gibt es keine Aussage"],"a":0},{"q":"Was ist beim Personal geplant?","o":["Allgemeiner Abbau","Zusätzliche Kapazität in der Logistik","Neue Stellen in allen Bereichen"],"a":1}]},"part4":{"messages":[{"script":"Hallo, hier ist Frau Berger aus der Personalabteilung. Die Unterweisung morgen beginnt nicht um neun, sondern erst um zehn Uhr. Bitte informieren Sie auch Herrn Yilmaz aus Ihrem Team. Danke.","q":"Was soll getan werden?","o":["Die Unterweisung absagen","Herrn Yilmaz über die neue Uhrzeit informieren","Frau Berger um neun Uhr anrufen"],"a":1},{"script":"Guten Tag, Schneider vom Lieferanten ProPack. Die angekündigten Kartons kommen heute nicht mehr. Wir liefern morgen bis elf Uhr. Bitte prüfen Sie, ob die Anlieferung dann noch in Ihr Zeitfenster passt.","q":"Worum bittet Herr Schneider?","o":["Um Bestätigung des neuen Lieferzeitfensters","Um eine neue Bestellung","Um sofortige Abholung"],"a":0},{"script":"Hi, hier ist Jana. Ich habe die Präsentation für den Kunden fast fertig. Die aktuellen Umsatzzahlen fehlen mir noch. Kannst du mir bitte die Datei aus dem Monatsreport weiterleiten?","q":"Was braucht Jana?","o":["Die aktuelle Umsatzdatei","Eine Kundenadresse","Einen neuen Präsentationstermin"],"a":0},{"script":"Guten Morgen, Arslan hier. Unser Fahrer steht seit zwanzig Minuten am Tor 3, aber die Zufahrt ist gesperrt. Bitte rufen Sie ihn kurz zurück und sagen Sie ihm, welches Tor er nutzen soll.","q":"Was ist zu tun?","o":["Die Lieferung stornieren","Den Fahrer zurückrufen und eine andere Zufahrt nennen","Tor 3 öffnen lassen"],"a":1},{"script":"Hallo, Meier aus dem Einkauf. Für die Besprechung am Nachmittag brauche ich noch den aktuellen Preisvergleich. Wenn Sie ihn bis 14 Uhr ins Projektlaufwerk stellen könnten, wäre das super.","q":"Was erwartet Herr Meier?","o":["Eine neue Preisanfrage","Den Preisvergleich bis 14 Uhr im Projektlaufwerk","Eine Terminverschiebung"],"a":1}]},"hearWrite":{"script":"Guten Tag, hier ist Anja Reuter von der Firma Nordlicht, Telefonnummer 040 731 8842. Es geht um unsere Bestellung 7814. Wir benötigen die 30 Präsentationsständer nicht mehr am Freitag, sondern bereits am Donnerstagvormittag, weil unser Messestand früher aufgebaut wird. Falls das nicht möglich ist, rufen Sie mich bitte heute bis 16 Uhr zurück. Prüfen Sie bitte zuerst, ob der frühere Liefertermin machbar ist, und geben Sie mir dann kurz Bescheid.","reason":{"q":"Grund für den Anruf","o":["Angebot","Bestellung/Liefertermin","Beschwerde"],"a":1},"expected":{"name":"Anja Reuter","phone":"040 731 8842","info":["Bestellung 7814","30 Präsentationsständer","Donnerstagvormittag","Messestand früher aufgebaut"],"todo":"früheren Liefertermin prüfen und Rückmeldung geben"}}},"languageWriting":{"blocks1":{"text":"Betreff: Starttermin und Dienstreise\nSehr geehrte Frau Lorenz, vielen Dank für Ihre Nachricht. ___ habe ich meinen bisherigen Arbeitgeber über den geplanten Wechsel informiert. Er wäre bereit, auf einen Teil der Kündigungsfrist zu ___. Allerdings habe ich für die erste Oktoberwoche bereits seit Monaten eine Reise ___. Ich würde diese nur ungern ___. Könnten Sie mir bitte mitteilen, unter welchen ___ eine Verschiebung meines Starttermins möglich wäre? Gerne komme ich dafür noch einmal zu einem persönlichen ___ vorbei.","options":["Bedingungen","gebucht","Gespräch","inzwischen","stornieren","verzichten","bestätigen","kaum","Rückfragen","Voraussetzung"],"answers":[3,5,1,4,0,2]},"blocks2":{"text":"Interne Nachricht: ___ verzögert sich die Freigabe unseres neuen Katalogs. Wenn wir den Kunden nicht bis nächste Woche ___, müssen wir den Zeitplan anpassen. ___ ist das zwar unangenehm, aber wir sollten die zusätzlichen Abstimmungen ___. Bitte gib mir kurz Bescheid, ___ mit dem Designteam so organisieren lässt und ___ wir die Druckerei informieren sollen.","items":[{"q":"Lücke 1","o":["Wie befürchtet","Als befürchten","Mit Befürchtung"],"a":0},{"q":"Lücke 2","o":["vertrösten können","zu vertrösten haben","vertröstet wollen"],"a":0},{"q":"Lücke 3","o":["Aus meiner Sicht","Zu meiner Sicht","Von meiner Sicht"],"a":0},{"q":"Lücke 4","o":["in Kauf nehmen","in Anspruch nehmen","außer Kraft setzen"],"a":0},{"q":"Lücke 5","o":["ob sich das","wann ihr das","warum dies"],"a":0},{"q":"Lücke 6","o":["wann","obwohl","sobald"],"a":0}]},"statementPrompts":[{"title":"Verbindlicher Weiterbildungstag","prompt":"Die Geschäftsführung erwägt, für alle Mitarbeitenden pro Quartal einen verpflichtenden Weiterbildungstag einzuführen. Wägen Sie Vor- und Nachteile ab, nennen Sie passende Beispiele, legen Sie Ihren Standpunkt dar und ziehen Sie ein Fazit."},{"title":"Feste Präsenztage für alle Teams","prompt":"Die Geschäftsführung plant, zwei feste Präsenztage pro Woche für alle Teams einzuführen. Wägen Sie Vor- und Nachteile ab, nennen Sie passende Beispiele, legen Sie Ihren Standpunkt dar und ziehen Sie ein Fazit."}]},"speaking":{"topics":["Welche Eigenschaften sollte eine gute Führungskraft haben?","Welche Rolle spielt Weiterbildung im Berufsleben?","Homeoffice: Welche Chancen und Grenzen sehen Sie?","Wie können Besprechungen effizienter werden?","Was macht gute Zusammenarbeit in internationalen Teams aus?","Wie wichtig ist Feedback am Arbeitsplatz?","Sollten Unternehmen flexible Arbeitszeiten stärker fördern?","Wie verändert künstliche Intelligenz den Arbeitsalltag?","Welche Bedeutung hat Nachhaltigkeit für Unternehmen?","Wie kann die Einarbeitung neuer Kolleginnen und Kollegen verbessert werden?","Was hilft gegen Stress im Berufsalltag?","Wie wichtig ist guter Kundenservice für den Erfolg eines Unternehmens?"],"examinerQuestions":["Können Sie ein konkretes Beispiel nennen?","Welche Nachteile könnte Ihre Position haben?","Wie ist die Situation in einem Betrieb, den Sie kennen?","Was würden Sie einer Führungskraft konkret empfehlen?"],"smallTalk":["Arbeitsweg und Pendeln","Pausengestaltung im Arbeitsalltag","Sport und Bewegung nach der Arbeit","Kinderbetreuung und Arbeitszeiten","Mittagessen im Betrieb","Urlaubsplanung im Team"],"problems":[{"title":"Falsche Lieferung an wichtigen Kunden","text":"Ein wichtiger Kunde hat die falsche Ware erhalten und braucht die richtige Lieferung spätestens morgen. Besprechen Sie Sofortmaßnahmen, Kundenkommunikation, interne Ursachenklärung und langfristige Verbesserungen."},{"title":"Neue Kollegin ohne klare Einarbeitung","text":"Eine neue Kollegin erhält widersprüchliche Informationen und macht deshalb Fehler. Besprechen Sie kurzfristige Unterstützung, Zuständigkeiten, einen Einarbeitungsplan und langfristige Verbesserungen."},{"title":"Viele Beschwerden über lange Antwortzeiten","text":"Der Kundenservice erhält zunehmend Beschwerden über langsame Rückmeldungen. Besprechen Sie Prioritäten, Aufgabenverteilung, Kommunikation mit Kunden und nachhaltige Prozessverbesserungen."}]}}};
